    if (!a) { const d = ROLES_DEF.find(x => x[0] === r); return d ? d[2].indexOf(mod) >= 0 : true; }
    let mods = a.modulos; if (typeof mods === 'string') { try { mods = JSON.parse(mods); } catch (e) { mods = []; } }
    return (mods || []).indexOf(mod) >= 0;
