    if (p && p._entidad) { const ent = _clientes.find(c => String(c.id) === String(id)); if (ent) { cerrarModal('nxPosProv'); cerrarModal('nxPosProvs'); abrirEntidad(ent, null); return; } }
    if (p) abrirProv(p);
