  window.nxPosGuardarProv = async function (id, fromCompra) {
    const body = { nombre: (val('pvNom') || '').trim(), rnc: (val('pvRnc') || '').trim() || null, telefono: (val('pvTel') || '').trim() || null, contacto: (val('pvCon') || '').trim() || null, direccion: (val('pvDir') || '').trim() || null, tiempo_entrega_dias: parseInt(val('pvEntrega'), 10) || null };
    if (!body.nombre) { toast('err', 'Pon el nombre del proveedor'); return; }
    try {
      let nuevo = null;
      if (id) await getAPI().patch('pos_proveedores', 'id=eq.' + id, body);
      else { const r = await getAPI().post('pos_proveedores', body); nuevo = (r && r[0]) || null; }
      toast('ok', id ? 'Proveedor actualizado' : 'Proveedor agregado', body.nombre);
      cerrarModal('nxPosProvForm');
      _proveedores = await getAPI().get('pos_proveedores', 'select=*&activo=eq.true&order=nombre.asc') || [];
      mergeProvEntidades();
      if (fromCompra === '1') { const h = document.getElementById('compProv'); if (h && nuevo) { h.value = nuevo.id; window.nxCompraProvSync && window.nxCompraProvSync(); } }
      else { const v = document.getElementById('v-pos'); if (v && _posTab === 'compras') renderPOS(v); if (document.getElementById('nxPosProvs')) window.nxPosProveedores(); }
    } catch (e) { toast('err', 'No se pudo guardar', String(e && e.message || e)); }
  };
  window.nxPosProvVer = async function (id) {
    const p = _proveedores.find(x => String(x.id) === String(id)); if (!p) return;
    cerrarModal('nxPosProv');
    let compras = [], pagos = [];
    try { compras = await getAPI().get('pos_compras', 'select=*&proveedor_id=eq.' + id + '&a_credito=eq.true&order=created_at.desc') || []; } catch (e) {}
    try { pagos = await getAPI().get('pos_compra_pagos', 'select=*&proveedor_id=eq.' + id + '&order=fecha.desc') || []; } catch (e) {}
    const totC = compras.reduce((s, c) => s + Number(c.total || 0), 0); const totP = pagos.reduce((s, a) => s + Number(a.monto || 0), 0); const saldo = Math.max(0, totC - totP);
    _cxpByProv[id] = totC; _pagosProvByProv[id] = totP;
    const comprasHTML = compras.length ? compras.map(c => `<div style="display:flex;justify-content:space-between;padding:7px 10px;border-bottom:1px solid #f1f5f9;font-size:11px"><span>#${c.numero || ''} <span style="color:#475569">${(c.fecha || '').slice(0, 10)}</span></span><b style="color:#dc2626">${fmt(c.total)}</b></div>`).join('') : '<div style="color:#475569;font-size:11px;padding:10px">Sin compras a crédito</div>';
    const pagosHTML = pagos.length ? pagos.map(a => `<div style="display:flex;justify-content:space-between;align-items:center;padding:7px 10px;border-bottom:1px solid #f1f5f9;font-size:11px"><span><b style="color:#059669">${fmt(a.monto)}</b> <span style="color:#475569">${(a.fecha || '').slice(0, 10)} · ${esc(a.metodo || '')}</span></span><button aria-label="Eliminar este pago al proveedor" class="btn bsm bghost" onclick="window.nxPosDelPagoProv('${a.id}','${id}')"><i class="ti ti-minus" style="color:#dc2626"></i></button></div>`).join('') : '<div style="color:#475569;font-size:11px;padding:10px">Sin pagos</div>';
    const ov = document.createElement('div'); ov.id = 'nxPosProv'; ov.className = 'overlay open';
    ov.addEventListener('click', e => { if (e.target === ov) ov.remove(); });
    ov.innerHTML = `<div class="modal nxPrForm" style="max-width:460px;max-height:90vh;display:flex;flex-direction:column">
        <div class="mt"><span><i class="ti ti-building-warehouse"></i> ${esc(p.nombre)}</span><button class="nxBack" type="button" onclick="document.getElementById('nxPosProv').remove()"><i class="ti ti-arrow-left"></i> Volver</button></div>
        <div style="overflow-y:auto;flex:1">
          <div style="font-size:11px;color:#475569;margin-bottom:8px">${esc(p.rnc || '')}${p.telefono ? ' · ' + esc(p.telefono) : ''}</div>
          <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-bottom:10px">${kpi('Comprado (créd.)', fmt(totC), '#0f172a')}${kpi('Pagado', fmt(totP), '#059669')}${kpi('Saldo (CxP)', fmt(saldo), saldo > 0 ? '#dc2626' : '#16a34a')}</div>
          ${saldo > 0 ? `<div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;padding:9px;margin-bottom:10px"><div style="font-size:11px;font-weight:800;color:#475569;margin-bottom:6px">REGISTRAR PAGO AL PROVEEDOR</div><div style="display:flex;gap:6px"><input id="provPagoMonto" data-nx-money inputmode="numeric" placeholder="Monto" style="flex:1;min-width:0;padding:9px;border:1.5px solid #e2e8f0;border-radius:9px;font-size:14px"><select id="provPagoMet" style="flex:0 0 auto;padding:9px;border:1.5px solid #e2e8f0;border-radius:9px;font-size:12px;background:#fff"><option>Efectivo</option><option>Transferencia</option><option>Cheque</option></select><button aria-label="Registrar un pago al proveedor" class="btn bc1 bsm" type="button" onclick="window.nxPosPagarProv('${id}')"><i class="ti ti-plus"></i></button></div></div>` : '<div style="text-align:center;color:#16a34a;font-weight:800;font-size:12px;margin-bottom:10px">✓ Sin deuda</div>'}
          <div style="font-size:11px;font-weight:800;color:#475569;margin:8px 0 4px">COMPRAS A CRÉDITO (${compras.length})</div>
          <div style="background:#fff;border:1px solid #e2e8f0;border-radius:10px;overflow:hidden;margin-bottom:8px">${comprasHTML}</div>
          <div style="font-size:11px;font-weight:800;color:#475569;margin:8px 0 4px">PAGOS (${pagos.length})</div>
          <div style="background:#fff;border:1px solid #e2e8f0;border-radius:10px;overflow:hidden">${pagosHTML}</div>
        </div>
        <div class="fe" style="margin-top:10px;gap:8px"><button class="btn bsm bghost" type="button" onclick="window.nxPosEditProv('${id}')"><i class="ti ti-edit"></i> Editar</button><button class="btn bsm bghost" type="button" style="color:#dc2626" onclick="window.nxPosDelProv('${id}')"><i class="ti ti-minus"></i> Borrar</button></div>
      </div>`;
    document.body.appendChild(ov);
    scanMoney(ov);
  };
  window.nxPosPagarProv = async function (id) {
    const monto = parseMoney(val('provPagoMonto')); if (monto <= 0) { toast('err', 'Pon el monto'); return; }
    const metodo = val('provPagoMet') || 'Efectivo';
    try {
      const rpg = await getAPI().post('pos_compra_pagos', { proveedor_id: id, monto: monto, metodo: metodo, numero: await nextSeq('pago_prov'), created_by_name: nomAdmin() });
      const pagoId = rpg && rpg[0] && rpg[0].id;
      _pagosProvByProv[id] = (_pagosProvByProv[id] || 0) + monto;
      // Asiento: Debe CxP (2101) / Haber Caja o Banco
      try {
        const byc = await ctasMap();
        if (Object.keys(byc).length) {
          const pn = (_proveedores.find(p => String(p.id) === String(id)) || {}).nombre || '';
          const ln = [lnCta(byc, '2101', 'Cuentas por pagar', monto, 0), lnCta(byc, metodo === 'Efectivo' ? '1101' : '1102', metodo === 'Efectivo' ? 'Caja' : 'Banco', 0, monto)];
          await postAsientoConcepto(isoHoy(), 'Pago a proveedor' + (pn ? ' ' + pn : ''), 'pago_prov', pagoId || null, ln);
        }
      } catch (e) {}
      toast('ok', 'Pago registrado', fmt(monto)); window.nxPosProvVer(id);
    } catch (e) { toast('err', 'No se pudo', String(e && e.message || e)); }
  };
  window.nxPosDelPagoProv = async function (pid, provId) { if (!confirm('¿Eliminar este pago? Se revierte su contabilidad.')) return; try { await getAPI().del('pos_compra_pagos', 'id=eq.' + pid); await delAsientoOrigen('pago_prov', pid); toast('ok', 'Pago eliminado'); window.nxPosProvVer(provId); } catch (e) { toast('err', 'No se pudo', String(e && e.message || e)); } };
  window.nxPosDelProv = async function (id) {
    const pp = _proveedores.find(x => String(x.id) === String(id));
    if (pp && pp._entidad) { toast('err', 'Es una Entidad', 'Quítale el rol "Proveedor" desde el módulo Entidades'); return; }
    // REGLAMENTO DE CLIENTES: no se elimina un proveedor al que todavía le debes (cuenta por pagar)
    // sin reconocerlo — mismo criterio que un cliente que debe. Cajero bloqueado, admin autoriza.
    const debeP = pp ? saldoProv(pp) : 0;
    if (debeP > 0) {
      if (!puedeVerMin()) { toast('err', 'Le debes ' + fmt(debeP) + ' a este proveedor', 'Paga la cuenta primero o pide autorización.'); return; }
      if (!confirm('Todavía le debes ' + fmt(debeP) + ' a este proveedor.\n\n¿Eliminarlo de todos modos?')) return;
      try { (window.logAudit || function () {})('POS_PROVEEDOR_ELIMINADO_CON_CXP', (pp.nombre || '') + ' · se le debía ' + fmt(debeP), 'POS'); } catch (e) {}
    } else if (!confirm('¿Eliminar este proveedor?')) return;
    try { await getAPI().patch('pos_proveedores', 'id=eq.' + id, { activo: false }); toast('ok', 'Proveedor eliminado'); cerrarModal('nxPosProv'); _proveedores = await getAPI().get('pos_proveedores', 'select=*&activo=eq.true&order=nombre.asc') || []; mergeProvEntidades(); const v = document.getElementById('v-pos'); if (v) renderPOS(v); if (document.getElementById('nxPosProvs')) window.nxPosProveedores(); } catch (e) { toast('err', 'No se pudo', String(e && e.message || e)); }
  };

  // ── TAB: CAJA (apertura / arqueo / cierre) ──
  function renderCaja() {
    try { window.nxPfEnsureCSS(); } catch (e) {}
    const cierresHTML = _cierres.length ? _cierres.map(c => `<tr onclick="window.nxPosVerCierre('${c.id}')" style="cursor:pointer" tabindex="0" onkeydown="if(event.keyCode==13||event.keyCode==32){event.preventDefault();this.click()}"><td style="font-size:10px">${fechaDMY(c.cierre)}</td><td style="text-align:right">${fmt(c.efectivo_esperado)}</td><td style="text-align:right;color:${Number(c.descuadre) < 0 ? 'var(--pf-red)' : Number(c.descuadre) > 0 ? 'var(--pf-orange)' : 'var(--pf-green)'};font-weight:700">${Number(c.descuadre) > 0 ? '+' : ''}${fmt(c.descuadre)}</td></tr>`).join('') : '<tr><td colspan="3" style="text-align:center;color:var(--pf-txt3);font-size:11px;padding:14px">Sin cierres aún</td></tr>';
    const histo = `<div style="font-size:11px;font-weight:800;color:var(--pf-txt2);margin:14px 0 4px">CIERRES RECIENTES</div><div class="tw" style="font-size:11px"><table style="width:100%"><thead><tr><th>Fecha cierre</th><th style="text-align:right">Esperado</th><th style="text-align:right">Descuadre</th></tr></thead><tbody>${cierresHTML}</tbody></table></div>`;
    if (!_caja) {
      return `<div class="nxPf nxCajaWrap"><div class="cajaCard" style="max-width:420px">
          <div style="text-align:center;padding:6px 0 12px"><i class="ti ti-lock" style="font-size:34px;color:var(--pf-txt3)"></i><div style="font-weight:800;color:var(--pf-txt);margin-top:6px">Caja cerrada</div><div style="font-size:11px;color:var(--pf-txt2)">Abre la caja para empezar el turno.</div></div>
          <div class="fr nxPrForm" style="display:block"><label style="font-size:11px;font-weight:700;color:var(--pf-txt2);display:block;margin-bottom:4px">Monto inicial (fondo)</label><input id="cajaIni" data-nx-money inputmode="numeric" placeholder="0" style="width:100%;padding:10px;border:1.5px solid var(--pf-line);border-radius:10px;font-size:14px;box-sizing:border-box;outline:none"></div>
          <button class="btn bc1" type="button" style="width:100%;margin-top:10px" onclick="window.nxPosAbrirCaja()"><i class="ti ti-lock-open"></i> Abrir caja</button>
        </div>${histo}</div>`;
    }
    const tt = _cajaTot || { efe: 0, tar: 0, tra: 0, cre: 0, abEfe: 0, ent: 0, sal: 0, esperado: Number(_caja.monto_inicial || 0), movs: [], nventas: 0 };
    const movsHTML = (tt.movs || []).length ? tt.movs.map(m => `<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;padding:6px 10px;border-bottom:1px solid var(--pf-line);font-size:11px"><div><b style="color:${m.tipo === 'entrada' ? 'var(--pf-green)' : 'var(--pf-red)'}">${m.tipo === 'entrada' ? '+' : '−'}${fmt(m.monto)}</b> <span style="color:var(--pf-txt2)">${esc(m.concepto || m.tipo)}</span></div><button aria-label="Eliminar este movimiento de caja" class="btn bsm bghost" onclick="window.nxPosDelMov('${m.id}')"><i class="ti ti-minus" style="color:var(--pf-red)"></i></button></div>`).join('') : '<div style="color:var(--pf-txt3);font-size:11px;padding:10px">Sin movimientos</div>';
    return `<div class="nxPf nxCajaWrap"><div class="cajaCard">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px"><div><div style="font-weight:800;color:var(--pf-green);font-size:13px"><i class="ti ti-lock-open"></i> Caja ABIERTA</div><div style="font-size:11px;color:var(--pf-txt2)">Desde ${fechaDMY(_caja.apertura)} · Fondo ${fmt(_caja.monto_inicial)} · ${tt.nventas} ventas</div></div></div>
        <div class="kpirow" style="margin-bottom:10px">
          ${kpiPf('Efectivo', fmt(tt.efe), 'var(--pf-green)')}${kpiPf('Tarjeta', fmt(tt.tar), 'var(--pf-purple)')}${kpiPf('Transfer.', fmt(tt.tra), 'var(--pf-purple)')}${kpiPf('Crédito', fmt(tt.cre), 'var(--pf-red)')}${kpiPf('Abonos efec.', fmt(tt.abEfe), 'var(--pf-green)')}
        </div>
        <div class="cajaEsp" style="margin-bottom:10px;display:flex;justify-content:space-between;align-items:center"><span style="font-weight:700;font-size:12px">Efectivo esperado en caja</span><b style="font-size:17px">${fmt(tt.esperado)}</b></div>
        <div style="font-size:11px;font-weight:800;color:var(--pf-txt2);margin:4px 0 4px">MOVIMIENTOS DE EFECTIVO</div>
        <div style="background:var(--pf-panel);border:1px solid var(--pf-line);border-radius:10px;overflow:hidden;margin-bottom:6px">${movsHTML}</div>
        <div style="display:flex;gap:6px;margin-bottom:12px"><button class="btn bsm bghost" type="button" onclick="window.nxPosMovimiento('entrada')"><i class="ti ti-plus"></i> Entrada</button><button class="btn bsm bghost" type="button" onclick="window.nxPosMovimiento('salida')"><i class="ti ti-minus"></i> Salida / Gasto</button></div>
        <button class="btn bc1" type="button" style="width:100%" onclick="window.nxPosCerrarCaja()"><i class="ti ti-lock"></i> Cerrar caja / Arqueo</button>
      </div>${histo}</div>`;
  }
  window.nxPosAbrirCaja = async function () {
    const ini = parseMoney(val('cajaIni'));
    try {
      const r = await getAPI().post('pos_cajas', { monto_inicial: ini, estado: 'abierta', created_by_name: nomAdmin() });
      _caja = (r && r[0]) || null; _cajaTot = _caja ? await totalesCaja(_caja) : null;
      toast('ok', 'Caja abierta', fmt(ini));
      const v = document.getElementById('v-pos'); if (v) renderPOS(v);
    } catch (e) { toast('err', 'No se pudo abrir', String(e && e.message || e)); }
  };
  window.nxPosMovimiento = function (tipo) {
    if (!_caja) return;
    cerrarModal('nxPosMov');
    const ov = document.createElement('div'); ov.id = 'nxPosMov'; ov.className = 'overlay open';
    ov.addEventListener('click', e => { if (e.target === ov) ov.remove(); });
    ov.innerHTML = `<div class="modal nxPrForm" style="max-width:380px"><div class="mt"><span><i class="ti ti-cash"></i> ${tipo === 'entrada' ? 'Entrada de efectivo' : 'Salida / Gasto'}</span><button class="nxBack" type="button" onclick="document.getElementById('nxPosMov').remove()"><i class="ti ti-arrow-left"></i> Volver</button></div>
        <div class="fr"><label>Concepto</label><input id="movConc" class="no-upper" placeholder="${tipo === 'entrada' ? 'Fondo extra, etc.' : 'Pago a proveedor, retiro...'}"></div>
        <div class="fr"><label>Monto</label><input id="movMonto" data-nx-money inputmode="numeric" placeholder="0"></div>
        <div class="fe" style="gap:8px"><button class="btn bghost" type="button" onclick="document.getElementById('nxPosMov').remove()">Cancelar</button><button class="btn bc1" type="button" onclick="window.nxPosAddMov('${tipo}')"><i class="ti ti-check"></i> Registrar</button></div>
      </div>`;
    document.body.appendChild(ov); scanMoney(ov);
  };
  window.nxPosAddMov = async function (tipo) {
    const monto = parseMoney(val('movMonto')); if (monto <= 0) { toast('err', 'Pon el monto'); return; }
    const concepto = (val('movConc') || '').trim() || null;
    try {
      const rmv = await getAPI().post('pos_caja_movimientos', { caja_id: _caja.id, tipo: tipo, concepto: concepto, monto: monto, created_by_name: nomAdmin() });
      const movId = rmv && rmv[0] && rmv[0].id;
      // Asiento: entrada → Debe Caja / Haber Otros ingresos · salida → Debe Gastos varios / Haber Caja
      try {
        const byc = await ctasMap();
        if (Object.keys(byc).length) {
          const ln = tipo === 'entrada' ? [lnCta(byc, '1101', 'Caja', monto, 0), lnCta(byc, '4102', 'Otros ingresos', 0, monto)] : [lnCta(byc, '6104', 'Gastos varios', monto, 0), lnCta(byc, '1101', 'Caja', 0, monto)];
          await postAsientoConcepto(isoHoy(), (tipo === 'entrada' ? 'Entrada de caja' : 'Salida de caja') + (concepto ? ': ' + concepto : ''), 'caja_mov', movId || null, ln);
        }
      } catch (e) {}
      cerrarModal('nxPosMov'); _cajaTot = await totalesCaja(_caja);
      toast('ok', tipo === 'entrada' ? 'Entrada registrada' : 'Salida registrada', fmt(monto));
      const v = document.getElementById('v-pos'); if (v) renderPOS(v);
    } catch (e) { toast('err', 'No se pudo', String(e && e.message || e)); }
  };
  window.nxPosDelMov = async function (id) {
    if (!confirm('¿Eliminar este movimiento?')) return;
    try { await getAPI().del('pos_caja_movimientos', 'id=eq.' + id); await delAsientoOrigen('caja_mov', id); _cajaTot = await totalesCaja(_caja); toast('ok', 'Movimiento eliminado'); const v = document.getElementById('v-pos'); if (v) renderPOS(v); } catch (e) { toast('err', 'No se pudo', String(e && e.message || e)); }
  };
  window.nxPosCerrarCaja = function () {
    if (!_caja || !_cajaTot) return;
    cerrarModal('nxPosCierre');
    const denoms = [2000, 1000, 500, 200, 100, 50, 25, 10, 5, 1];
    const rows = denoms.map(d => `<div style="display:flex;align-items:center;gap:8px;padding:2px 0"><span style="width:54px;font-size:12px;font-weight:700;color:#475569;text-align:right">${d.toLocaleString('en-US')}</span><span style="color:#cbd5e1">×</span><input type="number" inputmode="numeric" min="0" data-den="${d}" value="0" oninput="window.nxPosDenom()" style="width:56px;padding:6px;border:1.5px solid #e2e8f0;border-radius:8px;font-size:13px;text-align:center"><span data-densub="${d}" style="margin-left:auto;font-size:12px;color:#475569">RD$ 0</span></div>`).join('');
    const ov = document.createElement('div'); ov.id = 'nxPosCierre'; ov.className = 'overlay open';
    ov.addEventListener('click', e => { if (e.target === ov) ov.remove(); });
    ov.innerHTML = `<div class="modal nxPrForm" style="max-width:440px;max-height:92vh;display:flex;flex-direction:column">
        <div class="mt"><span><i class="ti ti-lock"></i> Cerrar caja / Arqueo</span><button class="nxBack" type="button" onclick="document.getElementById('nxPosCierre').remove()"><i class="ti ti-arrow-left"></i> Volver</button></div>
        <div style="overflow-y:auto;flex:1">
          <div style="background:#ecfdf5;border:1px solid #bbf7d0;border-radius:10px;padding:9px 12px;margin-bottom:10px;display:flex;justify-content:space-between"><span style="font-weight:700;color:#065f46;font-size:12px">Efectivo esperado</span><b style="color:#065f46;font-size:15px">${fmt(_cajaTot.esperado)}</b></div>
          <div style="font-size:11px;font-weight:800;color:#475569;margin:4px 0 6px">CONTEO DE EFECTIVO (opcional)</div>
          <div id="cierreDenoms" style="display:grid;grid-template-columns:1fr 1fr;gap:4px 14px;margin-bottom:10px">${rows}</div>
          <div class="fr"><label>Efectivo contado</label><input id="cierreContado" inputmode="numeric" value="0" oninput="window.nxPosCierreCalc()" style="font-weight:800"></div>
          <div style="display:flex;justify-content:space-between;align-items:center;background:#f8fafc;border-radius:10px;padding:9px 12px;margin-bottom:10px"><span style="font-weight:700;color:#475569;font-size:12px">Descuadre</span><b id="cierreDesc" style="font-size:15px;color:#16a34a">RD$ 0</b></div>
          <div class="fr"><label>Notas (opcional)</label><input id="cierreNotas" class="no-upper" placeholder="Observaciones del turno"></div>
        </div>
        <div class="fe" style="margin-top:10px;gap:8px"><button class="btn bghost" type="button" onclick="document.getElementById('nxPosCierre').remove()">Cancelar</button><button class="btn bc1" type="button" onclick="window.nxPosConfirmarCierre()"><i class="ti ti-check"></i> Cerrar caja</button></div>
      </div>`;
    document.body.appendChild(ov);
  };
  window.nxPosDenom = function () {
    let sum = 0;
    document.querySelectorAll('#cierreDenoms [data-den]').forEach(inp => { const d = Number(inp.getAttribute('data-den')); const q = Number(inp.value) || 0; const st = d * q; sum += st; const lbl = document.querySelector('#cierreDenoms [data-densub="' + d + '"]'); if (lbl) lbl.textContent = 'RD$ ' + st.toLocaleString('en-US'); });
    const c = document.getElementById('cierreContado'); if (c) c.value = sum.toLocaleString('en-US');
    window.nxPosCierreCalc();
  };
  window.nxPosCierreCalc = function () {
    const esperado = (_cajaTot && _cajaTot.esperado) || 0; const contado = parseMoney(val('cierreContado')); const desc = contado - esperado;
    const el = document.getElementById('cierreDesc'); if (el) { el.textContent = (desc > 0 ? '+' : '') + fmt(desc); el.style.color = desc < 0 ? '#dc2626' : desc > 0 ? '#ea580c' : '#16a34a'; }
  };
  window.nxPosConfirmarCierre = async function () {
    if (!_caja || !_cajaTot) return;
    const tt = _cajaTot; const contado = parseMoney(val('cierreContado')); const desc = contado - tt.esperado;
    const body = { estado: 'cerrada', cierre: new Date().toISOString(), ventas_efectivo: tt.efe, ventas_tarjeta: tt.tar, ventas_transferencia: tt.tra, ventas_credito: tt.cre, abonos_efectivo: tt.abEfe, entradas: tt.ent, salidas: tt.sal, efectivo_esperado: tt.esperado, efectivo_contado: contado, descuadre: desc, notas: (val('cierreNotas') || '').trim() || null };
    try {
      await getAPI().patch('pos_cajas', 'id=eq.' + _caja.id, body);
      // Asiento del descuadre: faltante → Debe Gastos varios / Haber Caja · sobrante → Debe Caja / Haber Otros ingresos
      try {
        if (Math.round(desc) !== 0) {
          const byc = await ctasMap();
          if (Object.keys(byc).length) {
            const a = Math.abs(desc);
            const ln = desc < 0 ? [lnCta(byc, '6104', 'Gastos varios', a, 0), lnCta(byc, '1101', 'Caja', 0, a)] : [lnCta(byc, '1101', 'Caja', a, 0), lnCta(byc, '4102', 'Otros ingresos', 0, a)];
            await postAsientoConcepto(isoHoy(), 'Descuadre cierre de caja (' + (desc < 0 ? 'faltante' : 'sobrante') + ')', 'cierre_caja', _caja.id, ln);
          }
        }
      } catch (e) {}
      const cerrada = Object.assign({}, _caja, body, { monto_inicial: _caja.monto_inicial });
      toast('ok', 'Caja cerrada', 'Descuadre ' + (desc > 0 ? '+' : '') + fmt(desc));
      cerrarModal('nxPosCierre');
      const movs = (tt.movs || []).slice();
      _caja = null; _cajaTot = null;
      try { _cierres = await getAPI().get('pos_cajas', 'select=*&estado=eq.cerrada&order=cierre.desc&limit=10') || []; } catch (e) {}
      const v = document.getElementById('v-pos'); if (v) renderPOS(v);
      imprimirCierre(cerrada, movs);
    } catch (e) { toast('err', 'No se pudo cerrar', String(e && e.message || e)); }
  };
  window.nxPosVerCierre = async function (id) {
    let c = _cierres.find(x => String(x.id) === String(id));
    if (!c) { try { const r = await getAPI().get('pos_cajas', 'select=*&id=eq.' + id); c = r && r[0]; } catch (e) {} }
    if (!c) return;
    let movs = []; try { movs = await getAPI().get('pos_caja_movimientos', 'select=*&caja_id=eq.' + id + '&order=fecha.asc') || []; } catch (e) {}
    imprimirCierre(c, movs);
  };
  function imprimirCierre(c, movs) {
    const e = empInfo();
    const row = (l, v, col) => `<tr><td>${l}</td><td style="text-align:right${col ? ';color:' + col : ''}">${fmt(v)}</td></tr>`;
    const movHTML = (movs || []).length ? movs.map(m => `<tr><td>${m.tipo === 'entrada' ? '➕' : '➖'} ${esc(m.concepto || m.tipo)}</td><td style="text-align:right;color:${m.tipo === 'entrada' ? '#059669' : '#dc2626'}">${m.tipo === 'entrada' ? '+' : '−'}${fmt(m.monto)}</td></tr>`).join('') : '';
    const desc = Number(c.descuadre || 0);
    const html = `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cierre de caja</title>
      <style>body{font-family:Segoe UI,system-ui,-apple-system,sans-serif;color:#1e293b;max-width:420px;margin:0 auto;padding:18px;font-size:13px}h1{font-size:17px;text-align:center;margin:0}.muted{color:#475569;font-size:11px;text-align:center}table{width:100%;border-collapse:collapse;margin:8px 0}td{padding:6px 4px;border-bottom:1px solid #eef2f6}.tit{font-size:11px;font-weight:800;color:#475569;margin:10px 0 2px}.big td{font-size:15px;font-weight:800}@media print{.noprint{display:none}body{padding:0}}</style></head>
      <body>
        <div class="noprint" style="position:sticky;top:0;display:flex;gap:8px;background:#1e3a6e;margin:-18px -18px 12px;padding:10px 14px"><button onclick="window.close()" style="background:rgba(255,255,255,.16);color:#fff;border:none;border-radius:8px;padding:8px 14px;font-weight:700;cursor:pointer">✕ Cerrar</button></div>
        <h1>📋 Cierre de Caja</h1>
        <div class="muted">${esc(e.nom)} · ${c.created_by_name ? esc(c.created_by_name) + ' · ' : ''}${fechaDMY(c.cierre)}</div>
        <div class="muted">Apertura: ${fechaDMY(c.apertura)}</div>
        <div class="tit">VENTAS DEL TURNO</div>
        <table>
          ${row('Efectivo', c.ventas_efectivo)}${row('Tarjeta', c.ventas_tarjeta)}${row('Transferencia', c.ventas_transferencia)}${row('Crédito', c.ventas_credito, '#dc2626')}${row('Abonos en efectivo', c.abonos_efectivo, '#059669')}
        </table>
        <div class="tit">EFECTIVO</div>
        <table>
          ${row('Fondo inicial', c.monto_inicial)}${row('+ Ventas efectivo', c.ventas_efectivo)}${row('+ Abonos efectivo', c.abonos_efectivo)}${row('+ Entradas', c.entradas)}${row('− Salidas/Gastos', c.salidas)}
          <tr class="big"><td>Efectivo esperado</td><td style="text-align:right">${fmt(c.efectivo_esperado)}</td></tr>
          <tr class="big"><td>Efectivo contado</td><td style="text-align:right">${fmt(c.efectivo_contado)}</td></tr>
          <tr class="big"><td>Descuadre</td><td style="text-align:right;color:${desc < 0 ? '#dc2626' : desc > 0 ? '#ea580c' : '#16a34a'}">${desc > 0 ? '+' : ''}${fmt(desc)}</td></tr>
        </table>
        ${movHTML ? '<div class="tit">MOVIMIENTOS</div><table>' + movHTML + '</table>' : ''}
        ${c.notas ? '<div class="muted" style="text-align:left;margin-top:6px">📝 ' + esc(c.notas) + '</div>' : ''}
        <button class="noprint" onclick="window.print()" style="width:100%;padding:12px;margin-top:16px;background:#1e3a6e;color:#fff;border:none;border-radius:10px;font-weight:700;cursor:pointer">🖨️ Imprimir</button>
      </body></html>`;
    try { const w = window.open('', '_blank'); if (!w) { toast('warn', 'Permite las ventanas emergentes para ver el cierre'); return; } w.document.write(html); w.document.close(); } catch (er) {}
  }

  // ════════════════════════════════════════════════════════════════════
  // ── MÓDULO CONTABILIDAD (POS / multiempresa) ──
  // Plan de cuentas, Libro Diario, Mayor, Balance de comprobación,
  // Estado de Resultados y Balance General. Asientos automáticos desde ventas.
  // ════════════════════════════════════════════════════════════════════
  const PLAN_BASE = [
    ['1101', 'Caja', 'activo', 'deudora'],
    ['1102', 'Banco', 'activo', 'deudora'],
    ['1103', 'Cuentas por cobrar (clientes)', 'activo', 'deudora'],
    ['1104', 'Inventario de mercancías', 'activo', 'deudora'],
    ['1105', 'ITBIS pagado (adelantado)', 'activo', 'deudora'],
    ['2101', 'Cuentas por pagar (proveedores)', 'pasivo', 'acreedora'],
    ['2102', 'ITBIS por pagar', 'pasivo', 'acreedora'],
    ['2103', 'Sueldos por pagar', 'pasivo', 'acreedora'],
    ['2104', 'Retenciones por pagar (TSS/ISR)', 'pasivo', 'acreedora'],
    ['2105', 'Notas de crédito por aplicar', 'pasivo', 'acreedora'],
    ['3101', 'Capital', 'capital', 'acreedora'],
    ['3102', 'Resultados acumulados', 'capital', 'acreedora'],
    ['4101', 'Ventas', 'ingreso', 'acreedora'],
    ['4102', 'Otros ingresos', 'ingreso', 'acreedora'],
    ['4103', 'Ingresos por mora', 'ingreso', 'acreedora'],
    ['5101', 'Costo de mercancía vendida', 'costo', 'deudora'],
    ['6101', 'Sueldos y salarios', 'gasto', 'deudora'],
    ['6102', 'Alquiler', 'gasto', 'deudora'],
    ['6103', 'Servicios (luz, agua, internet)', 'gasto', 'deudora'],
    ['6104', 'Gastos varios', 'gasto', 'deudora']
  ];
  const TIPO_LBL = { activo: 'Activo', pasivo: 'Pasivo', capital: 'Capital', ingreso: 'Ingreso', costo: 'Costo', gasto: 'Gasto' };

  function isoHoy() { try { return new Date().toLocaleDateString('en-CA'); } catch (e) { return new Date().toISOString().slice(0, 10); } }
  function isoMesIni() { const d = new Date(); return new Date(d.getFullYear(), d.getMonth(), 1).toLocaleDateString('en-CA'); }
  async function cargarContabilidad() {
    _cuentas = await getAPI().get('pos_cuentas', 'select=*&order=codigo.asc') || [];
    _asientos = await getAPI().get('pos_asientos', 'select=*&order=fecha.desc,created_at.desc&limit=600') || [];
    // Unir las líneas en JS (no depende de la detección de relación de PostgREST)
    try {
      const lns = await getAPI().get('pos_asiento_lineas', 'select=*&limit=5000') || [];
      const byA = {}; lns.forEach(l => { (byA[l.asiento_id] = byA[l.asiento_id] || []).push(l); });
      _asientos.forEach(a => { a.lineas = byA[a.id] || []; });
    } catch (e) { _asientos.forEach(a => { a.lineas = a.lineas || []; }); }
    if (!_ctaDesde) _ctaDesde = isoMesIni();
    if (!_ctaHasta) _ctaHasta = isoHoy();
  }
  function ctaById(id) { return _cuentas.find(x => String(x.id) === String(id)); }
  function asLineas(a) { return a.lineas || a.pos_asiento_lineas || []; }
  function enRangoCta(f) { const d = String(f || '').slice(0, 10); if (_ctaDesde && d < _ctaDesde) return false; if (_ctaHasta && d > _ctaHasta) return false; return true; }
  function asientosRango() { return (_asientos || []).filter(a => enRangoCta(a.fecha)); }
  function saldosCta() {
    const m = {};
    _cuentas.forEach(c => { m[c.codigo] = { cuenta: c, debe: 0, haber: 0 }; });
    asientosRango().forEach(a => asLineas(a).forEach(l => {
      let cod = l.cuenta_codigo || ((ctaById(l.cuenta_id) || {}).codigo);
      if (!cod) return;
      if (!m[cod]) { const c = ctaById(l.cuenta_id) || { codigo: cod, nombre: l.cuenta_nombre || cod, tipo: 'gasto', naturaleza: 'deudora' }; m[cod] = { cuenta: c, debe: 0, haber: 0 }; }
      m[cod].debe += Number(l.debito || 0); m[cod].haber += Number(l.credito || 0);
    }));
    return m;
  }
  function saldoNat(o) { const nat = (o.cuenta && o.cuenta.naturaleza) || 'deudora'; return nat === 'deudora' ? o.debe - o.haber : o.haber - o.debe; }
  function sumaPorTipo(saldos, tipo) { let s = 0; Object.values(saldos).forEach(o => { if (o.cuenta && o.cuenta.tipo === tipo) s += saldoNat(o); }); return s; }

  function renderContabilidad() {
    nxPfEnsureCSS();
    if (!_cuentas.length) {
      return `<div style="text-align:center;padding:40px 16px;color:#475569">
        <div style="font-size:42px;margin-bottom:8px"><i class="ti ti-book-2" style="color:#7c3aed"></i></div>
        <div style="font-size:15px;font-weight:800;color:#1e293b;margin-bottom:6px">Contabilidad lista para empezar</div>
        <div style="font-size:12.5px;max-width:420px;margin:0 auto 16px;line-height:1.5">Crea tu <b>Plan de Cuentas</b> base (Caja, Banco, Ventas, ITBIS, Gastos…). Desde ahí podrás registrar asientos y ver tus reportes. Las <b>ventas del POS se contabilizan solas</b>.</div>
        <button class="btn bc1" type="button" onclick="window.nxCtaInicializar()"><i class="ti ti-sparkles"></i> Crear plan de cuentas base</button>
      </div>`;
    }
    const sub = (k, lbl, ic) => `<button type="button" class="nxFacSubTab${_ctaTab === k ? ' on' : ''}" onclick="window.nxCtaTab('${k}')"><i class="ti ${ic}"></i> ${lbl}</button>`;
    const tabs = `<div class="nxFacSubTabs">${sub('resumen', 'Resumen', 'ti-gauge')}${sub('plan', 'Plan de cuentas', 'ti-list-numbers')}${sub('diario', 'Libro Diario', 'ti-book')}${sub('mayor', 'Libro Mayor', 'ti-file-text')}${sub('balanza', 'Comprobación', 'ti-scale')}${sub('resultados', 'Estado Resultados', 'ti-chart-bar')}${sub('general', 'Balance General', 'ti-report-money')}</div>`;
    const imprimible = ['diario', 'balanza', 'resultados', 'general'].indexOf(_ctaTab) >= 0;
    const rango = (_ctaTab === 'plan') ? '' : `<div class="nxCtaRango">
        <div class="nxFacF"><label>Desde</label><input type="date" value="${_ctaDesde}" onchange="window.nxCtaRango('d',this.value)"></div>
        <div class="nxFacF"><label>Hasta</label><input type="date" value="${_ctaHasta}" onchange="window.nxCtaRango('h',this.value)"></div>
        <div style="font-size:11px;color:#475569;align-self:end;padding-bottom:11px">${asientosRango().length} asiento(s)</div>
        ${imprimible ? `<button class="btn bsm bghost" type="button" style="margin-left:auto;align-self:end" onclick="window.nxCtaImprimir('${_ctaTab}')"><i class="ti ti-printer"></i> Imprimir</button>` : ''}
      </div>`;
    let body = '';
    if (_ctaTab === 'plan') body = ctaPlan();
    else if (_ctaTab === 'diario') body = ctaDiario();
    else if (_ctaTab === 'mayor') body = ctaMayor();
    else if (_ctaTab === 'balanza') body = ctaBalanza();
    else if (_ctaTab === 'resultados') body = ctaResultados();
    else if (_ctaTab === 'general') body = ctaGeneral();
    else body = ctaResumen();
    return `<div class="nxPf nxCtaWrap">${tabs}${rango}${body}</div>`;
  }

  // Efectivo real del período = Caja + Banco (cuentas activo por código 1101/1102 o por nombre)
  function ctaEfectivo(s) {
    let t = 0;
    Object.values(s).forEach(o => {
      const c = o.cuenta || {}; if (c.tipo !== 'activo') return;
      if (String(c.codigo) === '1101' || String(c.codigo) === '1102' || /caja|banco/i.test(c.nombre || '')) t += saldoNat(o);
    });
    return t;
  }
  // Flujo mensual real (últimos n meses) — a partir de TODOS los asientos, no del filtro de rango
  function ctaFlujoMeses(n) {
    const tipoDe = {}; _cuentas.forEach(c => { tipoDe[c.codigo] = c.tipo; });
    const hoy = new Date(); const MES = ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'];
    const buckets = [];
    for (let i = n - 1; i >= 0; i--) { const d = new Date(hoy.getFullYear(), hoy.getMonth() - i, 1); buckets.push({ key: d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0'), label: MES[d.getMonth()], ing: 0, gas: 0 }); }
    const idx = {}; buckets.forEach((b, i) => { idx[b.key] = i; });
    (_asientos || []).forEach(a => {
      const k = String(a.fecha || '').slice(0, 7); if (!(k in idx)) return; const b = buckets[idx[k]];
      asLineas(a).forEach(l => {
        const cod = l.cuenta_codigo || ((ctaById(l.cuenta_id) || {}).codigo); const tp = tipoDe[cod]; if (!tp) return;
        const de = Number(l.debito || 0), ha = Number(l.credito || 0);
        if (tp === 'ingreso') b.ing += (ha - de); else if (tp === 'costo' || tp === 'gasto') b.gas += (de - ha);
      });
    });
    buckets.forEach(b => { b.util = b.ing - b.gas; });
    return buckets;
  }
  function ctaFlujoSVG(ms) {
    const W = 320, H = 120, PL = 6, PR = 6, PT = 10, PB = 18;
    const max = Math.max(1, ...ms.reduce((a, b) => a.concat([Math.abs(b.ing), Math.abs(b.gas), Math.abs(b.util)]), []));
    const n = ms.length;
    const x = i => PL + (n <= 1 ? (W - PL - PR) / 2 : i * (W - PL - PR) / (n - 1));
    const mid = PT + (H - PT - PB) / 2; const y = v => mid - (v / max) * ((H - PT - PB) / 2);
    const linea = (key, col) => `<polyline points="${ms.map((b, i) => x(i).toFixed(1) + ',' + y(b[key]).toFixed(1)).join(' ')}" fill="none" stroke="${col}" stroke-width="2.2" stroke-linejoin="round" stroke-linecap="round"/>` + ms.map((b, i) => `<circle cx="${x(i).toFixed(1)}" cy="${y(b[key]).toFixed(1)}" r="2.4" fill="${col}"/>`).join('');
    const labels = ms.map((b, i) => `<text x="${x(i).toFixed(1)}" y="${H - 4}" font-size="8" text-anchor="middle" fill="#94a3b8">${esc(b.label)}</text>`).join('');
    return `<svg class="ctachart" viewBox="0 0 ${W} ${H}" width="100%" preserveAspectRatio="xMidYMid meet"><line x1="${PL}" y1="${y(0).toFixed(1)}" x2="${W - PR}" y2="${y(0).toFixed(1)}" stroke="var(--pf-line)" stroke-width="1" stroke-dasharray="3 3"/>${linea('ing', '#16a34a')}${linea('gas', '#dc2626')}${linea('util', '#2563eb')}${labels}</svg>`;
  }
  function ctaGastosBars(s) {
    const arr = Object.values(s).filter(o => (o.cuenta.tipo === 'costo' || o.cuenta.tipo === 'gasto') && saldoNat(o) > 0).map(o => ({ nombre: o.cuenta.nombre, v: saldoNat(o) })).sort((a, b) => b.v - a.v).slice(0, 6);
    const tot = arr.reduce((a, b) => a + b.v, 0);
    if (!tot) return '<div class="emptyrow">Sin gastos ni costos en el período.</div>';
    return arr.map(g => `<div class="ctabarrow"><div class="nm">${esc(g.nombre)}</div><div class="tr"><div style="width:${Math.round(g.v / tot * 100)}%"></div></div><div class="mo">${fmt(g.v)}</div></div>`).join('');
  }
  function ctaUltMov() {
    const list = (_asientos || []).slice(0, 6);
    if (!list.length) return '<div class="emptyrow">Sin movimientos registrados.</div>';
    return list.map(a => { const ls = asLineas(a); const td = ls.reduce((s, l) => s + Number(l.debito || 0), 0); const orig = (a.tipo && a.tipo !== 'manual') ? a.tipo : ''; return `<div class="ctamov" onclick="window.nxCtaTab('diario')" tabindex="0" onkeydown="if(event.keyCode==13||event.keyCode==32){event.preventDefault();this.click()}" role="button"><div class="mi"><div class="mt">${esc(a.concepto || 'Asiento')}</div><div class="md">${a.numero ? esc(a.numero) + ' · ' : ''}${fechaDMY(a.fecha)}${orig ? ' · ' + esc(orig) : ''}</div></div><div class="mv">${fmt(td)}</div></div>`; }).join('');
  }
  function ctaResumen() {
    const s = saldosCta();
    const ingresos = sumaPorTipo(s, 'ingreso'), costo = sumaPorTipo(s, 'costo'), gasto = sumaPorTipo(s, 'gasto');
    const utilidad = ingresos - costo - gasto;
    const efectivo = ctaEfectivo(s);
    return `<div class="kpirow">
        ${kpiPf('Ingresos del período', fmt(ingresos), '#16a34a')}
        ${kpiPf('Gastos y costos', fmt(costo + gasto), '#dc2626')}
        ${kpiPf(utilidad >= 0 ? 'Utilidad neta' : 'Pérdida neta', fmt(utilidad), utilidad >= 0 ? '#16a34a' : '#dc2626')}
        ${kpiPf('Efectivo (Caja + Banco)', fmt(efectivo), '#2563eb')}
      </div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:2px">
        <button class="btn bsm bc1" type="button" onclick="window.nxCtaGasto()"><i class="ti ti-cash-banknote"></i> Registrar gasto</button>
        <button class="btn bsm bghost" type="button" onclick="window.nxCtaNuevoAsiento()"><i class="ti ti-plus"></i> Nuevo asiento</button>
        <button class="btn bsm bghost" type="button" onclick="window.nxCtaTab('resultados')"><i class="ti ti-chart-bar"></i> Estado de resultados</button>
      </div>
      <div class="ctagrid">
        <div class="card"><h4><i class="ti ti-chart-line" style="color:var(--pf-blue)"></i> Flujo de efectivo <span style="font-weight:600;color:var(--pf-txt3);font-size:11px">· últimos 6 meses</span></h4>
          ${ctaFlujoSVG(ctaFlujoMeses(6))}
          <div class="clgnd"><span><i style="background:#16a34a"></i>Ingresos</span><span><i style="background:#dc2626"></i>Gastos</span><span><i style="background:#2563eb"></i>Utilidad</span></div>
        </div>
        <div class="card"><h4><i class="ti ti-chart-donut" style="color:var(--pf-red)"></i> Distribución de gastos</h4>
          ${ctaGastosBars(s)}
        </div>
      </div>
      <div class="card" style="margin-top:12px"><h4><i class="ti ti-history" style="color:var(--pf-purple)"></i> Últimos movimientos</h4>
        ${ctaUltMov()}
        <div style="margin-top:8px"><button class="btn bsm bghost" type="button" onclick="window.nxCtaTab('diario')"><i class="ti ti-book"></i> Ver libro diario</button></div>
      </div>`;
  }

  function ctaPlan() {
    const filas = _cuentas.map(c => `<tr${c.activo === false ? ' style="opacity:.5"' : ''}>
        <td class="nxFacCod">${esc(c.codigo)}</td>
        <td style="font-weight:600">${esc(c.nombre)}</td>
        <td><span class="nxCtaTipo nxCtaTipo-${c.tipo}">${TIPO_LBL[c.tipo] || c.tipo}</span></td>
        <td style="text-align:center;font-size:11px;color:#475569">${c.naturaleza === 'deudora' ? 'Deudora' : 'Acreedora'}</td>
        <td style="text-align:right;white-space:nowrap"><button aria-label="Editar esta cuenta contable" class="btn bsm bc1" onclick="window.nxCtaEditCuenta('${c.id}')"><i class="ti ti-edit"></i></button></td>
      </tr>`).join('');
    return `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px">
        <button class="btn bsm bc1" type="button" onclick="window.nxCtaNuevaCuenta()"><i class="ti ti-plus"></i> Nueva cuenta</button>
        <span style="font-size:11px;color:#475569;align-self:center">${_cuentas.length} cuentas</span>
      </div>
      <div class="tw" style="font-size:12px"><table style="width:100%"><thead><tr><th>Código</th><th>Cuenta</th><th>Tipo</th><th style="text-align:center">Naturaleza</th><th></th></tr></thead><tbody>${filas}</tbody></table></div>`;
  }

  function ctaDiario() {
    const list = asientosRango();
    if (!list.length) return `<div style="text-align:center;padding:30px;color:#475569;font-size:12.5px">Sin asientos en este período.<br><button class="btn bsm bc1" style="margin-top:10px" onclick="window.nxCtaNuevoAsiento()"><i class="ti ti-plus"></i> Nuevo asiento</button></div>`;
    const bloques = list.map(a => {
      const ls = asLineas(a);
      const td = ls.reduce((s, l) => s + Number(l.debito || 0), 0), th = ls.reduce((s, l) => s + Number(l.credito || 0), 0);
      const filas = ls.map(l => `<tr><td class="nxFacCod">${esc(l.cuenta_codigo || '')}</td><td>${esc(l.cuenta_nombre || (ctaById(l.cuenta_id) || {}).nombre || '')}</td><td style="text-align:right">${Number(l.debito) ? fmt(l.debito) : ''}</td><td style="text-align:right">${Number(l.credito) ? fmt(l.credito) : ''}</td></tr>`).join('');
      const badge = a.tipo === 'venta' ? '<span class="nxCtaOrig">auto · venta</span>' : a.tipo === 'manual' ? '' : `<span class="nxCtaOrig">${esc(a.tipo)}</span>`;
      return `<div class="nxCtaAs">
        <div class="nxCtaAsHd"><div>${a.numero ? '<span class="nxFacCod" style="color:#6d28d9">' + esc(a.numero) + '</span> · ' : ''}<b>${fechaDMY(a.fecha)}</b> · ${esc(a.concepto || 'Asiento')} ${badge}</div>${a.tipo === 'manual' ? `<button class="nxPosX" title="Eliminar" onclick="window.nxCtaDelAsiento('${a.id}')" aria-label="Eliminar"><i class="ti ti-minus" style="color:#dc2626"></i></button>` : ''}</div>
        <table class="nxCtaAsT"><thead><tr><th>Cód.</th><th>Cuenta</th><th style="text-align:right">Debe</th><th style="text-align:right">Haber</th></tr></thead><tbody>${filas}<tr class="nxCtaAsTot"><td></td><td style="text-align:right;font-weight:800">Totales</td><td style="text-align:right;font-weight:800">${fmt(td)}</td><td style="text-align:right;font-weight:800">${fmt(th)}</td></tr></tbody></table>
      </div>`;
    }).join('');
    return `<div style="margin-bottom:10px"><button class="btn bsm bc1" type="button" onclick="window.nxCtaNuevoAsiento()"><i class="ti ti-plus"></i> Nuevo asiento</button></div>${bloques}`;
  }

  function ctaMayor() {
    const opts = _cuentas.map(c => `<option value="${c.id}"${String(_ctaMayorSel) === String(c.id) ? ' selected' : ''}>${esc(c.codigo)} — ${esc(c.nombre)}</option>`).join('');
    let cuerpo = '<div style="text-align:center;padding:24px;color:#475569;font-size:12.5px">Elige una cuenta para ver su movimiento.</div>';
    const c = ctaById(_ctaMayorSel);
    if (c) {
      const movs = [];
      asientosRango().slice().reverse().forEach(a => asLineas(a).forEach(l => {
        const cod = l.cuenta_codigo || ((ctaById(l.cuenta_id) || {}).codigo);
        if (String(cod) === String(c.codigo)) movs.push({ fecha: a.fecha, concepto: a.concepto, debe: Number(l.debito || 0), haber: Number(l.credito || 0) });
      }));
      let saldo = 0;
      const filas = movs.map(m => { saldo += (c.naturaleza === 'deudora' ? (m.debe - m.haber) : (m.haber - m.debe)); return `<tr><td>${fechaDMY(m.fecha)}</td><td>${esc(m.concepto || '')}</td><td style="text-align:right">${m.debe ? fmt(m.debe) : ''}</td><td style="text-align:right">${m.haber ? fmt(m.haber) : ''}</td><td style="text-align:right;font-weight:700">${fmt(saldo)}</td></tr>`; }).join('');
      const td = movs.reduce((s, m) => s + m.debe, 0), th = movs.reduce((s, m) => s + m.haber, 0);
      cuerpo = movs.length ? `<div class="tw" style="font-size:12px"><table style="width:100%"><thead><tr><th>Fecha</th><th>Concepto</th><th style="text-align:right">Debe</th><th style="text-align:right">Haber</th><th style="text-align:right">Saldo</th></tr></thead><tbody>${filas}<tr class="nxCtaAsTot"><td colspan="2" style="text-align:right;font-weight:800">Totales</td><td style="text-align:right;font-weight:800">${fmt(td)}</td><td style="text-align:right;font-weight:800">${fmt(th)}</td><td style="text-align:right;font-weight:800">${fmt(saldo)}</td></tr></tbody></table></div>` : '<div style="text-align:center;padding:24px;color:#475569;font-size:12.5px">Sin movimientos en el período.</div>';
    }
    return `<div class="nxFacF" style="max-width:420px;margin-bottom:12px"><label>Cuenta</label><select onchange="window.nxCtaMayorSel(this.value)"><option value="">— Elegir cuenta —</option>${opts}</select></div>${cuerpo}`;
  }

  function ctaBalanza() {
    const s = saldosCta();
    const arr = Object.values(s).filter(o => o.debe || o.haber).sort((a, b) => String(a.cuenta.codigo).localeCompare(String(b.cuenta.codigo)));
    if (!arr.length) return '<div style="text-align:center;padding:24px;color:#475569;font-size:12.5px">Sin movimientos contables en el período.</div>';
    let TD = 0, TH = 0;
    const filas = arr.map(o => { TD += o.debe; TH += o.haber; return `<tr><td class="nxFacCod">${esc(o.cuenta.codigo)}</td><td>${esc(o.cuenta.nombre)}</td><td style="text-align:right">${fmt(o.debe)}</td><td style="text-align:right">${fmt(o.haber)}</td></tr>`; }).join('');
    const cuadra = Math.round(TD) === Math.round(TH);
    return `<div class="tw" style="font-size:12px"><table style="width:100%"><thead><tr><th>Código</th><th>Cuenta</th><th style="text-align:right">Debe</th><th style="text-align:right">Haber</th></tr></thead><tbody>${filas}<tr class="nxCtaAsTot"><td></td><td style="text-align:right;font-weight:800">TOTALES</td><td style="text-align:right;font-weight:800">${fmt(TD)}</td><td style="text-align:right;font-weight:800">${fmt(TH)}</td></tr></tbody></table></div>
      <div style="text-align:center;margin-top:10px;font-size:12px;font-weight:700;color:${cuadra ? '#16a34a' : '#dc2626'}">${cuadra ? '✓ La balanza cuadra (Debe = Haber)' : '⚠ Descuadre de ' + fmt(Math.abs(TD - TH))}</div>`;
  }

  function ctaResultados() {
    const s = saldosCta();
    const ingArr = Object.values(s).filter(o => o.cuenta.tipo === 'ingreso' && saldoNat(o));
    const cosArr = Object.values(s).filter(o => o.cuenta.tipo === 'costo' && saldoNat(o));
    const gasArr = Object.values(s).filter(o => o.cuenta.tipo === 'gasto' && saldoNat(o));
    const ing = ingArr.reduce((a, o) => a + saldoNat(o), 0);
    const cos = cosArr.reduce((a, o) => a + saldoNat(o), 0);
    const gas = gasArr.reduce((a, o) => a + saldoNat(o), 0);
    const bruta = ing - cos, neta = bruta - gas;
    const sec = (titulo, arr, col) => arr.length ? `<tr class="nxCtaSec"><td colspan="2">${titulo}</td></tr>` + arr.map(o => `<tr><td style="padding-left:18px">${esc(o.cuenta.nombre)}</td><td style="text-align:right;color:${col}">${fmt(saldoNat(o))}</td></tr>`).join('') : '';
    return `<div class="nxCtaRep"><table style="width:100%">
        ${sec('INGRESOS', ingArr, '#16a34a')}
        <tr class="nxCtaTotR"><td>Total ingresos</td><td style="text-align:right">${fmt(ing)}</td></tr>
        ${sec('COSTO DE VENTAS', cosArr, '#dc2626')}
        <tr class="nxCtaTotR"><td>Utilidad bruta</td><td style="text-align:right;color:${bruta >= 0 ? '#16a34a' : '#dc2626'}">${fmt(bruta)}</td></tr>
        ${sec('GASTOS OPERATIVOS', gasArr, '#dc2626')}
        <tr class="nxCtaTotR"><td>Total gastos</td><td style="text-align:right">${fmt(gas)}</td></tr>
        <tr class="nxCtaGran"><td>${neta >= 0 ? 'UTILIDAD NETA' : 'PÉRDIDA NETA'}</td><td style="text-align:right;color:${neta >= 0 ? '#16a34a' : '#dc2626'}">${fmt(neta)}</td></tr>
      </table></div>`;
  }

  function ctaGeneral() {
    const s = saldosCta();
    const ing = sumaPorTipo(s, 'ingreso'), cos = sumaPorTipo(s, 'costo'), gas = sumaPorTipo(s, 'gasto');
    const utilidad = ing - cos - gas;
    const actArr = Object.values(s).filter(o => o.cuenta.tipo === 'activo' && saldoNat(o));
    const pasArr = Object.values(s).filter(o => o.cuenta.tipo === 'pasivo' && saldoNat(o));
    const capArr = Object.values(s).filter(o => o.cuenta.tipo === 'capital' && saldoNat(o));
    const act = actArr.reduce((a, o) => a + saldoNat(o), 0);
    const pas = pasArr.reduce((a, o) => a + saldoNat(o), 0);
    const cap = capArr.reduce((a, o) => a + saldoNat(o), 0);
    const patrimonio = cap + utilidad, pasMasCap = pas + patrimonio;
    const cuadra = Math.round(act) === Math.round(pasMasCap);
    const sec = (titulo, arr) => `<tr class="nxCtaSec"><td colspan="2">${titulo}</td></tr>` + (arr.length ? arr.map(o => `<tr><td style="padding-left:18px">${esc(o.cuenta.nombre)}</td><td style="text-align:right">${fmt(saldoNat(o))}</td></tr>`).join('') : '<tr><td style="padding-left:18px;color:#475569">—</td><td></td></tr>');
    return `<div class="nxCtaRep"><table style="width:100%">
        ${sec('ACTIVOS', actArr)}
        <tr class="nxCtaTotR"><td>Total activos</td><td style="text-align:right">${fmt(act)}</td></tr>
        ${sec('PASIVOS', pasArr)}
        <tr class="nxCtaTotR"><td>Total pasivos</td><td style="text-align:right">${fmt(pas)}</td></tr>
        ${sec('PATRIMONIO / CAPITAL', capArr)}
        <tr><td style="padding-left:18px">Resultado del período</td><td style="text-align:right;color:${utilidad >= 0 ? '#16a34a' : '#dc2626'}">${fmt(utilidad)}</td></tr>
        <tr class="nxCtaTotR"><td>Total patrimonio</td><td style="text-align:right">${fmt(patrimonio)}</td></tr>
        <tr class="nxCtaGran"><td>PASIVO + CAPITAL</td><td style="text-align:right">${fmt(pasMasCap)}</td></tr>
      </table>
      <div style="text-align:center;margin-top:10px;font-size:12px;font-weight:700;color:${cuadra ? '#16a34a' : '#dc2626'}">${cuadra ? '✓ Balance cuadrado (Activo = Pasivo + Capital)' : '⚠ Diferencia de ' + fmt(Math.abs(act - pasMasCap))}</div></div>`;
  }

  // ── Acciones Contabilidad ──
  window.nxCtaTab = function (t) { _ctaTab = t; const v = document.getElementById('v-pos'); if (v) renderPOS(v); };
  window.nxCtaRango = function (k, val) { if (k === 'd') _ctaDesde = val; else _ctaHasta = val; const v = document.getElementById('v-pos'); if (v) renderPOS(v); };
  window.nxCtaMayorSel = function (id) { _ctaMayorSel = id; const v = document.getElementById('v-pos'); if (v) renderPOS(v); };
  window.nxCtaInicializar = async function () {
    if (!esAdmin()) return;
    try {
      const rows = PLAN_BASE.map(p => ({ codigo: p[0], nombre: p[1], tipo: p[2], naturaleza: p[3] }));
      await getAPI().post('pos_cuentas', rows);
      toast('ok', 'Plan de cuentas creado', rows.length + ' cuentas');
      await cargarContabilidad(); const v = document.getElementById('v-pos'); if (v) renderPOS(v);
    } catch (e) { toast('err', 'No se pudo crear el plan', String(e && e.message || e)); }
  };
  window.nxCtaNuevaCuenta = function () { abrirCuenta(null); };
  window.nxCtaEditCuenta = function (id) { const c = ctaById(id); if (c) abrirCuenta(c); };
  function abrirCuenta(c) {
    cerrarModal('nxCtaForm');
    const e = c || {};
    const tipos = ['activo', 'pasivo', 'capital', 'ingreso', 'costo', 'gasto'].map(t => `<option value="${t}"${e.tipo === t ? ' selected' : ''}>${TIPO_LBL[t]}</option>`).join('');
    const ov = document.createElement('div'); ov.id = 'nxCtaForm'; ov.className = 'overlay open';
    ov.addEventListener('click', ev => { if (ev.target === ov) ov.remove(); });
    ov.innerHTML = `<div class="modal" style="max-width:400px">
        <div class="mt"><span><i class="ti ti-list-numbers"></i> ${c ? 'Editar cuenta' : 'Nueva cuenta'}</span><button class="nxBack" type="button" onclick="document.getElementById('nxCtaForm').remove()"><i class="ti ti-arrow-left"></i> Volver</button></div>
        <div class="fr-row">
          <div class="fr"><label>Código *</label><input id="ctC" class="no-upper" value="${esc(e.codigo || '')}" placeholder="Ej: 6105"></div>
          <div class="fr"><label>Tipo</label><select id="ctT">${tipos}</select></div>
        </div>
        <div class="fr"><label>Nombre *</label><input id="ctN" class="no-upper" value="${esc(e.nombre || '')}" placeholder="Nombre de la cuenta"></div>
        <div class="fr-row">
          <div class="fr"><label>Naturaleza</label><select id="ctNat"><option value="deudora"${e.naturaleza !== 'acreedora' ? ' selected' : ''}>Deudora</option><option value="acreedora"${e.naturaleza === 'acreedora' ? ' selected' : ''}>Acreedora</option></select></div>
          <div class="fr"><label>Activa</label><select id="ctA"><option value="1"${e.activo !== false ? ' selected' : ''}>Sí</option><option value="0"${e.activo === false ? ' selected' : ''}>No</option></select></div>
        </div>
        <div class="fe" style="margin-top:8px;gap:8px"><button class="btn bghost" type="button" onclick="document.getElementById('nxCtaForm').remove()">Cancelar</button><button class="btn bc1" type="button" onclick="window.nxCtaGuardarCuenta('${c ? c.id : ''}')"><i class="ti ti-device-floppy"></i> Guardar</button></div>
      </div>`;
    document.body.appendChild(ov);
  }
  window.nxCtaGuardarCuenta = async function (id) {
    const body = { codigo: (val('ctC') || '').trim(), nombre: (val('ctN') || '').trim(), tipo: val('ctT'), naturaleza: val('ctNat'), activo: val('ctA') === '1' };
    if (!body.codigo || !body.nombre) { toast('err', 'Falta código o nombre'); return; }
    try {
      if (id) await getAPI().patch('pos_cuentas', 'id=eq.' + id, body); else await getAPI().post('pos_cuentas', body);
      cerrarModal('nxCtaForm'); toast('ok', 'Cuenta guardada');
      await cargarContabilidad(); const v = document.getElementById('v-pos'); if (v) renderPOS(v);
    } catch (e) { toast('err', 'No se pudo guardar', String(e && e.message || e)); }
  };
  window.nxCtaDelAsiento = async function (id) {
    if (!confirm('¿Eliminar este asiento? Esta acción no se puede deshacer.')) return;
    try { await getAPI().del('pos_asiento_lineas', 'asiento_id=eq.' + id); await getAPI().del('pos_asientos', 'id=eq.' + id); toast('ok', 'Asiento eliminado'); await cargarContabilidad(); const v = document.getElementById('v-pos'); if (v) renderPOS(v); }
    catch (e) { toast('err', 'No se pudo eliminar', String(e && e.message || e)); }
  };

  // ── Registrar gasto rápido (Debe gasto / Haber Caja o Banco) ──
  window.nxCtaGasto = function () {
    const gastos = _cuentas.filter(c => (c.tipo === 'gasto' || c.tipo === 'costo') && c.activo !== false);
    if (!gastos.length) { toast('err', 'No hay cuentas de gasto', 'Crea el plan de cuentas primero'); return; }
    cerrarModal('nxGastoForm');
    const opts = gastos.map(c => `<option value="${c.id}">${esc(c.codigo)} — ${esc(c.nombre)}</option>`).join('');
    const ov = document.createElement('div'); ov.id = 'nxGastoForm'; ov.className = 'overlay open';
    ov.addEventListener('click', ev => { if (ev.target === ov) ov.remove(); });
    ov.innerHTML = `<div class="modal" style="max-width:420px">
        <div class="mt"><span><i class="ti ti-cash-banknote"></i> Registrar gasto</span><button class="nxBack" type="button" onclick="document.getElementById('nxGastoForm').remove()"><i class="ti ti-arrow-left"></i> Volver</button></div>
        <div class="fr"><label>Tipo de gasto *</label><select id="gsC">${opts}</select></div>
        <div class="fr-row">
          <div class="fr"><label>Monto *</label><input id="gsM" data-nx-money inputmode="numeric" placeholder="0"></div>
          <div class="fr"><label>Pagado con</label><select id="gsP"><option value="1101">Caja (efectivo)</option><option value="1102">Banco / transferencia</option></select></div>
        </div>
        <div class="fr"><label>Fecha</label><input type="date" id="gsF" value="${isoHoy()}"></div>
        <div class="fr"><label>Concepto</label><input id="gsD" class="no-upper" placeholder="Ej: Pago de luz de junio"></div>
        <div class="fe" style="margin-top:8px;gap:8px"><button class="btn bghost" type="button" onclick="document.getElementById('nxGastoForm').remove()">Cancelar</button><button class="btn bc1" type="button" onclick="window.nxCtaGuardarGasto()"><i class="ti ti-device-floppy"></i> Guardar</button></div>
      </div>`;
    document.body.appendChild(ov);
    scanMoney(ov);
  };
  window.nxCtaGuardarGasto = async function () {
    const cid = val('gsC'), monto = parseMoney(val('gsM'));
    if (!cid || monto <= 0) { toast('err', 'Elige el gasto y el monto'); return; }
    const cg = ctaById(cid); const pagCod = val('gsP') || '1101'; const cp = _cuentas.find(c => c.codigo === pagCod);
    if (!cg || !cp) { toast('err', 'Faltan cuentas (Caja/Banco)'); return; }
    const conc = (val('gsD') || '').trim() || ('Gasto: ' + (cg.nombre || ''));
    try {
      const aid = await guardarAsientoBalanceado({ numero: await nextSeq('asiento'), fecha: val('gsF') || isoHoy(), concepto: conc, tipo: 'gasto' }, [
        { cuenta_id: cg.id, cuenta_codigo: cg.codigo, cuenta_nombre: cg.nombre, debito: Math.round(monto), credito: 0 },
        { cuenta_id: cp.id, cuenta_codigo: cp.codigo, cuenta_nombre: cp.nombre, debito: 0, credito: Math.round(monto) }
      ]);
      if (!aid) throw new Error('No se pudo registrar el gasto');
      // Si el gasto es en efectivo y hay caja abierta, también baja el efectivo de la caja (arqueo)
      try { if (pagCod === '1101' && _caja && _caja.id) await getAPI().post('pos_caja_movimientos', { caja_id: _caja.id, tipo: 'salida', concepto: conc, monto: Math.round(monto), created_by_name: nomAdmin() }); } catch (e) {}
      cerrarModal('nxGastoForm'); toast('ok', 'Gasto registrado', fmt(monto));
      await cargarContabilidad(); const v = document.getElementById('v-pos'); if (v) renderPOS(v);
    } catch (e) { toast('err', 'No se pudo guardar', String(e && e.message || e)); }
  };

  // ── Imprimir reportes contables ──
  window.nxCtaImprimir = function (tipo) {
    const e = empInfo();
    const titulos = { diario: 'LIBRO DIARIO', balanza: 'BALANCE DE COMPROBACIÓN', resultados: 'ESTADO DE RESULTADOS', general: 'BALANCE GENERAL' };
    let cuerpo = '';
    const s = saldosCta();
    if (tipo === 'balanza') {
      const arr = Object.values(s).filter(o => o.debe || o.haber).sort((a, b) => String(a.cuenta.codigo).localeCompare(String(b.cuenta.codigo)));
      let TD = 0, TH = 0;
      const filas = arr.map(o => { TD += o.debe; TH += o.haber; return `<tr><td>${esc(o.cuenta.codigo)}</td><td>${esc(o.cuenta.nombre)}</td><td class="r">${fmt(o.debe)}</td><td class="r">${fmt(o.haber)}</td></tr>`; }).join('');
      cuerpo = `<table><thead><tr><th>Código</th><th>Cuenta</th><th class="r">Debe</th><th class="r">Haber</th></tr></thead><tbody>${filas}<tr class="tot"><td></td><td class="r">TOTALES</td><td class="r">${fmt(TD)}</td><td class="r">${fmt(TH)}</td></tr></tbody></table>`;
    } else if (tipo === 'resultados') {
      const ingArr = Object.values(s).filter(o => o.cuenta.tipo === 'ingreso' && saldoNat(o));
      const cosArr = Object.values(s).filter(o => o.cuenta.tipo === 'costo' && saldoNat(o));
      const gasArr = Object.values(s).filter(o => o.cuenta.tipo === 'gasto' && saldoNat(o));
      const ing = ingArr.reduce((a, o) => a + saldoNat(o), 0), cos = cosArr.reduce((a, o) => a + saldoNat(o), 0), gas = gasArr.reduce((a, o) => a + saldoNat(o), 0);
      const sec = (t, arr) => (arr.length ? `<tr class="sec"><td colspan="2">${t}</td></tr>` + arr.map(o => `<tr><td class="ind">${esc(o.cuenta.nombre)}</td><td class="r">${fmt(saldoNat(o))}</td></tr>`).join('') : '');
      cuerpo = `<table>${sec('INGRESOS', ingArr)}<tr class="tot"><td>Total ingresos</td><td class="r">${fmt(ing)}</td></tr>${sec('COSTO DE VENTAS', cosArr)}<tr class="tot"><td>Utilidad bruta</td><td class="r">${fmt(ing - cos)}</td></tr>${sec('GASTOS', gasArr)}<tr class="tot"><td>Total gastos</td><td class="r">${fmt(gas)}</td></tr><tr class="gran"><td>${(ing - cos - gas) >= 0 ? 'UTILIDAD NETA' : 'PÉRDIDA NETA'}</td><td class="r">${fmt(ing - cos - gas)}</td></tr></table>`;
    } else if (tipo === 'general') {
      const ing = sumaPorTipo(s, 'ingreso'), cos = sumaPorTipo(s, 'costo'), gas = sumaPorTipo(s, 'gasto'), util = ing - cos - gas;
      const actArr = Object.values(s).filter(o => o.cuenta.tipo === 'activo' && saldoNat(o));
      const pasArr = Object.values(s).filter(o => o.cuenta.tipo === 'pasivo' && saldoNat(o));
      const capArr = Object.values(s).filter(o => o.cuenta.tipo === 'capital' && saldoNat(o));
      const act = actArr.reduce((a, o) => a + saldoNat(o), 0), pas = pasArr.reduce((a, o) => a + saldoNat(o), 0), cap = capArr.reduce((a, o) => a + saldoNat(o), 0);
      const sec = (t, arr) => `<tr class="sec"><td colspan="2">${t}</td></tr>` + (arr.length ? arr.map(o => `<tr><td class="ind">${esc(o.cuenta.nombre)}</td><td class="r">${fmt(saldoNat(o))}</td></tr>`).join('') : '<tr><td class="ind">—</td><td></td></tr>');
      cuerpo = `<table>${sec('ACTIVOS', actArr)}<tr class="tot"><td>Total activos</td><td class="r">${fmt(act)}</td></tr>${sec('PASIVOS', pasArr)}<tr class="tot"><td>Total pasivos</td><td class="r">${fmt(pas)}</td></tr>${sec('PATRIMONIO', capArr)}<tr><td class="ind">Resultado del período</td><td class="r">${fmt(util)}</td></tr><tr class="gran"><td>PASIVO + CAPITAL</td><td class="r">${fmt(pas + cap + util)}</td></tr></table>`;
    } else {
      const list = asientosRango();
      cuerpo = list.map(a => { const ls = asLineas(a); const filas = ls.map(l => `<tr><td>${esc(l.cuenta_codigo || '')}</td><td>${esc(l.cuenta_nombre || '')}</td><td class="r">${Number(l.debito) ? fmt(l.debito) : ''}</td><td class="r">${Number(l.credito) ? fmt(l.credito) : ''}</td></tr>`).join(''); return `<div class="as"><b>${fechaDMY(a.fecha)}</b> · ${esc(a.concepto || '')}<table><thead><tr><th>Cód.</th><th>Cuenta</th><th class="r">Debe</th><th class="r">Haber</th></tr></thead><tbody>${filas}</tbody></table></div>`; }).join('') || '<div style="color:#777">Sin asientos en el período.</div>';
    }
    const html = `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${titulos[tipo] || 'Reporte'}</title>
      <style>body{font-family:Segoe UI,system-ui,-apple-system,sans-serif;color:#111;max-width:720px;margin:0 auto;padding:20px;font-size:12.5px}h1{font-size:16px;text-align:center;margin:0}.c{text-align:center}.muted{color:#555;font-size:11px}table{width:100%;border-collapse:collapse;margin:8px 0}th{text-align:left;font-size:10px;text-transform:uppercase;color:#555;border-bottom:1.5px solid #999;padding:5px 6px}td{padding:4px 6px;border-bottom:1px solid #eee}.r{text-align:right}.tot td{font-weight:800;border-top:1.5px solid #999;border-bottom:none}.gran td{font-weight:800;font-size:14px;border-top:2px solid #111;border-bottom:none}.sec td{font-weight:800;font-size:10px;text-transform:uppercase;color:#555;padding-top:10px}.ind{padding-left:16px}.as{border:1px solid #e2e8f0;border-radius:8px;padding:8px 10px;margin-bottom:8px}.line{border-top:1px solid #ccc;margin:8px 0}@media print{.noprint{display:none}body{padding:0}}</style></head>
      <body>
        <div class="noprint" style="position:sticky;top:0;display:flex;gap:8px;background:#1e3a6e;margin:-20px -20px 14px;padding:9px 14px"><button onclick="window.close()" style="background:rgba(255,255,255,.16);color:#fff;border:none;border-radius:8px;padding:8px 14px;font-weight:700;cursor:pointer">✕ Cerrar</button><button onclick="window.print()" style="background:#fff;color:#1e3a6e;border:none;border-radius:8px;padding:8px 14px;font-weight:700;cursor:pointer">🖨️ Imprimir</button></div>
        <h1>${esc(e.nom)}</h1>
        <div class="c muted">${e.rnc ? 'RNC: ' + esc(e.rnc) : ''}${e.tel ? ' · ' + esc(e.tel) : ''}</div>
        <div class="line"></div>
        <div class="c"><b>${titulos[tipo] || 'Reporte'}</b></div>
        <div class="c muted">Del ${fechaDMY(_ctaDesde)} al ${fechaDMY(_ctaHasta)}</div>
        ${cuerpo}
        <div class="muted" style="margin-top:18px">Generado el ${fechaDMY(isoHoy())} · NEXUS PRO</div>
      </body></html>`;
    try { const w = window.open('', '_blank'); if (!w) { toast('warn', 'Permite las ventanas emergentes para imprimir'); return; } w.document.write(html); w.document.close(); } catch (er) {}
  };

  // ── Editor de asiento manual ──
  window.nxCtaNuevoAsiento = function () {
    _asEdit = { fecha: isoHoy(), concepto: '', lineas: [{ cuenta_id: '', debito: '', credito: '' }, { cuenta_id: '', debito: '', credito: '' }] };
    abrirAsiento();
  };
  function asientoCtaOpts(sel) { return '<option value="">— Cuenta —</option>' + _cuentas.filter(c => c.activo !== false).map(c => `<option value="${c.id}"${String(sel) === String(c.id) ? ' selected' : ''}>${esc(c.codigo)} — ${esc(c.nombre)}</option>`).join(''); }
  function abrirAsiento() {
    cerrarModal('nxAsForm');
    const ov = document.createElement('div'); ov.id = 'nxAsForm'; ov.className = 'overlay open';
    ov.addEventListener('click', ev => { if (ev.target === ov) ov.remove(); });
    ov.innerHTML = `<div class="modal" style="max-width:560px;max-height:92vh;display:flex;flex-direction:column">
        <div class="mt"><span><i class="ti ti-book"></i> Nuevo asiento</span><button class="nxBack" type="button" onclick="document.getElementById('nxAsForm').remove()"><i class="ti ti-arrow-left"></i> Volver</button></div>
        <div class="fr-row">
          <div class="fr"><label>Fecha</label><input type="date" id="asF" value="${_asEdit.fecha}"></div>
          <div class="fr" style="flex:2"><label>Concepto</label><input id="asC" class="no-upper" value="${esc(_asEdit.concepto)}" placeholder="Ej: Pago de alquiler"></div>
        </div>
        <div id="asLineas" style="overflow-y:auto;flex:1"></div>
        <div style="margin-top:6px"><button class="btn bsm bghost" type="button" onclick="window.nxAsAddLinea()"><i class="ti ti-plus"></i> Agregar línea</button></div>
        <div id="asTot" class="nxAsTot"></div>
        <div class="fe" style="margin-top:8px;gap:8px"><button class="btn bghost" type="button" onclick="document.getElementById('nxAsForm').remove()">Cancelar</button><button class="btn bc1" type="button" onclick="window.nxAsGuardar()"><i class="ti ti-device-floppy"></i> Guardar asiento</button></div>
      </div>`;
    document.body.appendChild(ov);
    pintarAsLineas();
  }
  function leerAsLineas() {
    if (!_asEdit) return;
    const wrap = document.getElementById('asLineas'); if (!wrap) return;
    _asEdit.lineas.forEach((l, i) => {
      const cs = wrap.querySelector(`[data-asc="${i}"]`), db = wrap.querySelector(`[data-asd="${i}"]`), cr = wrap.querySelector(`[data-ash="${i}"]`);
      if (cs) l.cuenta_id = cs.value; if (db) l.debito = db.value; if (cr) l.credito = cr.value;
    });
    const f = document.getElementById('asF'), c = document.getElementById('asC');
    if (f) _asEdit.fecha = f.value; if (c) _asEdit.concepto = c.value;
  }
  function pintarAsLineas() {
    const wrap = document.getElementById('asLineas'); if (!wrap || !_asEdit) return;
    wrap.innerHTML = _asEdit.lineas.map((l, i) => `<div class="nxAsRow">
        <select data-asc="${i}" onchange="window.nxAsTotals()">${asientoCtaOpts(l.cuenta_id)}</select>
        <input data-asd="${i}" inputmode="numeric" placeholder="Debe" value="${l.debito || ''}" oninput="window.nxAsTotals()">
        <input data-ash="${i}" inputmode="numeric" placeholder="Haber" value="${l.credito || ''}" oninput="window.nxAsTotals()">
        <button aria-label="Quitar esta línea" class="nxPosX" type="button" onclick="window.nxAsDelLinea(${i})"><i class="ti ti-minus" style="color:#dc2626"></i></button>
      </div>`).join('');
    pintarAsTot();
  }
  function pintarAsTot() {
    const el = document.getElementById('asTot'); if (!el || !_asEdit) return;
    let td = 0, th = 0;
    _asEdit.lineas.forEach(l => { td += Number(l.debito || 0); th += Number(l.credito || 0); });
    const ok = Math.round(td) === Math.round(th) && td > 0;
    el.innerHTML = `<div style="display:flex;justify-content:space-between"><span>Debe: <b>${fmt(td)}</b></span><span>Haber: <b>${fmt(th)}</b></span><span style="color:${ok ? '#16a34a' : '#dc2626'};font-weight:800">${ok ? '✓ cuadra' : 'Diferencia ' + fmt(Math.abs(td - th))}</span></div>`;
  }
  window.nxAsTotals = function () { leerAsLineas(); pintarAsTot(); };
  window.nxAsAddLinea = function () { leerAsLineas(); _asEdit.lineas.push({ cuenta_id: '', debito: '', credito: '' }); pintarAsLineas(); };
  window.nxAsDelLinea = function (i) { leerAsLineas(); if (_asEdit.lineas.length <= 2) { _asEdit.lineas[i] = { cuenta_id: '', debito: '', credito: '' }; } else { _asEdit.lineas.splice(i, 1); } pintarAsLineas(); };
  window.nxAsGuardar = async function () {
    leerAsLineas();
    const lineas = _asEdit.lineas.filter(l => l.cuenta_id && (Number(l.debito) > 0 || Number(l.credito) > 0));
    if (lineas.length < 2) { toast('err', 'El asiento necesita al menos 2 líneas'); return; }
    const td = lineas.reduce((s, l) => s + Number(l.debito || 0), 0), th = lineas.reduce((s, l) => s + Number(l.credito || 0), 0);
    if (Math.round(td) !== Math.round(th)) { toast('err', 'No cuadra', 'El Debe debe ser igual al Haber'); return; }
    try {
      const rows = lineas.map(l => { const c = ctaById(l.cuenta_id) || {}; return { cuenta_id: l.cuenta_id, cuenta_codigo: c.codigo || '', cuenta_nombre: c.nombre || '', debito: Math.round(Number(l.debito || 0)), credito: Math.round(Number(l.credito || 0)) }; });
      const aid = await guardarAsientoBalanceado({ numero: await nextSeq('asiento'), fecha: _asEdit.fecha || isoHoy(), concepto: (_asEdit.concepto || '').trim() || 'Asiento manual', tipo: 'manual' }, rows);
      if (!aid) throw new Error('No se creó el asiento');
      cerrarModal('nxAsForm'); _asEdit = null; toast('ok', 'Asiento registrado');
      await cargarContabilidad(); const v = document.getElementById('v-pos'); if (v) renderPOS(v);
    } catch (e) { toast('err', 'No se pudo guardar', String(e && e.message || e)); }
  };

  // ── Asiento automático desde una venta del POS ──
  async function postAsientoVenta(venta, c) {
    try {
      let cu = _cuentas;
      if (!cu || !cu.length) { try { cu = await getAPI().get('pos_cuentas', 'select=id,codigo,nombre') || []; } catch (e) { cu = []; } }
      if (!cu.length) return; // sin plan de cuentas: no se contabiliza
      const byc = {}; cu.forEach(x => byc[x.codigo] = x);
      const ln = (cod, nom, d, h) => { const x = byc[cod]; if (!x || (Math.round(d) === 0 && Math.round(h) === 0)) return null; return { cuenta_id: x.id, cuenta_codigo: cod, cuenta_nombre: x.nombre || nom, debito: Math.round(d), credito: Math.round(h) }; };
      // A5: la nota de crédito NO es efectivo — no debe entrar a Caja (1101). Si la org tiene
      // la cuenta 2105 (Notas de crédito por aplicar) usa esa; si no existe (plan de cuentas
      // viejo, sin recrear), cae al comportamiento anterior (todo a Caja) para no descuadrar.
      const ncMonto = Number(c.nc || 0);
      const ncCta = byc['2105'] ? '2105' : '1101';
      const caja = Number(c.efe || 0) + Number(c.tar || 0) + Number(c.tra || 0) + Number(c.che || 0) + (ncCta === '1101' ? ncMonto : 0);
      // Costo de ventas (COGS): baja el inventario contable en cada venta (Debe 5101 / Haber 1104).
      // Como pos_venta_items NO guarda costo, se lee de pos_productos.costo.
      let costo = 0;
      try {
        const vitems = await getAPI().get('pos_venta_items', 'select=producto_id,cantidad&venta_id=eq.' + venta.id) || [];
        for (const it of vitems) { const p = _prods.find(x => String(x.id) === String(it.producto_id)); if (p && p.tipo !== 'servicio') costo += Number(p.costo || 0) * Number(it.cantidad || 0); }
      } catch (e) {}
      const lineas = [ln('1101', 'Caja', caja, 0), ncCta === '2105' ? ln('2105', 'Notas de crédito por aplicar', ncMonto, 0) : null, ln('1103', 'Cuentas por cobrar (clientes)', Number(c.credito || 0), 0), ln('4101', 'Ventas', 0, Number(c.subtotal || 0)), ln('2102', 'ITBIS por pagar', 0, Number(c.itbis || 0)), ln('5101', 'Costo de mercancía vendida', costo, 0), ln('1104', 'Inventario de mercancías', 0, costo)].filter(Boolean);
      // Pasa por el motor único: valida Debe=Haber y limpia la cabecera si las líneas fallan.
      await guardarAsientoBalanceado({ numero: await nextSeq('asiento'), fecha: (String(venta.fecha || '').slice(0, 10)) || isoHoy(), concepto: 'Venta ' + (venta.numero_factura || ('No. ' + (venta.numero || ''))), referencia: venta.numero_factura || String(venta.numero || ''), tipo: 'venta', origen_id: venta.id }, lineas);
    } catch (e) {}
  }
  // Cuentas en memoria (carga perezosa) para los asientos automáticos
  async function ctasMap() {
    let cu = _cuentas;
    if (!cu || !cu.length) { try { cu = await getAPI().get('pos_cuentas', 'select=id,codigo,nombre') || []; } catch (e) { cu = []; } }
    const byc = {}; cu.forEach(x => byc[x.codigo] = x); return byc;
  }
  function lnCta(byc, cod, nomDef, d, h) { const x = byc[cod]; if (!x || (Math.round(d) === 0 && Math.round(h) === 0)) return null; return { cuenta_id: x.id, cuenta_codigo: cod, cuenta_nombre: x.nombre || nomDef, debito: Math.round(d), credito: Math.round(h) }; }
  // REGLAMENTO DE CONTABILIDAD: motor ÚNICO por el que pasa TODO asiento (automático o manual).
  // (1) Ningún asiento se guarda si Debe ≠ Haber — antes solo el asiento manual lo validaba; los
  //     automáticos posteaban sus líneas a ciegas, así que un error de redondeo/cálculo dejaba la
  //     contabilidad descuadrada en silencio. Si no cuadra: NO se registra + queda en Auditoría.
  // (2) Ningún asiento queda colgando: si la cabecera se creó pero las líneas fallan, se borra la
  //     cabecera huérfana (antes el catch se lo tragaba y dejaba un asiento sin líneas).
  // Devuelve el id del asiento creado, o null si no se guardó. Las líneas van SIN asiento_id (se
  // les pone aquí, ganando siempre sobre cualquier asiento_id que ya trajeran).
  async function guardarAsientoBalanceado(cab, lineas) {
    lineas = (lineas || []).filter(Boolean); if (lineas.length < 2) return null;
    const td = lineas.reduce((s, l) => s + Number(l.debito || 0), 0), th = lineas.reduce((s, l) => s + Number(l.credito || 0), 0);
    if (Math.round(td) !== Math.round(th)) {
      try { (window.logAudit || function () {})('ASIENTO_DESCUADRADO', (cab && cab.concepto || 'Asiento') + ' · Debe ' + Math.round(td) + ' ≠ Haber ' + Math.round(th) + ' — no se registró', 'Contabilidad'); } catch (e) {}
      return null;
    }
    let aid = null;
    try {
      const as = await getAPI().post('pos_asientos', cab);
      aid = as && as[0] && as[0].id; if (!aid) return null;
      await getAPI().post('pos_asiento_lineas', lineas.map(l => Object.assign({}, l, { asiento_id: aid })));
      return aid;
    } catch (e) {
      if (aid) { try { await getAPI().del('pos_asientos', 'id=eq.' + aid); } catch (e2) {} } // borra la cabecera colgada
      return null;
    }
  }
  async function postAsientoConcepto(fecha, concepto, tipo, origenId, lineas, referencia) {
    await guardarAsientoBalanceado({ numero: await nextSeq('asiento'), fecha: (String(fecha || '').slice(0, 10)) || isoHoy(), concepto: concepto, referencia: referencia || null, tipo: tipo, origen_id: origenId || null }, lineas);
  }
  // Compra: Debe Inventario (+ITBIS adelantado) / Haber Caja o CxP
  async function postAsientoCompra(compra, subtotal, itbis, aCredito) {
    try {
      const byc = await ctasMap(); if (!Object.keys(byc).length) return;
      const monto = Number(subtotal || 0) + Number(itbis || 0);
      const lineas = [lnCta(byc, '1104', 'Inventario de mercancías', Number(subtotal || 0), 0), lnCta(byc, '1105', 'ITBIS pagado (adelantado)', Number(itbis || 0), 0)];
      if (aCredito) lineas.push(lnCta(byc, '2101', 'Cuentas por pagar (proveedores)', 0, monto));
      else lineas.push(lnCta(byc, '1101', 'Caja', 0, monto));
      await postAsientoConcepto(compra.fecha, 'Compra ' + (compra.proveedor_nombre ? 'a ' + compra.proveedor_nombre : ('No. ' + (compra.numero || ''))), 'compra', compra.id, lineas, String(compra.numero || ''));
    } catch (e) {}
  }
  // Abono de cliente (cobro de fiado): Debe Caja/Banco / Haber Cuentas por cobrar
  async function postAsientoAbono(cliNom, monto, metodo, fecha, origenId, moraMonto) {
    try {
      const byc = await ctasMap(); if (!Object.keys(byc).length) return;
      const efe = (metodo || 'Efectivo') === 'Efectivo';
      // Mora cobrada: se reconoce como ingreso aparte (no como parte del abono a la CxC), para
      // que el Estado de Resultados/Libro Mayor muestren cuánta mora se ha cobrado de verdad.
      // Fallback a 4102 "Otros ingresos" si la org no ha resembrado su plan de cuentas con 4103.
      const mora = Math.min(Number(moraMonto || 0), Number(monto || 0));
      const cxc = Number(monto || 0) - mora;
      const moraCod = byc['4103'] ? '4103' : '4102';
      const lineas = [lnCta(byc, efe ? '1101' : '1102', efe ? 'Caja' : 'Banco', Number(monto || 0), 0), cxc > 0 ? lnCta(byc, '1103', 'Cuentas por cobrar (clientes)', 0, cxc) : null, mora > 0 ? lnCta(byc, moraCod, moraCod === '4103' ? 'Ingresos por mora' : 'Otros ingresos', 0, mora) : null].filter(Boolean);
      await postAsientoConcepto(fecha, 'Abono cliente' + (cliNom ? ' ' + cliNom : ''), 'cobro', origenId || null, lineas);
    } catch (e) {}
  }
  // Asiento de INGRESO por servicio (reparaciones/apartados): Debe Caja o Banco / Haber Ventas
  async function postAsientoServicio(concepto, monto, metodo, origenId) {
    try {
      if (!(Number(monto) > 0)) return;
      const byc = await ctasMap(); if (!Object.keys(byc).length) return;
      const efe = /efectivo/i.test(metodo || 'Efectivo');
      const lineas = [lnCta(byc, efe ? '1101' : '1102', efe ? 'Caja' : 'Banco', Number(monto), 0), lnCta(byc, '4101', 'Ventas', 0, Number(monto))].filter(Boolean);
      if (lineas.length < 2) return;
      await postAsientoConcepto(hoyISOPos(), concepto, 'servicio', origenId || null, lineas);
    } catch (e) {}
  }
  // Borra el/los asiento(s) de un documento (reversa al eliminar/anular)
  async function delAsientoOrigen(tipo, origenId) {
    try {
      const as = await getAPI().get('pos_asientos', 'select=id&tipo=eq.' + tipo + '&origen_id=eq.' + origenId) || [];
      for (const a of as) { try { await getAPI().del('pos_asiento_lineas', 'asiento_id=eq.' + a.id); await getAPI().del('pos_asientos', 'id=eq.' + a.id); } catch (e) {} }
    } catch (e) {}
  }

  // ════════════════════════════════════════════════════════════════════
  // ── MÓDULO COTIZACIONES / PRESUPUESTOS (POS) ──
  // ════════════════════════════════════════════════════════════════════
  async function cargarCotizaciones() {
    _cotizaciones = await getAPI().get('pos_cotizaciones', 'select=*&order=created_at.desc&limit=300') || [];
  }
  function cotProxNumero() { let mx = 0; (_cotizaciones || []).forEach(c => { const m = String(c.numero || '').match(/(\d+)\s*$/); if (m) { const n = parseInt(m[1], 10); if (n > mx) mx = n; } }); return 'COT-' + String(mx + 1).padStart(4, '0'); }
  function cotTotales(lineas) {
    let total = 0, itbis = 0, descuento = 0;
    (lineas || []).forEach(it => { const imp = lineImporte(it); descuento += lineDescMonto(it); total += imp; if (it.itbis) itbis += imp * 18 / 118; });
    total = Math.round(total); itbis = Math.round(itbis); descuento = Math.round(descuento);
    return { total: total, itbis: itbis, subtotal: total - itbis, descuento: descuento };
  }
  function cotEstadoBadge(e) {
    const m = { vigente: ['#16a34a', '#f0fdf4', 'VIGENTE'], convertida: ['#6d28d9', '#eff6ff', 'CONVERTIDA'], vencida: ['#ea580c', '#fff7ed', 'VENCIDA'], anulada: ['#dc2626', '#fef2f2', 'ANULADA'] };
    const x = m[e] || m.vigente; return `<span style="font-size:9px;font-weight:800;color:${x[0]};background:${x[1]};padding:2px 7px;border-radius:6px">${x[2]}</span>`;
  }
  function cotVigente(c) {
    if (c.estado !== 'vigente') return c.estado;
    try { const venc = new Date(String(c.fecha).slice(0, 10) + 'T12:00:00'); venc.setDate(venc.getDate() + Number(c.validez_dias || 15)); if (venc < new Date()) return 'vencida'; } catch (e) {}
    return 'vigente';
  }
  function renderCotizaciones() {
    nxPfEnsureCSS();
    const filas = _cotizaciones.length ? _cotizaciones.map(c => {
      const est = cotVigente(c);
      return `<tr data-row tabindex="0" role="button" onclick="window.nxCotEditar('${c.id}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();window.nxCotEditar('${c.id}')}">
        <td style="font-weight:800;font-family:var(--mono,monospace);color:var(--pf-blue-d)">${esc(c.numero || '')}</td>
        <td>${esc(c.cliente_nombre || '—')}<div style="font-size:10px;color:var(--pf-txt3)">${fechaDMY(c.fecha)}</div></td>
        <td style="text-align:center">${cotEstadoBadge(est)}</td>
        <td style="text-align:right;font-weight:800">${fmt(c.total)}</td>
        <td style="text-align:right;white-space:nowrap" onclick="event.stopPropagation()">
          <button class="ab g3" style="height:30px;width:30px;padding:0" title="Imprimir" onclick="window.nxCotImprimir('${c.id}')" aria-label="Imprimir"><i class="ti ti-printer"></i></button>
          ${est === 'vigente' || est === 'vencida' ? `<button class="ab g1" style="height:30px;width:30px;padding:0" title="Convertir en venta" onclick="window.nxCotConvertir('${c.id}')" aria-label="Convertir en venta"><i class="ti ti-arrow-right"></i></button>` : ''}
          <button class="ab g3" style="height:30px;width:30px;padding:0" title="Editar" onclick="window.nxCotEditar('${c.id}')" aria-label="Editar"><i class="ti ti-edit"></i></button>
          ${est === 'convertida' ? `<button class="ab g3" style="height:30px;width:30px;padding:0" title="Ver cadena" onclick="window.nxDocCadena('pos_cotizaciones','${c.id}')" aria-label="Ver cadena del documento"><i class="ti ti-git-branch"></i></button>` : ''}
        </td>
      </tr>`;
    }).join('') : `<tr><td colspan="5" class="emptyrow">Aún no hay cotizaciones. Crea la primera.</td></tr>`;
    return `<div class="nxPf">
      <div class="toolbar2"><button class="ab g2 sm" type="button" onclick="window.nxCotNueva()"><i class="ti ti-plus"></i> Nueva cotización</button></div>
      <div class="card" style="padding:0;overflow-x:auto"><table class="ltbl"><thead><tr><th>No.</th><th>Cliente</th><th style="text-align:center">Estado</th><th style="text-align:right">Total</th><th></th></tr></thead><tbody>${filas}</tbody></table></div>
    </div>`;
  }
  window.nxCotNueva = function () { _cotEdit = { id: null, cliente_id: '', cliente_nombre: '', fecha: isoHoy(), validez_dias: 15, notas: '', lineas: [] }; _cotEditSnapshot = null; abrirCotizacion(); };
  window.nxCotEditar = async function (id) {
    const c = _cotizaciones.find(x => String(x.id) === String(id)); if (!c) return;
    let items = []; try { items = await getAPI().get('pos_cotizacion_items', 'select=*&cotizacion_id=eq.' + id) || []; } catch (e) {}
    _cotEdit = { id: c.id, cliente_id: c.cliente_id || '', cliente_nombre: c.cliente_nombre || '', fecha: String(c.fecha).slice(0, 10), validez_dias: c.validez_dias || 15, notas: c.notas || '', estado: c.estado, lineas: items.map(it => ({ producto_id: it.producto_id, nombre: it.nombre, precio: Number(it.precio || 0), cantidad: Number(it.cantidad || 1), itbis: it.itbis !== false, desc: 0, descT: 'pct' })) };
    // Fotografía del estado ya guardado (para el motor de documentos: al volver a guardar, se compara
    // contra esto y se loguean SOLO los cambios reales — cliente/artículos/precio/cantidad).
    _cotEditSnapshot = JSON.parse(JSON.stringify(_cotEdit));
    abrirCotizacion();
  };
  function abrirCotizacion() {
    nxPfEnsureCSS();
    cerrarModal('nxCotForm');
    const cliOpts = '<option value="">— Cliente / consumidor final —</option>' + _clientes.map(c => `<option value="${c.id}"${String(_cotEdit.cliente_id) === String(c.id) ? ' selected' : ''}>${esc(c.nombre)}</option>`).join('');
    const prodList = _prods.map(p => `<option value="${esc(p.nombre)}${p.codigo ? ' [' + esc(p.codigo) + ']' : ''}">`).join('');
    const ov = document.createElement('div'); ov.id = 'nxCotForm'; ov.className = 'overlay open';
    ov.addEventListener('click', ev => { if (ev.target === ov) ov.remove(); });
    ov.innerHTML = `<div class="modal nxPf" style="max-width:640px;max-height:94vh;display:flex;flex-direction:column;padding:0;border-radius:18px;overflow:hidden">
        <div class="head">
          <button class="nxBack" type="button" onclick="document.getElementById('nxCotForm').remove()" title="Volver" aria-label="Volver"><i class="ti ti-arrow-left"></i></button>
          <h3><i class="ti ti-clipboard-text"></i> ${_cotEdit.id ? 'Editar' : 'Nueva'} cotización</h3>
        </div>
        <div style="overflow-y:auto;flex:1;padding:14px;display:flex;flex-direction:column;gap:12px">
          <div class="card">
            <h4><span class="bdg purple"><i class="ti ti-file-description"></i></span> Datos de la cotización</h4>
            <div class="fld" style="margin-bottom:10px"><label>Cliente</label><div class="inw"><select id="cotCli" onchange="window.nxCotSetCli(this.value)">${cliOpts}</select><i class="ti ti-chevron-down chev"></i></div></div>
            <div class="g2">
              <div class="fld"><label>Fecha</label><div class="inw"><input type="date" id="cotFecha" value="${_cotEdit.fecha}" onchange="window.nxCotField('fecha',this.value)"></div></div>
              <div class="fld"><label>Validez (días)</label><div class="inw"><input id="cotVal" inputmode="numeric" value="${_cotEdit.validez_dias}" onchange="window.nxCotField('validez_dias',this.value)"></div></div>
            </div>
          </div>
          <div class="card">
            <h4><span class="bdg blue"><i class="ti ti-shopping-cart"></i></span> Productos</h4>
            <div class="nxFacAdd" style="margin:0 0 10px"><i class="ti ti-search"></i><input list="cotProds" id="cotBuscar" placeholder="Escribe un producto y elígelo para agregar..." autocomplete="off" onchange="window.nxCotAdd(this.value)"><datalist id="cotProds">${prodList}</datalist></div>
            <div id="cotTabla"></div>
            <div id="cotTot" class="nxAsTot" style="margin-top:8px"></div>
          </div>
          <div class="card">
            <h4><span class="bdg green"><i class="ti ti-notes"></i></span> Notas</h4>
            <div class="fld"><label>Notas (opcional)</label><div class="inw"><input id="cotNotas" class="no-upper" value="${esc(_cotEdit.notas || '')}" placeholder="Condiciones, entrega..." onchange="window.nxCotField('notas',this.value)"></div></div>
          </div>
        </div>
        <div class="actions" style="margin-top:0;grid-template-columns:1fr 1fr 1fr">
          <button class="ab g3" type="button" onclick="document.getElementById('nxCotForm').remove()">Cancelar</button>
          <button class="ab g2" type="button" onclick="window.nxCotGuardar(true)"><i class="ti ti-printer"></i> Guardar e imprimir</button>
          <button class="ab g1" type="button" onclick="window.nxCotGuardar()"><i class="ti ti-device-floppy"></i> Guardar</button>
        </div>
      </div>`;
    document.body.appendChild(ov);
    pintarCotTabla();
  }
  window.nxCotSetCli = function (id) { _cotEdit.cliente_id = id; const c = _clientes.find(x => String(x.id) === String(id)); _cotEdit.cliente_nombre = c ? c.nombre : ''; };
  window.nxCotField = function (k, v) { _cotEdit[k] = (k === 'validez_dias') ? (parseInt(v, 10) || 15) : v; };
  window.nxCotAdd = function (txt) {
    if (!txt) return;
    const t = String(txt).toLowerCase();
    let p = _prods.find(x => (x.nombre + (x.codigo ? ' [' + x.codigo + ']' : '')).toLowerCase() === t) || _prods.find(x => String(x.nombre).toLowerCase() === t) || _prods.find(x => x.codigo && String(x.codigo).toLowerCase() === t);
    if (!p) { const m = String(txt).match(/\[([^\]]+)\]/); if (m) p = _prods.find(x => x.codigo && String(x.codigo).toLowerCase() === m[1].toLowerCase()); }
    if (!p) { toast('warn', 'Producto no encontrado', 'Elígelo de la lista'); return; }
    const ex = _cotEdit.lineas.find(l => String(l.producto_id) === String(p.id));
    if (ex) ex.cantidad += 1; else _cotEdit.lineas.push({ producto_id: p.id, nombre: p.nombre, precio: Number(p.precio || 0), cantidad: 1, itbis: p.itbis !== false, desc: 0, descT: 'pct' });
    const inp = document.getElementById('cotBuscar'); if (inp) inp.value = '';
    pintarCotTabla();
  };
  window.nxCotLinea = function (i, k, v) { const l = _cotEdit.lineas[i]; if (!l) return; if (k === 'cantidad') l.cantidad = Math.max(1, parseFloat(v) || 1); else if (k === 'precio') l.precio = parseMoney(v); else if (k === 'desc') l.desc = parseFloat(v) || 0; pintarCotTabla(); };
  window.nxCotDel = function (i) { _cotEdit.lineas.splice(i, 1); pintarCotTabla(); };
  function pintarCotTabla() {
    const wrap = document.getElementById('cotTabla'); if (!wrap) return;
    if (!_cotEdit.lineas.length) { wrap.innerHTML = '<div style="text-align:center;color:#475569;font-size:12px;padding:22px">Agrega productos a la cotización.</div>'; const t = document.getElementById('cotTot'); if (t) t.innerHTML = ''; return; }
    const filas = _cotEdit.lineas.map((l, i) => `<tr>
        <td class="nxFacDesc">${esc(l.nombre)}</td>
        <td class="nxFacCant"><input inputmode="numeric" value="${l.cantidad}" onchange="window.nxCotLinea(${i},'cantidad',this.value)"></td>
        <td class="nxFacPre"><input inputmode="numeric" value="${Math.round(l.precio)}" onchange="window.nxCotLinea(${i},'precio',this.value)"></td>
        <td class="nxFacImp">${fmt(lineImporte(l))}</td>
        <td class="nxFacDel"><button aria-label="Quitar este producto" onclick="window.nxCotDel(${i})"><i class="ti ti-minus" style="color:#dc2626"></i></button></td>
      </tr>`).join('');
    wrap.innerHTML = `<div class="nxFacTblWrap"><table class="nxFacTbl" style="min-width:0"><thead><tr><th>Descripción</th><th style="text-align:right">Cant.</th><th style="text-align:right">Precio</th><th style="text-align:right">Importe</th><th></th></tr></thead><tbody>${filas}</tbody></table></div>`;
    const tt = cotTotales(_cotEdit.lineas); const t = document.getElementById('cotTot');
    if (t) t.innerHTML = `<div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px"><span>Subtotal: <b>${fmt(tt.subtotal)}</b></span><span>ITBIS: <b>${fmt(tt.itbis)}</b></span><span style="color:#0f172a">TOTAL: <b>${fmt(tt.total)}</b></span></div>`;
  }
  window.nxCotGuardar = async function (imprimir) {
    if (!_cotEdit.lineas.length) { toast('err', 'Agrega al menos un producto'); return; }
    const tt = cotTotales(_cotEdit.lineas);
    const numero = _cotEdit.numero || (await nextSeq('cotizacion')) || cotProxNumero();
    const esNueva = !_cotEdit.id;
    const body = { numero: numero, cliente_id: _cotEdit.cliente_id || null, cliente_nombre: _cotEdit.cliente_nombre || null, fecha: _cotEdit.fecha || isoHoy(), validez_dias: Number(_cotEdit.validez_dias || 15), subtotal: tt.subtotal, itbis: tt.itbis, descuento: tt.descuento, total: tt.total, notas: (_cotEdit.notas || '').trim() || null, created_by_name: nomAdmin() };
    try {
      let cotId = _cotEdit.id;
      if (cotId) { await getAPI().patch('pos_cotizaciones', 'id=eq.' + cotId, body); await getAPI().del('pos_cotizacion_items', 'cotizacion_id=eq.' + cotId); }
      else { const r = await getAPI().post('pos_cotizaciones', body); cotId = (r && r[0] && r[0].id); }
      if (!cotId) throw new Error('No se pudo guardar');
      const items = _cotEdit.lineas.map(l => ({ cotizacion_id: cotId, producto_id: l.producto_id, nombre: l.nombre, precio: Math.round(l.precio), cantidad: l.cantidad, itbis: !!l.itbis, descuento: Math.round(lineDescMonto(l)), importe: Math.round(lineImporte(l)) }));
      await getAPI().post('pos_cotizacion_items', items);
      if (esNueva) { registrarDocumento('cotizacion', numero, 'pos_cotizaciones', cotId, { clienteId: body.cliente_id, monto: body.total }).catch(() => {}); }
      else {
        // Motor de documentos: se editó una cotización ya guardada — loguear SOLO lo que de verdad cambió.
        try {
          const cambios = diffCotizacion(_cotEditSnapshot, _cotEdit);
          if (cambios.length) { const doc = await buscarDocumentoDe('pos_cotizaciones', cotId); if (doc) cambios.forEach(ev => registrarEventoDoc(doc.id, ev.evento, ev.detalle).catch(() => {})); }
        } catch (eDiff) { console.warn('motor de documentos (diff cotización):', eDiff); }
      }
      _cotEditSnapshot = null;
      cerrarModal('nxCotForm'); toast('ok', 'Cotización guardada', numero);
      await cargarCotizaciones(); const v = document.getElementById('v-pos'); if (v) renderPOS(v);
      if (imprimir) window.nxCotImprimir(cotId);
    } catch (e) { toast('err', 'No se pudo guardar', String(e && e.message || e)); }
  };
  window.nxCotConvertir = async function (id) {
    const c = _cotizaciones.find(x => String(x.id) === String(id)); if (!c) return;
    if (!confirm('¿Convertir esta cotización en venta? Se cargará en la pantalla Factura para cobrarla.')) return;
    let items = []; try { items = await getAPI().get('pos_cotizacion_items', 'select=*&cotizacion_id=eq.' + id) || []; } catch (e) {}
    if (!items.length) { toast('err', 'La cotización no tiene productos'); return; }
    _cart = items.map(it => ({ producto_id: it.producto_id, nombre: it.nombre, precio: Number(it.precio || 0), cantidad: Number(it.cantidad || 1), itbis: it.itbis !== false, desc: 0, descT: 'pct' }));
    _factCli = c.cliente_id || '';
    try { await getAPI().patch('pos_cotizaciones', 'id=eq.' + id, { estado: 'convertida' }); } catch (e) {}
    try { const doc = await buscarDocumentoDe('pos_cotizaciones', id); if (doc) { _facOrigenDoc = { tipo: 'cotizacion', documentoId: doc.id }; registrarEventoDoc(doc.id, 'convertido_a_carrito', 'Cargada en Factura para cobrar').catch(() => {}); } } catch (e) {}
    toast('ok', 'Cotización cargada', 'Completa el cobro en Factura');
    _posTab = 'factura'; const v = document.getElementById('v-pos'); if (v) renderPOS(v);
  };
  window.nxCotImprimir = async function (id) {
    const c = _cotizaciones.find(x => String(x.id) === String(id)); if (!c) return;
    let items = []; try { items = await getAPI().get('pos_cotizacion_items', 'select=*&cotizacion_id=eq.' + id) || []; } catch (e) {}
    const e = empInfo();
    const filas = items.map(it => `<tr><td>${Number(it.cantidad)}</td><td>${esc(it.nombre)}</td><td class="r">${fmt(it.precio)}</td><td class="r">${fmt(it.importe)}</td></tr>`).join('');
    let venc = ''; try { const d = new Date(String(c.fecha).slice(0, 10) + 'T12:00:00'); d.setDate(d.getDate() + Number(c.validez_dias || 15)); venc = fechaDMY(d.toLocaleDateString('en-CA')); } catch (er) {}
    const html = `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cotización ${esc(c.numero || '')}</title>
      <style>body{font-family:Segoe UI,system-ui,-apple-system,sans-serif;color:#111;max-width:660px;margin:0 auto;padding:22px;font-size:12.5px}h1{font-size:17px;text-align:center;margin:0}.c{text-align:center}.muted{color:#555;font-size:11px}table{width:100%;border-collapse:collapse;margin:10px 0}th{text-align:left;font-size:10px;text-transform:uppercase;color:#555;border-bottom:1.5px solid #999;padding:6px}td{padding:5px 6px;border-bottom:1px solid #eee}.r{text-align:right}.line{border-top:1px solid #ccc;margin:8px 0}.tot{margin-left:auto;max-width:280px}.tot td{padding:3px 6px;border:none}.gran{font-weight:800;font-size:15px;border-top:1.5px solid #111!important}@media print{.noprint{display:none}body{padding:0}}</style></head>
      <body>
        <div class="noprint" style="position:sticky;top:0;display:flex;gap:8px;background:#1e3a6e;margin:-22px -22px 14px;padding:9px 14px"><button onclick="window.close()" style="background:rgba(255,255,255,.16);color:#fff;border:none;border-radius:8px;padding:8px 14px;font-weight:700;cursor:pointer">✕ Cerrar</button><button onclick="window.print()" style="background:#fff;color:#1e3a6e;border:none;border-radius:8px;padding:8px 14px;font-weight:700;cursor:pointer">🖨️ Imprimir</button></div>
        <h1>${esc(e.nom)}</h1>
        <div class="c muted">${e.rnc ? 'RNC: ' + esc(e.rnc) : ''}${e.tel ? ' · ' + esc(e.tel) : ''}${e.dir ? '<br>' + esc(e.dir) : ''}</div>
        <div class="line"></div>
        <div class="c"><b>COTIZACIÓN ${esc(c.numero || '')}</b></div>
        <div class="muted">Fecha: ${fechaDMY(c.fecha)} · Válida hasta: ${venc}<br>Cliente: <b>${esc(c.cliente_nombre || 'Consumidor final')}</b></div>
        <table><thead><tr><th>Cant.</th><th>Descripción</th><th class="r">Precio</th><th class="r">Importe</th></tr></thead><tbody>${filas}</tbody></table>
        <table class="tot"><tr><td>Subtotal</td><td class="r">${fmt(c.subtotal)}</td></tr>${Number(c.descuento) ? `<tr><td>Descuento</td><td class="r">- ${fmt(c.descuento)}</td></tr>` : ''}<tr><td>ITBIS (18%)</td><td class="r">${fmt(c.itbis)}</td></tr><tr class="gran"><td>TOTAL</td><td class="r">${fmt(c.total)}</td></tr></table>
        ${c.notas ? `<div class="muted" style="margin-top:10px"><b>Notas:</b> ${esc(c.notas)}</div>` : ''}
        <div class="muted" style="margin-top:16px">Esta cotización es un presupuesto y no constituye una factura. Precios sujetos a cambio después de la fecha de validez.</div>
      </body></html>`;
    try { const w = window.open('', '_blank'); if (!w) { toast('warn', 'Permite las ventanas emergentes'); return; } w.document.write(html); w.document.close(); } catch (er) {}
  };

  // ════════════════════════════════════════════════════════════════════
  // ── MÓDULO INVENTARIO (kardex / valoración / ajuste) estilo Odoo ──
  // ════════════════════════════════════════════════════════════════════
  let _invMovs = [], _invProdSel = '', _invProdMovs = [];
  let _almacenes = [], _stockAlmRows = {}, _almacenSel = '';
  const MOV_LBL = { venta: ['Venta', '#dc2626'], compra: ['Compra', '#16a34a'], devolucion: ['Devolución', '#6d28d9'], anulacion: ['Anulación', '#475569'], ajuste: ['Ajuste', '#ea580c'], apertura: ['Apertura', '#7c3aed'], transferencia: ['Transferencia', '#0891b2'] };
  function almPrincipal() { return _almacenes.find(a => a.es_principal) || _almacenes[0] || null; }
  function almNombre(id) { const a = _almacenes.find(x => String(x.id) === String(id)); return a ? a.nombre : ''; }
  // Fase 8 (Auditoría Completa): nombre del almacén/sucursal ACTIVO en este momento, para que
  // logAudit() (núcleo de Seguros, index.html) lo mande en cada registro sin tener que conocer
  // la estructura interna del POS. Solo devuelve algo si la organización tiene Multi-almacén
  // activado (_almacenes con datos) — si no, null es la respuesta honesta (no hay sucursal que reportar).
  window.nxSucursalActual = function () {
    try { return (_almacenes && _almacenes.length && _almacenSel) ? (almNombre(_almacenSel) || null) : null; } catch (e) { return null; }
  };
  function stockKey(pid, aid) { return String(pid) + '|' + String(aid); }
  function stockEnAlm(pid, aid) { const r = _stockAlmRows[stockKey(pid, aid)]; return r ? Number(r.stock || 0) : 0; }
  function almTotalUnidades(aid) { let s = 0; Object.keys(_stockAlmRows).forEach(k => { if (k.endsWith('|' + aid)) s += Number(_stockAlmRows[k].stock || 0); }); return s; }
  async function upsertStockAlm(pid, aid, nuevo) {
    nuevo = Math.max(0, Number(nuevo || 0)); // nunca por debajo de 0 (evita stock de almacén negativo)
    const k = stockKey(pid, aid); const r = _stockAlmRows[k];
    if (r && r.id) { await getAPI().patch('pos_stock_almacen', 'id=eq.' + r.id, { stock: nuevo }); r.stock = nuevo; }
    else { const res = await getAPI().post('pos_stock_almacen', { producto_id: pid, almacen_id: aid, stock: nuevo }); const row = res && res[0]; _stockAlmRows[k] = { id: row ? row.id : null, stock: nuevo }; }
  }
  // Registra un movimiento de inventario (best-effort, no bloquea la operación)
  async function logMov(prod, tipo, cantidad, stockAnterior, stockNuevo, referencia, motivo) {
    try { await getAPI().post('pos_inv_movimientos', { producto_id: prod.id, producto_nombre: prod.nombre, tipo: tipo, cantidad: cantidad, stock_anterior: stockAnterior, stock_nuevo: stockNuevo, referencia: referencia || null, motivo: motivo || null, created_by_name: (typeof nomAdmin === 'function' ? nomAdmin() : null) }); } catch (e) {}
  }
  // ══════════════ KARDEX INTELIGENTE (Fase 5, Plan Maestro POS 3.0) ══════════════
  // "No modificar inventario directamente. Todo movimiento deberá provenir de: Compra, Venta,
  // Ajuste, Transferencia, Garantía, Taller, Producción. Con historial completo." — regla del
  // dueño. `moverStock` es el ÚNICO camino permitido para cambiar `pos_productos.stock`/
  // `pos_stock_almacen.stock` desde el navegador — cualquier código nuevo que necesite tocar
  // stock pasa por aquí, nunca con un `getAPI().patch('pos_productos', {stock:...})` suelto.
  // Las TRANSFERENCIAS son la única excepción: desde la RPC `pos_transferir_stock` (transferencia
  // con IMEI atómica), que mueve el stock de los 2 almacenes + el kardex dentro de la MISMA
  // transacción del lado de la base — el candado real (UPDATE condicional, no SELECT-luego-
  // escribe) solo es posible ahí, no en JS. `garantia`/`taller`/`producción` quedan reservados en
  // el enum, listos para cuando exista un flujo real que los dispare (hoy Reparaciones no consume
  // piezas del inventario ni existe un módulo de producción dentro del POS — no se inventó uno
  // solo para tener dónde usar el tipo, mismo criterio de "no fingir" del resto del sistema).
  const MOV_TIPOS_VALIDOS = ['compra', 'venta', 'ajuste', 'transferencia', 'garantia', 'taller', 'produccion', 'devolucion', 'anulacion', 'apertura'];
  // Mueve el stock TOTAL de un producto (y, si se pasa almacenId, también ESE almacén por el
  // mismo delta — nunca al revés). delta positivo = entra, negativo = sale. `opts.piso0` (default
  // true) evita bajar de 0; `opts.extra` son campos adicionales para fusionar en el mismo PATCH
  // (ej. costo en una compra). Devuelve el stock nuevo, o null si el tipo no es válido.
  async function moverStock(prod, tipo, delta, opts) {
    opts = opts || {};
    if (!prod || !prod.id) return null;
    if (MOV_TIPOS_VALIDOS.indexOf(tipo) === -1) { console.warn('moverStock: tipo de movimiento inválido:', tipo); return null; }
    delta = Number(delta || 0);
    const prev = Number(prod.stock || 0);
    let ns = prev + delta;
    if (opts.piso0 !== false) ns = Math.max(0, ns);
    prod.stock = ns;
    const body = Object.assign({ stock: ns }, opts.extra || null);
    if (opts.extra && Object.prototype.hasOwnProperty.call(opts.extra, 'costo')) prod.costo = opts.extra.costo;
    try { await getAPI().patch('pos_productos', 'id=eq.' + prod.id, body); } catch (e) {}
    logMov(prod, tipo, delta, prev, ns, opts.referencia || null, opts.motivo || null).catch(() => {});
    if (_almacenes.length && opts.almacenId) {
      try { await upsertStockAlm(prod.id, opts.almacenId, stockEnAlm(prod.id, opts.almacenId) + delta); } catch (e) {}
    }
    return ns;
  }
  async function cargarInventario() {
    try { _invMovs = await getAPI().get('pos_inv_movimientos', 'select=*&order=fecha.desc&limit=200') || []; } catch (e) { _invMovs = []; }
    try { _almacenes = await getAPI().get('pos_almacenes', 'select=*&activo=eq.true&order=es_principal.desc,nombre.asc') || []; } catch (e) {}
    try { const rows = await getAPI().get('pos_stock_almacen', 'select=*&limit=20000') || []; _stockAlmRows = {}; rows.forEach(r => { _stockAlmRows[stockKey(r.producto_id, r.almacen_id)] = { id: r.id, stock: Number(r.stock || 0) }; }); } catch (e) { _stockAlmRows = {}; }
  }
  function invProductosStock() { return (_prods || []).filter(p => p.tipo !== 'servicio'); }
  function movFila(m) {
    const t = MOV_LBL[m.tipo] || [m.tipo, '#475569'];
    const c = Number(m.cantidad || 0);
    return `<tr><td style="white-space:nowrap;color:#475569">${fechaDMY(m.fecha)}</td><td>${esc(m.producto_nombre || '')}</td><td><span style="font-size:9px;font-weight:800;color:${t[1]};background:${t[1]}1a;padding:2px 7px;border-radius:6px">${t[0]}</span></td><td style="text-align:right;font-weight:700;color:${c < 0 ? '#dc2626' : '#16a34a'}">${c > 0 ? '+' : ''}${fmtN(c)}</td><td style="text-align:right;color:#475569">${m.stock_nuevo != null ? fmtN(m.stock_nuevo) : ''}</td><td style="color:#475569;font-size:10px">${esc(m.referencia || m.motivo || '')}</td></tr>`;
  }
  function fmtN(n) { return Number(n || 0).toLocaleString('en-US'); }
  function renderInventario() {
    nxPfEnsureCSS();
    const prods = invProductosStock();
    const valCosto = prods.reduce((s, p) => s + Number(p.stock || 0) * Number(p.costo || 0), 0);
    const valPrecio = prods.reduce((s, p) => s + Number(p.stock || 0) * Number(p.precio || 0), 0);
    const bajos = prods.filter(p => Number(p.stock || 0) <= Number(p.stock_min || 0) && Number(p.stock_min || 0) > 0);
    const sinStock = prods.filter(p => Number(p.stock || 0) <= 0);
    const kpi = (l, v, c) => kpiPf(l, v, c);
    const prodList = prods.map(p => `<option value="${esc(p.nombre)}${p.codigo ? ' [' + esc(p.codigo) + ']' : ''}">`).join('');
    let detalle = '';
    if (_invProdSel) {
      const p = _prods.find(x => String(x.id) === String(_invProdSel));
      const filas = _invProdMovs.length ? _invProdMovs.map(movFila).join('') : '<tr><td colspan="6" style="text-align:center;padding:18px;color:#475569;font-size:12px">Sin movimientos registrados (el kardex empieza desde ahora).</td></tr>';
      const porAlm = _almacenes.length ? `<div style="display:flex;gap:5px;flex-wrap:wrap;margin-bottom:8px">${_almacenes.map(a => `<span class="nxAlmChip">${esc(a.nombre)}: <b>${fmtN(stockEnAlm(_invProdSel, a.id))}</b></span>`).join('')}</div>` : '';
      detalle = `<div class="nxRepCard" style="margin-bottom:12px"><div class="nxRepTit" style="justify-content:space-between"><span><i class="ti ti-history"></i> Kardex — ${esc(p ? p.nombre : '')} (stock total: ${fmtN(p ? p.stock : 0)})</span><span style="display:flex;gap:6px"><button class="btn bsm bghost" onclick="window.nxInvKardexImprimir('${_invProdSel}')"><i class="ti ti-printer"></i> Imprimir</button><button aria-label="Cerrar" class="btn bsm bghost" onclick="window.nxInvCerrarProd()"><i class="ti ti-x"></i></button></span></div>
        ${porAlm}
        <div class="tw" style="font-size:11.5px"><table style="width:100%"><thead><tr><th>Fecha</th><th>Producto</th><th>Tipo</th><th style="text-align:right">Cant.</th><th style="text-align:right">Stock</th><th>Ref.</th></tr></thead><tbody>${filas}</tbody></table></div></div>`;
    }
    let almSec = '';
    if (!_almacenes.length) {
      almSec = `<div class="nxRepCard" style="margin-bottom:12px;text-align:center"><div style="font-size:12.5px;color:#475569;margin-bottom:8px"><b>Multi-almacén</b> — maneja el stock por almacén o sucursal. Crea tu almacén principal para empezar (tu stock actual se asigna ahí).</div><button class="btn bsm bc1" onclick="window.nxAlmInit()"><i class="ti ti-building-warehouse"></i> Activar multi-almacén</button></div>`;
    } else {
      const cards = _almacenes.map(a => `<div class="nxAlmCard"><div style="min-width:0"><b>${esc(a.nombre)}</b>${a.es_principal ? ' <span class="nxEntRol">Principal</span>' : ''}<div style="font-size:10px;color:#475569">${esc(a.direccion || '')}</div></div><div style="text-align:right;white-space:nowrap"><div style="font-weight:800;color:#0d9488">${fmtN(almTotalUnidades(a.id))}</div><div style="font-size:9px;color:#94a3b8">unidades</div></div></div>`).join('');
      almSec = `<div class="nxRepCard" style="margin-bottom:12px"><div class="nxRepTit" style="justify-content:space-between"><span><i class="ti ti-building-warehouse"></i> Almacenes</span><span style="display:flex;gap:6px">${_almacenes.length > 1 ? '<button class="btn bsm bc1" onclick="window.nxAlmTransferir()"><i class="ti ti-transfer"></i> Transferencia</button>' : ''}<button class="btn bsm bghost" onclick="window.nxAlmNuevo()"><i class="ti ti-plus"></i> Almacén</button></span></div><div class="nxAlmGrid">${cards}</div></div>`;
    }
    const bajosHTML = bajos.length ? `<div class="nxRepCard" style="margin-bottom:12px"><div class="nxRepTit"><i class="ti ti-alert-triangle" style="color:#ea580c"></i> Bajo stock (${bajos.length})</div><div class="tw" style="font-size:11.5px"><table style="width:100%"><thead><tr><th>Producto</th><th style="text-align:right">Stock</th><th style="text-align:right">Mínimo</th><th></th></tr></thead><tbody>${bajos.map(p => `<tr><td>${esc(p.nombre)}</td><td style="text-align:right;font-weight:700;color:${Number(p.stock || 0) <= 0 ? '#dc2626' : '#ea580c'}">${fmtN(p.stock)}</td><td style="text-align:right;color:#475569">${fmtN(p.stock_min)}</td><td style="text-align:right"><button aria-label="Ajustar el inventario de este artículo" class="btn bsm bc1" onclick="window.nxInvAjustarProd('${p.id}')"><i class="ti ti-adjustments"></i></button></td></tr>`).join('')}</tbody></table></div></div>` : '';
    const recientes = _invMovs.length ? `<div class="nxRepCard"><div class="nxRepTit"><i class="ti ti-arrows-exchange"></i> Movimientos recientes</div><div class="tw" style="font-size:11.5px"><table style="width:100%"><thead><tr><th>Fecha</th><th>Producto</th><th>Tipo</th><th style="text-align:right">Cant.</th><th style="text-align:right">Stock</th><th>Ref.</th></tr></thead><tbody>${_invMovs.slice(0, 60).map(movFila).join('')}</tbody></table></div></div>` : '<div style="text-align:center;color:#475569;font-size:12px;padding:20px">Aún no hay movimientos. Se registran al vender, comprar, devolver o ajustar.</div>';
    return `<div class="nxPf nxInvWrap"><div class="kpirow" style="margin-bottom:12px">
        ${kpi('Productos', fmtN(prods.length), '#2563eb')}
        ${kpi('Valor a costo', fmt(valCosto), '#0891b2')}
        ${kpi('Valor a precio', fmt(valPrecio), '#16a34a')}
        ${kpi('Bajo stock', fmtN(bajos.length), bajos.length ? '#ea580c' : '#16a34a')}
        ${kpi('Sin stock', fmtN(sinStock.length), sinStock.length ? '#dc2626' : '#16a34a')}
      </div>
      <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px;align-items:center">
        <button class="btn bsm bc1" type="button" onclick="window.nxInvAjustarProd('')"><i class="ti ti-adjustments"></i> Ajustar inventario</button>
        <div class="nxFacAdd" style="flex:1;min-width:180px;margin:0"><i class="ti ti-search"></i><input list="invProds" placeholder="Ver kardex de un producto..." onchange="window.nxInvBuscar(this.value)"><datalist id="invProds">${prodList}</datalist></div>
      </div>
      ${almSec}${detalle}${bajosHTML}${recientes}</div>`;
  }
  window.nxInvBuscar = function (txt) {
    const t = String(txt || '').toLowerCase();
    const p = _prods.find(x => (x.nombre + (x.codigo ? ' [' + x.codigo + ']' : '')).toLowerCase() === t) || _prods.find(x => String(x.nombre).toLowerCase() === t);
    if (p) window.nxInvVerProd(p.id);
  };
  window.nxInvVerProd = async function (id) {
    _invProdSel = id;
    try { _invProdMovs = await getAPI().get('pos_inv_movimientos', 'select=*&producto_id=eq.' + id + '&order=fecha.desc&limit=300') || []; } catch (e) { _invProdMovs = []; }
    const v = document.getElementById('v-pos'); if (v) renderPOS(v);
  };
  window.nxInvCerrarProd = function () { _invProdSel = ''; _invProdMovs = []; const v = document.getElementById('v-pos'); if (v) renderPOS(v); };
  window.nxInvKardexImprimir = function (id) {
    const p = _prods.find(x => String(x.id) === String(id)); if (!p) return;
    const e = empInfo();
    const porAlm = _almacenes.length ? _almacenes.map(a => `${esc(a.nombre)}: ${fmtN(stockEnAlm(id, a.id))}`).join(' · ') : '';
    const filas = (_invProdMovs || []).map(m => { const t = MOV_LBL[m.tipo] || [m.tipo, '#111']; const c = Number(m.cantidad || 0); return `<tr><td>${fechaDMY(m.fecha)}</td><td>${t[0]}</td><td class="r" style="color:${c < 0 ? '#b91c1c' : '#15803d'}">${c > 0 ? '+' : ''}${fmtN(c)}</td><td class="r">${m.stock_nuevo != null ? fmtN(m.stock_nuevo) : ''}</td><td>${esc(m.referencia || m.motivo || '')}</td></tr>`; }).join('') || '<tr><td colspan="5" style="text-align:center;color:#777;padding:14px">Sin movimientos</td></tr>';
    const html = `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kardex — ${esc(p.nombre)}</title>
      <style>body{font-family:Segoe UI,system-ui,-apple-system,sans-serif;color:#111;max-width:720px;margin:0 auto;padding:20px;font-size:12px}h1{font-size:16px;text-align:center;margin:0}.c{text-align:center}.muted{color:#555;font-size:11px}table{width:100%;border-collapse:collapse;margin:10px 0}th{text-align:left;font-size:9.5px;text-transform:uppercase;color:#555;border-bottom:1.5px solid #999;padding:5px}td{padding:4px 5px;border-bottom:1px solid #eee}.r{text-align:right}.line{border-top:1px solid #ccc;margin:8px 0}@media print{.noprint{display:none}body{padding:0}}</style></head>
      <body>
        <div class="noprint" style="position:sticky;top:0;display:flex;gap:8px;background:#4c1d95;margin:-20px -20px 14px;padding:9px 14px"><button onclick="window.close()" style="background:rgba(255,255,255,.16);color:#fff;border:none;border-radius:8px;padding:8px 14px;font-weight:700;cursor:pointer">✕ Cerrar</button><button onclick="window.print()" style="background:#fff;color:#4c1d95;border:none;border-radius:8px;padding:8px 14px;font-weight:700;cursor:pointer">🖨️ Imprimir</button></div>
        <h1>${esc(e.nom)}</h1>
        <div class="c muted">${e.rnc ? 'RNC: ' + esc(e.rnc) : ''}</div>
        <div class="line"></div>
        <div class="c"><b>KARDEX DE INVENTARIO</b></div>
        <div class="muted">Producto: <b>${esc(p.nombre)}</b>${p.codigo ? ' · Cód: ' + esc(p.codigo) : ''} · Stock total: <b>${fmtN(p.stock)}</b>${porAlm ? '<br>Por almacén: ' + porAlm : ''}<br>Generado: ${fechaDMY(isoHoy())}</div>
        <table><thead><tr><th>Fecha</th><th>Tipo</th><th class="r">Cant.</th><th class="r">Stock</th><th>Referencia</th></tr></thead><tbody>${filas}</tbody></table>
      </body></html>`;
    try { const w = window.open('', '_blank'); if (!w) { toast('warn', 'Permite las ventanas emergentes'); return; } w.document.write(html); w.document.close(); } catch (er) {}
  };
  window.nxInvAjustarProd = function (id) {
    cerrarModal('nxInvAjuste');
    const prods = invProductosStock();
    const opts = prods.map(p => `<option value="${p.id}"${String(id) === String(p.id) ? ' selected' : ''}>${esc(p.nombre)}${p.codigo ? ' (' + esc(p.codigo) + ')' : ''} — stock ${fmtN(p.stock)}</option>`).join('');
    const ov = document.createElement('div'); ov.id = 'nxInvAjuste'; ov.className = 'overlay open';
    ov.addEventListener('click', ev => { if (ev.target === ov) ov.remove(); });
    ov.innerHTML = `<div class="modal" style="max-width:420px">
        <div class="mt"><span><i class="ti ti-adjustments"></i> Ajuste de inventario</span><button class="nxBack" type="button" onclick="document.getElementById('nxInvAjuste').remove()"><i class="ti ti-arrow-left"></i> Volver</button></div>
        <div class="fr"><label>Producto *</label><select id="ajProd">${opts}</select></div>
        ${_almacenes.length > 1 ? `<div class="fr"><label>Almacén</label><select id="ajAlm">${_almacenes.map(a => `<option value="${a.id}"${String(_almacenSel) === String(a.id) ? ' selected' : ''}>${esc(a.nombre)}</option>`).join('')}</select></div>` : ''}
        <div class="fr-row">
          <div class="fr"><label>Stock contado (real) *</label><input id="ajStock" inputmode="numeric" placeholder="Cantidad real"></div>
          <div class="fr"><label>Motivo</label><input id="ajMot" class="no-upper" placeholder="Ej: conteo físico, merma"></div>
        </div>
        <div style="font-size:11px;color:#475569;margin-bottom:6px">El sistema calcula la diferencia con el stock actual y la registra en el kardex.</div>
        <div class="fe" style="gap:8px"><button class="btn bghost" type="button" onclick="document.getElementById('nxInvAjuste').remove()">Cancelar</button><button class="btn bc1" type="button" onclick="window.nxInvGuardarAjuste()"><i class="ti ti-device-floppy"></i> Aplicar ajuste</button></div>
      </div>`;
    document.body.appendChild(ov);
  };
  window.nxInvGuardarAjuste = async function () {
    const pid = val('ajProd'); const nuevo = parseInt(String(val('ajStock')).replace(/[^0-9.-]/g, ''), 10);
    if (!pid || isNaN(nuevo)) { toast('err', 'Elige producto y stock real'); return; }
    const p = _prods.find(x => String(x.id) === String(pid)); if (!p) return;
    const motivo = (val('ajMot') || '').trim() || null;
    const aid = (_almacenes.length > 1) ? (val('ajAlm') || _almacenSel) : (_almacenes.length ? (almPrincipal() && almPrincipal().id) : null);
    try {
      if (aid) {
        // ajuste por almacén: el conteo es de ESE almacén; el total cambia por la diferencia
        const curAlm = stockEnAlm(pid, aid); const delta = nuevo - curAlm;
        if (delta === 0) { toast('ok', 'Sin cambios', 'El stock ya coincide'); cerrarModal('nxInvAjuste'); return; }
        await moverStock(p, 'ajuste', delta, { referencia: 'Ajuste · ' + almNombre(aid), motivo: motivo, almacenId: aid });
        toast('ok', 'Inventario ajustado', almNombre(aid) + ': ' + fmtN(curAlm) + ' → ' + fmtN(nuevo));
      } else {
        const prev = Number(p.stock || 0); const delta = nuevo - prev;
        if (delta === 0) { toast('ok', 'Sin cambios', 'El stock ya coincide'); cerrarModal('nxInvAjuste'); return; }
        await moverStock(p, 'ajuste', delta, { referencia: 'Ajuste manual', motivo: motivo });
        toast('ok', 'Inventario ajustado', p.nombre + ': ' + fmtN(prev) + ' → ' + fmtN(nuevo));
      }
      cerrarModal('nxInvAjuste');
      await cargarInventario(); const v = document.getElementById('v-pos'); if (v) renderPOS(v);
    } catch (e) { toast('err', 'No se pudo ajustar', String(e && e.message || e)); }
  };

  // ── Almacenes: activar, gestionar, transferir ──
  window.nxAlmInit = async function () {
    if (!confirm('¿Crear el "Almacén Principal" y asignarle tu stock actual?')) return;
    try {
      const res = await getAPI().post('pos_almacenes', { nombre: 'Almacén Principal', es_principal: true });
      const alm = res && res[0]; if (!alm) throw new Error('No se creó el almacén');
      const prods = invProductosStock();
      const rows = prods.map(p => ({ producto_id: p.id, almacen_id: alm.id, stock: Number(p.stock || 0) }));
      if (rows.length) await getAPI().post('pos_stock_almacen', rows);
      toast('ok', 'Multi-almacén activado', rows.length + ' productos en el Almacén Principal');
      await cargarInventario(); const v = document.getElementById('v-pos'); if (v) renderPOS(v);
    } catch (e) { toast('err', 'No se pudo activar', String(e && e.message || e)); }
  };
  window.nxAlmNuevo = function () { abrirAlmacen(null); };
  window.nxAlmEdit = function (id) { const a = _almacenes.find(x => String(x.id) === String(id)); if (a) abrirAlmacen(a); };
  function abrirAlmacen(a) {
    cerrarModal('nxAlmForm');
    const e = a || {};
    const ov = document.createElement('div'); ov.id = 'nxAlmForm'; ov.className = 'overlay open';
    ov.addEventListener('click', ev => { if (ev.target === ov) ov.remove(); });
    ov.innerHTML = `<div class="modal" style="max-width:400px">
        <div class="mt"><span><i class="ti ti-building-warehouse"></i> ${a ? 'Editar almacén' : 'Nuevo almacén'}</span><button class="nxBack" type="button" onclick="document.getElementById('nxAlmForm').remove()"><i class="ti ti-arrow-left"></i> Volver</button></div>
        <div class="fr"><label>Nombre *</label><input id="almNom" class="no-upper" value="${esc(e.nombre || '')}" placeholder="Ej: Sucursal Centro, Depósito"></div>
        <div class="fr"><label>Dirección</label><input id="almDir" class="no-upper" value="${esc(e.direccion || '')}" placeholder="Opcional"></div>
        <div class="fe" style="margin-top:8px;gap:8px"><button class="btn bghost" type="button" onclick="document.getElementById('nxAlmForm').remove()">Cancelar</button><button class="btn bc1" type="button" onclick="window.nxAlmGuardar('${a ? a.id : ''}')"><i class="ti ti-device-floppy"></i> Guardar</button></div>
      </div>`;
    document.body.appendChild(ov);
  }
  window.nxAlmGuardar = async function (id) {
    const body = { nombre: (val('almNom') || '').trim(), direccion: (val('almDir') || '').trim() || null };
    if (!body.nombre) { toast('err', 'Falta el nombre del almacén'); return; }
    try {
      if (id) await getAPI().patch('pos_almacenes', 'id=eq.' + id, body); else await getAPI().post('pos_almacenes', body);
      cerrarModal('nxAlmForm'); toast('ok', 'Almacén guardado', body.nombre);
      await cargarInventario(); const v = document.getElementById('v-pos'); if (v) renderPOS(v);
    } catch (e) { toast('err', 'No se pudo guardar', String(e && e.message || e)); }
  };
  // { origen, destino, fecha, notas, lineas:[{producto_id,nombre,cant,serial?,seriales?}] }
  // Líneas serializadas (producto.serial===true): `cant` se deriva SIEMPRE de `seriales.length` —
  // nunca se teclea, mismo criterio del Reglamento de Venta (§10: no existe "vender sin IMEI").
  let _transEdit = null;
  let _transSerOpen = null; // índice de la línea con el selector de IMEI abierto (uno a la vez)
  let _transSerCache = {}; // 'producto_id|almacen_id' -> [{id,serial,color}], se invalida al cambiar origen
  window.nxAlmTransferir = function () {
    if (_almacenes.length < 2) { toast('err', 'Necesitas al menos 2 almacenes'); return; }
    _transEdit = { origen: _almacenes[0].id, destino: _almacenes[1].id, fecha: isoHoy(), notas: '', lineas: [] };
    _transSerOpen = null; _transSerCache = {};
    abrirTransfer();
  };
  function abrirTransfer() {
    cerrarModal('nxAlmTransf');
    const almOpts = (sel) => _almacenes.map(a => `<option value="${a.id}"${String(sel) === String(a.id) ? ' selected' : ''}>${esc(a.nombre)}</option>`).join('');
    const prodList = invProductosStock().map(p => `<option value="${esc(p.nombre)}${p.codigo ? ' [' + esc(p.codigo) + ']' : ''}">`).join('');
    const ov = document.createElement('div'); ov.id = 'nxAlmTransf'; ov.className = 'overlay open';
    ov.addEventListener('click', ev => { if (ev.target === ov) ov.remove(); });
    ov.innerHTML = `<div class="modal" style="max-width:560px;max-height:94vh;display:flex;flex-direction:column">
        <div class="mt"><span><i class="ti ti-transfer"></i> Transferencia / Despacho</span><button class="nxBack" type="button" onclick="document.getElementById('nxAlmTransf').remove()"><i class="ti ti-arrow-left"></i> Volver</button></div>
        <div class="fr-row">
          <div class="fr"><label>Desde *</label><select id="trOrig" onchange="window.nxTransField('origen',this.value)">${almOpts(_transEdit.origen)}</select></div>
          <div class="fr"><label>Hacia *</label><select id="trDest" onchange="window.nxTransField('destino',this.value)">${almOpts(_transEdit.destino)}</select></div>
          <div class="fr"><label>Fecha</label><input type="date" id="trFecha" value="${_transEdit.fecha}" onchange="window.nxTransField('fecha',this.value)"></div>
        </div>
        <div class="nxFacAdd" style="margin:2px 0 10px"><i class="ti ti-search"></i><input list="trProds" id="trBuscar" placeholder="Escribe un producto y elígelo para agregar..." autocomplete="off" onchange="window.nxTransAdd(this.value)"><datalist id="trProds">${prodList}</datalist></div>
        <div id="trTabla" style="overflow-y:auto;flex:1"></div>
        <div class="fr"><label>Notas / motivo</label><input id="trNotas" class="no-upper" placeholder="Ej: surtido a sucursal" onchange="window.nxTransField('notas',this.value)"></div>
        <div class="fe" style="margin-top:8px;gap:8px"><button class="btn bghost" type="button" onclick="document.getElementById('nxAlmTransf').remove()">Cancelar</button><button class="btn bc1" type="button" onclick="window.nxAlmGuardarTransfer()"><i class="ti ti-transfer"></i> Transferir y despachar</button></div>
      </div>`;
    document.body.appendChild(ov);
    pintarTransTabla();
  }
  window.nxTransField = function (k, v) {
    if (!_transEdit) return;
    _transEdit[k] = v;
    if (k === 'origen') {
      // El origen cambió: cualquier IMEI ya elegido pertenecía al almacén viejo — se limpia
      // (mismo criterio que ya se sigue en Vender/Factura al filtrar IMEI por almacén, v56.20).
      // `cant` se resetea junto con `seriales` — para una línea serializada `cant` SIEMPRE debe
      // ser `seriales.length`, nunca quedar pegado al valor de antes del cambio de almacén.
      _transEdit.lineas.forEach(l => { if (l.serial) { l.seriales = []; l.cant = 0; } });
      _transSerCache = {}; _transSerOpen = null;
      pintarTransTabla();
    }
  };
  window.nxTransAdd = function (txt) {
    if (!txt) return; const t = String(txt).toLowerCase();
    let p = _prods.find(x => (x.nombre + (x.codigo ? ' [' + x.codigo + ']' : '')).toLowerCase() === t) || _prods.find(x => String(x.nombre).toLowerCase() === t);
    if (!p) { const m = String(txt).match(/\[([^\]]+)\]/); if (m) p = _prods.find(x => x.codigo && String(x.codigo).toLowerCase() === m[1].toLowerCase()); }
    if (!p) { toast('warn', 'Producto no encontrado', 'Elígelo de la lista'); return; }
    const ex = _transEdit.lineas.find(l => String(l.producto_id) === String(p.id));
    if (ex) { if (!p.serial) ex.cant += 1; }
    else if (p.serial) _transEdit.lineas.push({ producto_id: p.id, nombre: p.nombre, cant: 0, serial: true, seriales: [] });
    else _transEdit.lineas.push({ producto_id: p.id, nombre: p.nombre, cant: 1 });
    const inp = document.getElementById('trBuscar'); if (inp) inp.value = '';
    pintarTransTabla();
  };
  window.nxTransCant = function (i, v) { const l = _transEdit.lineas[i]; if (!l || l.serial) return; let n = parseInt(String(v).replace(/[^0-9.-]/g, ''), 10); if (isNaN(n) || n < 1) n = 1; l.cant = n; pintarTransTabla(); };
  window.nxTransDel = function (i) { _transEdit.lineas.splice(i, 1); if (_transSerOpen === i) _transSerOpen = null; pintarTransTabla(); };
  // IMEI disponibles de este producto EN EL ALMACÉN ORIGEN — mismo filtro por almacén que ya
  // usan Vender/Factura (nxCargarSerialesDet/nxFacSerial, v56.20), con caché por producto+almacén.
  async function transSerDisponibles(pid, oid) {
    const k = pid + '|' + oid;
    if (_transSerCache[k]) return _transSerCache[k];
    let rows = [];
    try { rows = await getAPI().get('pos_seriales', 'select=id,serial,color&producto_id=eq.' + pid + '&estado=eq.disponible&almacen_id=eq.' + oid + '&order=created_at.asc') || []; } catch (e) {}
    _transSerCache[k] = rows;
    return rows;
  }
  window.nxTransSerAbrir = async function (i) {
    _transSerOpen = (_transSerOpen === i) ? null : i;
    pintarTransTabla();
    if (_transSerOpen === i) {
      const l = _transEdit.lineas[i]; if (!l) return;
      await transSerDisponibles(l.producto_id, _transEdit.origen);
      if (_transSerOpen === i) pintarTransTabla();
    }
  };
  window.nxTransSerTog = function (i, id, ser) {
    const l = _transEdit.lineas[i]; if (!l) return;
    const idx = l.seriales.findIndex(s => String(s.id) === String(id));
    if (idx >= 0) l.seriales.splice(idx, 1); else l.seriales.push({ id: id, serial: ser });
    l.cant = l.seriales.length;
    pintarTransTabla();
  };
  function transSerChipsHTML(i) {
    const l = _transEdit.lineas[i]; if (!l) return '';
    const rows = _transSerCache[l.producto_id + '|' + _transEdit.origen];
    if (!rows) return '<div style="font-size:10.5px;color:#475569;padding:6px 2px">Cargando IMEI…</div>';
    if (!rows.length) return '<div style="font-size:10.5px;color:#475569;padding:6px 2px">Sin IMEI disponible de este artículo en ' + esc(almNombre(_transEdit.origen)) + '.</div>';
    const sel = new Set(l.seriales.map(s => String(s.id)));
    return rows.map(r => `<span class="nxSerPick${sel.has(String(r.id)) ? ' on' : ''}" onclick="window.nxTransSerTog(${i},'${r.id}','${esc(r.serial)}')" style="display:inline-flex;align-items:center;gap:5px" tabindex="0" onkeydown="if(event.keyCode==13||event.keyCode==32){event.preventDefault();this.click()}" role="button">${colorDotHTML(r.color)}${esc(r.serial)}</span>`).join('');
  }
  function pintarTransTabla() {
    const wrap = document.getElementById('trTabla'); if (!wrap || !_transEdit) return;
    if (!_transEdit.lineas.length) { wrap.innerHTML = '<div style="text-align:center;color:#475569;font-size:12px;padding:22px">Agrega los artículos a despachar.</div>'; return; }
    const oid = _transEdit.origen;
    const filas = _transEdit.lineas.map((l, i) => {
      const disp = stockEnAlm(l.producto_id, oid);
      const falta = l.cant > disp;
      const cantCell = l.serial
        ? `<button class="btn bsm bghost" type="button" onclick="window.nxTransSerAbrir(${i})" style="${falta ? 'border-color:#dc2626;color:#dc2626' : ''}"><i class="ti ti-device-mobile"></i> IMEI: ${l.seriales.length}</button>`
        : `<input inputmode="numeric" value="${l.cant}" onchange="window.nxTransCant(${i},this.value)" style="${falta ? 'border-color:#dc2626' : ''}">`;
      const serRow = (l.serial && _transSerOpen === i)
        ? `<tr><td colspan="4" style="padding:6px 10px;background:#f8fafc"><div style="display:flex;flex-wrap:wrap;gap:6px">${transSerChipsHTML(i)}</div></td></tr>`
        : '';
      return `<tr>
        <td class="nxFacDesc">${esc(l.nombre)}${l.serial ? ' <span style="font-size:9px;color:#0891b2">· IMEI</span>' : ''}</td>
        <td class="nxFacExi"><span${falta ? ' class="nxFacExi0"' : ''}>${fmtN(disp)}</span></td>
        <td class="nxFacCant">${cantCell}</td>
        <td class="nxFacDel"><button aria-label="Quitar esta línea" onclick="window.nxTransDel(${i})"><i class="ti ti-minus" style="color:#dc2626"></i></button></td>
      </tr>${serRow}`;
    }).join('');
    wrap.innerHTML = `<div class="nxFacTblWrap"><table class="nxFacTbl" style="min-width:0"><thead><tr><th>Artículo</th><th style="text-align:center">Disp. origen</th><th style="text-align:right">Cantidad</th><th></th></tr></thead><tbody>${filas}</tbody></table></div>`;
  }
  // Transferencia con IMEI atómica: TODO el despacho (numeración, seriales, stock de los 2
  // almacenes, kardex) es UNA sola llamada RPC transaccional (pos_transferir_stock) — reemplaza
  // el flujo anterior de varios pasos sueltos (post cabecera → post items → moverStockTransferencia
  // por línea), que tenía 2 carreras reales: nextSeq('transferencia') podía repetir número entre 2
  // despachos simultáneos, y upsertStockAlm calculaba el stock nuevo en memoria (SELECT-luego-
  // escribe) en vez de un UPDATE condicional. Las 2 quedan cerradas del lado de la base, no aquí.
  window.nxAlmGuardarTransfer = async function () {
    const oid = _transEdit.origen, did = _transEdit.destino;
    if (oid === did) { toast('err', 'Origen y destino deben ser distintos'); return; }
    for (const l of _transEdit.lineas) { if (l.serial && !l.seriales.length) { toast('err', 'Elige los IMEI', l.nombre); return; } }
    const lineas = _transEdit.lineas.filter(l => Number(l.cant || 0) > 0);
    if (!lineas.length) { toast('err', 'Agrega al menos un artículo'); return; }
    for (const l of lineas) { if (!l.serial && l.cant > stockEnAlm(l.producto_id, oid)) { toast('err', 'Sin stock suficiente', l.nombre + ' en ' + almNombre(oid)); return; } }
    try {
      const payload = lineas.map(l => l.serial
        ? { producto_id: l.producto_id, serial_ids: l.seriales.map(s => s.id) }
        : { producto_id: l.producto_id, cantidad: l.cant });
      const r = await getAPI().post('rpc/pos_transferir_stock', {
        p_origen_id: oid, p_destino_id: did, p_fecha: _transEdit.fecha || isoHoy(),
        p_notas: (_transEdit.notas || '').trim() || null, p_lineas: payload, p_created_by_name: nomAdmin()
      });
      const res = Array.isArray(r) ? r[0] : r;
      if (!res || !res.id) throw new Error('No se pudo transferir');
      cerrarModal('nxAlmTransf');
      toast('ok', 'Despacho ' + res.numero, lineas.length + ' artículo(s)');
      transDespachoImprimir({ numero: res.numero, fecha: _transEdit.fecha || isoHoy(), origen_nombre: almNombre(oid), destino_nombre: almNombre(did), notas: (_transEdit.notas || '').trim() || null, _items: lineas.map(l => ({ nombre: l.nombre, cantidad: l.cant })) });
      await cargarInventario(); const v = document.getElementById('v-pos'); if (v) renderPOS(v);
    } catch (e) {
      const msg = String(e && e.message || e);
      const amigable = /TRANSFER_STOCK_INSUFICIENTE/.test(msg) ? 'No hay suficiente stock en el almacén origen'
        : /TRANSFER_IMEI_NO_DISPONIBLE/.test(msg) ? 'Un IMEI elegido ya no está disponible (puede que otra venta o transferencia lo haya tomado) — vuelve a elegirlo'
        : /TRANSFER_IMEI_REQUERIDO/.test(msg) ? 'Falta elegir el IMEI de un artículo serializado'
        : /TRANSFER_ORIGEN_IGUAL_DESTINO/.test(msg) ? 'Origen y destino deben ser distintos'
        : msg;
      toast('err', 'No se pudo transferir', amigable);
    }
  };
  function transDespachoImprimir(t) {
    const e = empInfo();
    const filas = (t._items || []).map((it, i) => `<tr><td>${i + 1}</td><td>${esc(it.nombre)}</td><td class="r">${fmtN(it.cantidad)}</td></tr>`).join('');
    const total = (t._items || []).reduce((s, it) => s + Number(it.cantidad || 0), 0);
    const html = `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Despacho ${esc(t.numero || '')}</title>
      <style>body{font-family:Segoe UI,system-ui,-apple-system,sans-serif;color:#111;max-width:560px;margin:0 auto;padding:20px;font-size:12.5px}h1{font-size:16px;text-align:center;margin:0}.c{text-align:center}.muted{color:#555;font-size:11px}table{width:100%;border-collapse:collapse;margin:10px 0}th{text-align:left;font-size:10px;text-transform:uppercase;color:#555;border-bottom:1.5px solid #999;padding:6px}td{padding:6px;border-bottom:1px solid #eee}.r{text-align:right}.line{border-top:1px solid #ccc;margin:8px 0}.rut{display:flex;justify-content:space-between;margin:8px 0;font-weight:700}.fz{display:flex;justify-content:space-between;margin-top:40px;font-size:12px}.fz>div{text-align:center;width:45%;border-top:1px solid #999;padding-top:4px}@media print{.noprint{display:none}body{padding:0}}</style></head>
      <body>
        <div class="noprint" style="position:sticky;top:0;display:flex;gap:8px;background:#4c1d95;margin:-20px -20px 14px;padding:9px 14px"><button onclick="window.close()" style="background:rgba(255,255,255,.16);color:#fff;border:none;border-radius:8px;padding:8px 14px;font-weight:700;cursor:pointer">✕ Cerrar</button><button onclick="window.print()" style="background:#fff;color:#4c1d95;border:none;border-radius:8px;padding:8px 14px;font-weight:700;cursor:pointer">🖨️ Imprimir</button></div>
        <h1>${esc(e.nom)}</h1>
        <div class="c muted">${e.rnc ? 'RNC: ' + esc(e.rnc) : ''}</div>
        <div class="line"></div>
        <div class="c"><b>CONDUCE DE DESPACHO / TRASLADO ${esc(t.numero || '')}</b></div>
        <div class="muted">Fecha: ${fechaDMY(t.fecha)}</div>
        <div class="rut"><span>Desde: ${esc(t.origen_nombre || '')}</span><span>→</span><span>Hacia: ${esc(t.destino_nombre || '')}</span></div>
        <table><thead><tr><th>#</th><th>Artículo</th><th class="r">Cantidad</th></tr></thead><tbody>${filas}<tr style="font-weight:800"><td></td><td class="r">TOTAL UNIDADES</td><td class="r">${fmtN(total)}</td></tr></tbody></table>
        ${t.notas ? `<div class="muted"><b>Notas:</b> ${esc(t.notas)}</div>` : ''}
        <div class="fz"><div>Entregado por</div><div>Recibido por</div></div>
      </body></html>`;
    try { const w = window.open('', '_blank'); if (!w) { toast('warn', 'Permite las ventanas emergentes para ver el despacho'); return; } w.document.write(html); w.document.close(); } catch (er) {}
  }

  // ════════════════════════════════════════════════════════════════════
  // ── MÓDULO CRM / EMBUDO DE VENTAS estilo Odoo ──
  // ════════════════════════════════════════════════════════════════════
  let _crm = [], _crmFiltro = 'abiertas';
  const CRM_ETAPAS = [['nuevo', 'Nuevo', '#6d28d9'], ['contactado', 'Contactado', '#0891b2'], ['cotizado', 'Cotizado', '#7c3aed'], ['ganado', 'Ganado', '#16a34a'], ['perdido', 'Perdido', '#dc2626']];
  function crmEt(e) { return CRM_ETAPAS.find(x => x[0] === e) || CRM_ETAPAS[0]; }
  function crmAbierta(o) { return ['nuevo', 'contactado', 'cotizado'].indexOf(o.etapa) >= 0; }
  async function cargarCRM() { try { _crm = await getAPI().get('pos_crm', 'select=*&order=created_at.desc&limit=400') || []; } catch (e) { _crm = []; } }
  function renderCRM() {
    nxPfEnsureCSS();
    const abiertas = _crm.filter(crmAbierta);
    const pipeline = abiertas.reduce((s, o) => s + Number(o.monto_estimado || 0), 0);
    const ganadas = _crm.filter(o => o.etapa === 'ganado');
    const montoGan = ganadas.reduce((s, o) => s + Number(o.monto_estimado || 0), 0);
    const fil = o => _crmFiltro === 'todas' || (_crmFiltro === 'abiertas' && crmAbierta(o)) || _crmFiltro === o.etapa;
    const lista = _crm.filter(fil);
    const chip = (k, lbl) => `<button type="button" class="chip${_crmFiltro === k ? ' on' : ''}" onclick="window.nxCrmFiltro('${k}')">${lbl}</button>`;
    const etOpts = o => CRM_ETAPAS.map(e => `<option value="${e[0]}"${o.etapa === e[0] ? ' selected' : ''}>${e[1]}</option>`).join('');
    const cards = lista.length ? lista.map(o => {
      const et = crmEt(o.etapa);
      const cli = o.cliente_id ? (_clientes.find(x => String(x.id) === String(o.cliente_id)) || {}).nombre : '';
      return `<div class="oppcard" style="border-left:4px solid ${et[2]}">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px">
          <div style="min-width:0"><div style="font-weight:800;font-size:13px">${esc(o.nombre)}</div><div style="font-size:10.5px;color:var(--pf-txt3)">${esc(cli || o.contacto || 'Sin contacto')}${o.telefono ? ' · ' + esc(o.telefono) : ''}</div></div>
          <div style="text-align:right;white-space:nowrap"><div style="font-weight:800;color:${et[2]}">${fmt(o.monto_estimado)}</div></div>
        </div>
        <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;margin-top:9px">
          <select class="oppet" onchange="window.nxCrmEtapa('${o.id}',this.value)">${etOpts(o)}</select>
          <div style="display:flex;gap:5px">
            ${o.etapa !== 'perdido' ? `<button class="ab g1" style="height:30px;width:30px;padding:0" onclick="window.nxCrmVender('${o.id}')" title="Convertir en venta" aria-label="Convertir en venta"><i class="ti ti-cash"></i></button>` : ''}
            ${o.telefono && waNum(o.telefono) ? `<a class="ab g3" style="height:30px;width:30px;padding:0;color:#16a34a" href="https://wa.me/${waNum(o.telefono)}" target="_blank" aria-label="WhatsApp"><i class="ti ti-brand-whatsapp"></i></a>` : ''}
            <button class="ab g3" style="height:30px;width:30px;padding:0" onclick="window.nxCrmEdit('${o.id}')" aria-label="Editar"><i class="ti ti-edit"></i></button>
          </div>
        </div>
        ${o.proxima_accion ? `<div style="font-size:10px;color:var(--pf-orange);margin-top:7px"><i class="ti ti-calendar"></i> Próx.: ${fechaDMY(o.proxima_accion)}</div>` : ''}
      </div>`;
    }).join('') : `<div class="emptyrow">Sin oportunidades. Toca "Nueva oportunidad".</div>`;
    return `<div class="nxPf">
      <div class="kpirow">
        ${kpiPf('Oportunidades abiertas', abiertas.length, 'var(--pf-purple)')}
        ${kpiPf('En pipeline', fmt(pipeline), 'var(--pf-purple)')}
        ${kpiPf('Ganadas', ganadas.length, 'var(--pf-green)')}
        ${kpiPf('Monto ganado', fmt(montoGan), 'var(--pf-green)')}
      </div>
      <div class="toolbar2">
        <button class="ab g2 sm" type="button" onclick="window.nxCrmNueva()"><i class="ti ti-plus"></i> Nueva oportunidad</button>
        <div class="chiprow">${chip('abiertas', 'Abiertas')}${chip('nuevo', 'Nuevo')}${chip('contactado', 'Contactado')}${chip('cotizado', 'Cotizado')}${chip('ganado', 'Ganadas')}${chip('perdido', 'Perdidas')}</div>
      </div>
      <div>${cards}</div>
    </div>`;
  }
  window.nxCrmFiltro = function (k) { _crmFiltro = k; const v = document.getElementById('v-pos'); if (v) renderPOS(v); };
  window.nxCrmEtapa = async function (id, etapa) {
    const body = { etapa: etapa, cerrado_at: (etapa === 'ganado' || etapa === 'perdido') ? new Date().toISOString() : null };
    try { await getAPI().patch('pos_crm', 'id=eq.' + id, body); const o = _crm.find(x => String(x.id) === String(id)); if (o) o.etapa = etapa; toast('ok', 'Etapa actualizada', crmEt(etapa)[1]); const v = document.getElementById('v-pos'); if (v) renderPOS(v); } catch (e) { toast('err', 'No se pudo', String(e && e.message || e)); }
  };
  window.nxCrmVender = async function (id) {
    const o = _crm.find(x => String(x.id) === String(id)); if (!o) return;
    if (!confirm('¿Convertir esta oportunidad en venta? Se abrirá la Factura' + (o.cliente_id ? ' con el cliente cargado' : '') + ' y se marca como Ganada.')) return;
    _cart = [];
    _factCli = o.cliente_id || '';
    try { await getAPI().patch('pos_crm', 'id=eq.' + id, { etapa: 'ganado', cerrado_at: new Date().toISOString() }); o.etapa = 'ganado'; } catch (e) {}
    toast('ok', 'Oportunidad ganada', 'Agrega los productos y cobra');
    _posTab = 'factura'; const v = document.getElementById('v-pos'); if (v) renderPOS(v);
  };
  window.nxCrmNueva = function () { abrirCrm(null); };
  window.nxCrmEdit = function (id) { const o = _crm.find(x => String(x.id) === String(id)); if (o) abrirCrm(o); };
  function abrirCrm(o) {
    nxPfEnsureCSS();
    cerrarModal('nxCrmForm');
    const e = o || {};
    const cliOpts = '<option value="">— Sin enlazar —</option>' + _clientes.filter(c => c.es_cliente !== false).map(c => `<option value="${c.id}"${String(e.cliente_id) === String(c.id) ? ' selected' : ''}>${esc(c.nombre)}</option>`).join('');
    const etOpts = CRM_ETAPAS.map(x => `<option value="${x[0]}"${e.etapa === x[0] ? ' selected' : ''}>${x[1]}</option>`).join('');
    const ov = document.createElement('div'); ov.id = 'nxCrmForm'; ov.className = 'overlay open';
    ov.addEventListener('click', ev => { if (ev.target === ov) ov.remove(); });
    ov.innerHTML = `<div class="modal nxPf" style="max-width:460px;max-height:92vh;display:flex;flex-direction:column;padding:0;border-radius:18px;overflow:hidden">
        <div class="head">
          <button class="nxBack" type="button" onclick="document.getElementById('nxCrmForm').remove()" title="Volver" aria-label="Volver"><i class="ti ti-arrow-left"></i></button>
          <h3><i class="ti ti-target-arrow"></i> ${o ? 'Editar oportunidad' : 'Nueva oportunidad'}</h3>
        </div>
        <div style="overflow-y:auto;flex:1;padding:14px;display:flex;flex-direction:column;gap:12px">
          <div class="card">
            <h4><span class="bdg purple"><i class="ti ti-target-arrow"></i></span> Oportunidad</h4>
            <div class="fld" style="margin-bottom:10px"><label>Nombre de la oportunidad *</label><div class="inw"><input id="crNom" class="no-upper" value="${esc(e.nombre || '')}" placeholder="Ej: Venta 5 laptops a Colmado X"></div></div>
            <div class="g2">
              <div class="fld"><label>Cliente (opcional)</label><div class="inw"><select id="crCli">${cliOpts}</select><i class="ti ti-chevron-down chev"></i></div></div>
              <div class="fld"><label>Etapa</label><div class="inw"><select id="crEt">${etOpts}</select><i class="ti ti-chevron-down chev"></i></div></div>
            </div>
          </div>
          <div class="card">
            <h4><span class="bdg blue"><i class="ti ti-address-book"></i></span> Contacto</h4>
            <div class="g2" style="margin-bottom:10px">
              <div class="fld"><label>Contacto</label><div class="inw"><input id="crCont" class="no-upper" value="${esc(e.contacto || '')}" placeholder="Nombre"></div></div>
              <div class="fld"><label>Teléfono</label><div class="inw"><input id="crTel" class="no-upper" inputmode="tel" value="${esc(e.telefono || '')}" placeholder="809-..."></div></div>
            </div>
            <div class="fld"><label>Email</label><div class="inw"><input id="crEmail" class="no-upper" type="email" value="${esc(e.email || '')}" placeholder="Opcional"></div></div>
          </div>
          <div class="card">
            <h4><span class="bdg green"><i class="ti ti-calendar-stats"></i></span> Seguimiento</h4>
            <div class="g2" style="margin-bottom:10px">
              <div class="fld"><label>Monto estimado</label><div class="inw"><span class="cur">$</span><input id="crMonto" data-nx-money inputmode="numeric" value="${e.monto_estimado ? Math.round(e.monto_estimado) : ''}" placeholder="0" style="padding-left:24px"></div></div>
              <div class="fld"><label>Próxima acción</label><div class="inw"><input type="date" id="crProx" value="${esc((e.proxima_accion || '').slice(0, 10))}"></div></div>
            </div>
            <div class="fld" style="margin-bottom:10px"><label>Fuente</label><div class="inw"><input id="crFuente" class="no-upper" value="${esc(e.fuente || '')}" placeholder="Referido, redes..."></div></div>
            <div class="fld"><label>Notas</label><div class="inw"><input id="crNotas" class="no-upper" value="${esc(e.notas || '')}" placeholder="Detalle del seguimiento"></div></div>
          </div>
        </div>
        <div class="actions" style="margin-top:0${o ? ';grid-template-columns:auto 1fr 1fr' : ''}">
          ${o ? `<button class="ab g4" type="button" style="width:44px;padding:0" onclick="window.nxCrmDel('${o.id}')" aria-label="Eliminar"><i class="ti ti-minus"></i></button>` : ''}
          <button class="ab g3" type="button" onclick="document.getElementById('nxCrmForm').remove()">Cancelar</button>
          <button class="ab g1" type="button" onclick="window.nxCrmGuardar('${o ? o.id : ''}')"><i class="ti ti-device-floppy"></i> Guardar</button>
        </div>
      </div>`;
    document.body.appendChild(ov);
    scanMoney(ov);
  }
  window.nxCrmGuardar = async function (id) {
    const etapa = val('crEt') || 'nuevo';
    const body = { nombre: (val('crNom') || '').trim(), cliente_id: val('crCli') || null, contacto: (val('crCont') || '').trim() || null, telefono: (val('crTel') || '').trim() || null, email: (val('crEmail') || '').trim() || null, monto_estimado: parseMoney(val('crMonto')), etapa: etapa, fuente: (val('crFuente') || '').trim() || null, proxima_accion: val('crProx') || null, notas: (val('crNotas') || '').trim() || null, cerrado_at: (etapa === 'ganado' || etapa === 'perdido') ? new Date().toISOString() : null };
    if (!body.nombre) { toast('err', 'Falta el nombre de la oportunidad'); return; }
    if (!id) { body.created_by_name = nomAdmin(); body.numero = await nextSeq('crm'); }
    try {
      if (id) await getAPI().patch('pos_crm', 'id=eq.' + id, body); else await getAPI().post('pos_crm', body);
      cerrarModal('nxCrmForm'); toast('ok', id ? 'Oportunidad actualizada' : 'Oportunidad creada', body.nombre);
      await cargarCRM(); const v = document.getElementById('v-pos'); if (v) renderPOS(v);
    } catch (e) { toast('err', 'No se pudo guardar', String(e && e.message || e)); }
  };
  window.nxCrmDel = async function (id) {
    if (!confirm('¿Eliminar esta oportunidad?')) return;
    try { await getAPI().del('pos_crm', 'id=eq.' + id); cerrarModal('nxCrmForm'); toast('ok', 'Eliminada'); await cargarCRM(); const v = document.getElementById('v-pos'); if (v) renderPOS(v); } catch (e) { toast('err', 'No se pudo'); }
  };

  // ════════════════════════════════════════════════════════════════════
  // ── MÓDULO REPORTES (POS) — analítica sobre ventas existentes ──
  // ════════════════════════════════════════════════════════════════════
  async function cargarReportes() {
    if (!_repDesde) _repDesde = isoMesIni();
    if (!_repHasta) _repHasta = isoHoy();
    _repVentas = await getAPI().get('pos_ventas', 'select=*&estado=eq.completada&order=created_at.desc&limit=2000') || [];
    try {
      const its = await getAPI().get('pos_venta_items', 'select=*&limit=20000') || [];
      const byV = {}; its.forEach(it => { (byV[it.venta_id] = byV[it.venta_id] || []).push(it); });
      _repVentas.forEach(v => { v._items = byV[v.id] || []; });
    } catch (e) {}
  }
  function repFecha(v) { return String(v.fecha || v.created_at || '').slice(0, 10); }
  function repItems(v) { return v._items || v.pos_venta_items || []; }
  function prodCosto(pid) { const p = _prods.find(x => String(x.id) === String(pid)); return p ? Number(p.costo || 0) : 0; }
  function ventasRepRango() { return (_repVentas || []).filter(v => { const f = repFecha(v); return (!_repDesde || f >= _repDesde) && (!_repHasta || f <= _repHasta); }); }

  function renderReportes() {
    nxPfEnsureCSS();
    const list = ventasRepRango();
    let totVta = 0, totItbis = 0, ganancia = 0, costoTot = 0;
    const porDia = {}, porProd = {}, metodos = { Efectivo: 0, Tarjeta: 0, Transferencia: 0, Otro: 0, 'Crédito': 0 };
    list.forEach(v => {
      totVta += Number(v.total || 0); totItbis += Number(v.itbis || 0);
      const f = repFecha(v); porDia[f] = (porDia[f] || 0) + Number(v.total || 0);
      metodos.Efectivo += Number(v.pagado_efectivo || 0); metodos.Tarjeta += Number(v.pagado_tarjeta || 0);
      metodos.Transferencia += Number(v.pagado_transferencia || 0); metodos.Otro += Number(v.pagado_otro || 0);
      metodos['Crédito'] += Number(v.credito_monto || 0);
      repItems(v).forEach(it => {
        const cant = Number(it.cantidad || 0), imp = Number(it.importe != null ? it.importe : (Number(it.precio || 0) * cant));
        const sinItbis = it.itbis ? imp - (imp * 18 / 118) : imp;
        const cst = prodCosto(it.producto_id) * cant; costoTot += cst; ganancia += sinItbis - cst;
        const key = it.nombre || it.producto_id || '—';
        if (!porProd[key]) porProd[key] = { cant: 0, monto: 0 };
        porProd[key].cant += cant; porProd[key].monto += imp;
      });
    });
    const kpi = (l, v, c) => kpiPf(l, fmt(v), c);
    const dias = Object.keys(porDia).sort().slice(-14);
    const maxDia = Math.max(1, ...dias.map(d => porDia[d]));
    const barras = dias.length ? dias.map(d => { const h = Math.max(3, Math.round(porDia[d] / maxDia * 90)); const dd = d.slice(8) + '/' + d.slice(5, 7); return `<div class="nxRepBar"><div class="nxRepBarV" style="height:${h}px" title="${fmt(porDia[d])}"></div><div class="nxRepBarL">${dd}</div></div>`; }).join('') : '<div style="color:#475569;font-size:12px;padding:20px">Sin ventas en el período.</div>';
    const top = Object.entries(porProd).sort((a, b) => b[1].monto - a[1].monto).slice(0, 10);
    const topFilas = top.length ? top.map(([nom, o], i) => `<tr><td style="color:#475569;width:22px">${i + 1}</td><td style="font-weight:600">${esc(nom)}</td><td style="text-align:right">${o.cant}</td><td style="text-align:right;font-weight:700">${fmt(o.monto)}</td></tr>`).join('') : '<tr><td colspan="4" style="text-align:center;padding:18px;color:#475569;font-size:12px">Sin datos</td></tr>';
    const totMet = Object.values(metodos).reduce((a, b) => a + b, 0) || 1;
    const metFilas = Object.entries(metodos).filter(([k, v]) => v > 0).map(([k, v]) => `<div class="nxRepMet"><div class="nxRepMetTop"><span>${esc(k)}</span><b>${fmt(v)}</b></div><div class="nxRepMetBar"><div style="width:${Math.round(v / totMet * 100)}%"></div></div></div>`).join('') || '<div style="color:#475569;font-size:12px">Sin pagos registrados</div>';
    return `<div class="nxPf nxRepWrap"><div class="nxCtaRango">
        <div class="nxFacF"><label>Desde</label><input type="date" value="${_repDesde}" onchange="window.nxRepRango('d',this.value)"></div>
        <div class="nxFacF"><label>Hasta</label><input type="date" value="${_repHasta}" onchange="window.nxRepRango('h',this.value)"></div>
        <div style="font-size:11px;color:var(--pf-txt3);align-self:end;padding-bottom:11px">${list.length} venta(s)</div>
        <div style="margin-left:auto;display:flex;gap:6px;align-self:end;flex-wrap:wrap">
          ${_vendedores.length ? `<button class="btn bsm bghost" type="button" onclick="window.nxRepComisiones()"><i class="ti ti-user-dollar"></i> Comisiones</button>` : ''}
          <button class="btn bsm bghost" type="button" onclick="window.nxRepImei()"><i class="ti ti-device-mobile-message"></i> Historial de IMEI</button>
          <button class="btn bsm bghost" type="button" onclick="window.nxRep607()"><i class="ti ti-file-certificate"></i> Reporte 607 (NCF)</button>
        </div>
      </div>
      <div class="kpirow">
        ${kpi('Ventas (total)', totVta, '#2563eb')}
        ${kpi('Ganancia estimada', ganancia, ganancia >= 0 ? '#16a34a' : '#dc2626')}
        ${kpi('Costo de lo vendido', costoTot, '#ea580c')}
        ${kpi('ITBIS cobrado', totItbis, '#7c3aed')}
        ${kpiPf('No. de ventas', String(list.length), '')}
        ${kpi('Ticket promedio', list.length ? Math.round(totVta / list.length) : 0, '#0891b2')}
      </div>
      <div class="nxRepGrid">
        <div class="nxRepCard"><div class="nxRepTit"><i class="ti ti-chart-bar"></i> Ventas por día (últimos ${dias.length})</div><div class="nxRepBars">${barras}</div></div>
        <div class="nxRepCard"><div class="nxRepTit"><i class="ti ti-wallet"></i> Por método de pago</div>${metFilas}</div>
      </div>
      <div class="nxRepCard" style="margin-top:12px"><div class="nxRepTit"><i class="ti ti-trophy"></i> Productos más vendidos</div>
        <div class="tw" style="font-size:12px"><table style="width:100%"><thead><tr><th></th><th>Producto</th><th style="text-align:right">Cant.</th><th style="text-align:right">Monto</th></tr></thead><tbody>${topFilas}</tbody></table></div>
      </div></div>`;
  }
  window.nxRepRango = function (k, val) { if (k === 'd') _repDesde = val; else _repHasta = val; const v = document.getElementById('v-pos'); if (v) renderPOS(v); };
  window.nxRepComisiones = function () {
    const list = ventasRepRango();
    const acc = {};
    _vendedores.forEach(v => { acc[v.id] = { nombre: v.nombre, pct: Number(v.comision_pct || 0), ventas: 0, monto: 0, comision: 0 }; });
    let huboEspecial = false;
    list.forEach(v => {
      if (!v.vendedor_id || !acc[v.vendedor_id]) return;
      const a = acc[v.vendedor_id];
      a.ventas += 1; a.monto += Number(v.total || 0);
      const items = repItems(v);
      if (items.length) {
        items.forEach(it => {
          const prod = _prods.find(x => String(x.id) === String(it.producto_id));
          const especial = prod && prod.comision_pct != null && prod.comision_pct !== '';
          const pct = especial ? Number(prod.comision_pct) : a.pct;
          if (especial) huboEspecial = true;
          const imp = Number(it.importe != null ? it.importe : (Number(it.precio || 0) * Number(it.cantidad || 0)));
          a.comision += imp * pct / 100;
        });
      } else {
        a.comision += Number(v.total || 0) * a.pct / 100;
      }
    });
    const e = empInfo();
    let tM = 0, tC = 0;
    const filas = Object.values(acc).filter(o => o.ventas > 0).map(o => { tM += o.monto; tC += o.comision; return `<tr><td>${esc(o.nombre)}</td><td class="r">${o.ventas}</td><td class="r">${fmt(o.monto)}</td><td class="r">${o.pct}%</td><td class="r">${fmt(o.comision)}</td></tr>`; }).join('') || '<tr><td colspan="5" style="text-align:center;color:#777;padding:14px">No hay ventas con vendedor asignado en el período.</td></tr>';
    const html = `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Comisiones</title>
      <style>body{font-family:Segoe UI,system-ui,-apple-system,sans-serif;color:#111;max-width:620px;margin:0 auto;padding:20px;font-size:12.5px}h1{font-size:16px;text-align:center;margin:0}.c{text-align:center}.muted{color:#555;font-size:11px}table{width:100%;border-collapse:collapse;margin:10px 0}th{text-align:left;font-size:10px;text-transform:uppercase;color:#555;border-bottom:1.5px solid #999;padding:6px}td{padding:5px 6px;border-bottom:1px solid #eee}.r{text-align:right}.tot td{font-weight:800;border-top:1.5px solid #999}.line{border-top:1px solid #ccc;margin:8px 0}@media print{.noprint{display:none}body{padding:0}}</style></head>
      <body>
        <div class="noprint" style="position:sticky;top:0;display:flex;gap:8px;background:#1e3a6e;margin:-20px -20px 14px;padding:9px 14px"><button onclick="window.close()" style="background:rgba(255,255,255,.16);color:#fff;border:none;border-radius:8px;padding:8px 14px;font-weight:700;cursor:pointer">✕ Cerrar</button><button onclick="window.print()" style="background:#fff;color:#1e3a6e;border:none;border-radius:8px;padding:8px 14px;font-weight:700;cursor:pointer">🖨️ Imprimir</button></div>
        <h1>${esc(e.nom)}</h1>
        <div class="line"></div>
        <div class="c"><b>REPORTE DE COMISIONES</b></div>
        <div class="c muted">Del ${fechaDMY(_repDesde)} al ${fechaDMY(_repHasta)}</div>
        <table><thead><tr><th>Vendedor</th><th class="r">Ventas</th><th class="r">Monto</th><th class="r">% base</th><th class="r">Comisión</th></tr></thead><tbody>${filas}<tr class="tot"><td>TOTALES</td><td class="r"></td><td class="r">${fmt(tM)}</td><td class="r"></td><td class="r">${fmt(tC)}</td></tr></tbody></table>
        ${huboEspecial ? '<div class="muted">* La comisión ya incluye artículos con una comisión especial propia (distinta al % base del vendedor), configurada en su ficha en Inventario → Ventas.</div>' : ''}
      </body></html>`;
    try { const w = window.open('', '_blank'); if (!w) { toast('warn', 'Permite las ventanas emergentes'); return; } w.document.write(html); w.document.close(); } catch (er) {}
  };
  window.nxRepImei = function () {
    cerrarModal('nxRepImeiM');
    const ov = document.createElement('div'); ov.id = 'nxRepImeiM'; ov.className = 'overlay open';
    ov.addEventListener('click', ev => { if (ev.target === ov) ov.remove(); });
    ov.innerHTML = `<div class="modal" style="max-width:520px;max-height:90vh;display:flex;flex-direction:column">
        <div class="mt"><span><i class="ti ti-device-mobile-message"></i> Historial por IMEI</span><button class="nxBack" type="button" onclick="document.getElementById('nxRepImeiM').remove()"><i class="ti ti-arrow-left"></i> Cerrar</button></div>
        <div style="display:flex;gap:6px;margin-bottom:10px"><input id="imQ" class="no-upper" inputmode="numeric" placeholder="Escribe el IMEI / serial…" style="flex:1;height:40px;border:1.5px solid #e2e8f0;border-radius:9px;padding:0 12px;font-size:13px;font-family:var(--mono,monospace)" onkeydown="if(event.key==='Enter')window.nxRepImeiBuscar()"><button class="btn bc1" type="button" onclick="window.nxRepImeiBuscar()"><i class="ti ti-search"></i> Buscar</button></div>
        <div id="imRes" style="overflow-y:auto;flex:1"><div style="text-align:center;color:#475569;font-size:12px;padding:24px">Escribe un IMEI (completo o parte) y toca Buscar para ver su recorrido: cuándo entró (compra) y cuándo salió (venta).</div></div>
      </div>`;
    document.body.appendChild(ov);
    setTimeout(function () { const i = document.getElementById('imQ'); if (i) i.focus(); }, 60);
  };
  window.nxRepImeiBuscar = async function () {
    const q = (val('imQ') || '').trim(); const res = document.getElementById('imRes'); if (!res) return;
    if (!q) { res.innerHTML = '<div style="text-align:center;color:#dc2626;font-size:12px;padding:16px">Escribe un IMEI</div>'; return; }
    res.innerHTML = '<div style="text-align:center;padding:24px;color:#475569"><div class="spin"></div><div style="margin-top:6px;font-size:12px">Buscando…</div></div>';
    let rows = [];
    try { rows = await getAPI().get('pos_seriales', 'select=*&serial=ilike.*' + encodeURIComponent(q) + '*&order=created_at.desc&limit=50') || []; } catch (er) {}
    if (!rows.length) { res.innerHTML = '<div style="text-align:center;color:#475569;font-size:12.5px;padding:22px">No se encontró ningún equipo con ese IMEI.<br><span style="font-size:11px">Recuerda: el IMEI se registra al comprar el equipo o en su ficha (Administrar seriales).</span></div>'; return; }
    // ventas de salida
    const vids = rows.filter(r => r.venta_id).map(r => r.venta_id);
    const vmap = {};
    if (vids.length) { try { const vs = await getAPI().get('pos_ventas', 'select=id,numero,numero_factura,fecha,cliente_nombre,total&id=in.(' + vids.join(',') + ')') || []; vs.forEach(v => vmap[v.id] = v); } catch (er) {} }
    const cards = rows.map(r => {
      const prod = _prods.find(x => String(x.id) === String(r.producto_id));
      const vendido = r.estado === 'vendido';
      const v = r.venta_id ? vmap[r.venta_id] : null;
      const alm = r.almacen_id ? almNombre(r.almacen_id) : '';
      return `<div style="border:1px solid #e8edf3;border-radius:11px;padding:11px;margin-bottom:8px">
        <div style="display:flex;justify-content:space-between;align-items:center;gap:8px">
          <div style="font-family:var(--mono,monospace);font-weight:800;color:#1e293b;font-size:13px">${esc(r.serial)}</div>
          <span style="font-size:9px;font-weight:800;color:${vendido ? '#dc2626' : '#16a34a'};background:${vendido ? '#fef2f2' : '#f0fdf4'};padding:2px 8px;border-radius:6px">${vendido ? 'VENDIDO' : 'DISPONIBLE'}</span>
        </div>
        <div style="font-size:11.5px;color:#475569;margin-top:2px">${esc(prod ? prod.nombre : 'Producto')}${alm ? ' · ' + esc(alm) : ''}</div>
        <div style="margin-top:8px;font-size:11.5px;color:#334155"><span style="color:#16a34a;font-weight:700"><i class="ti ti-login-2"></i> Entró:</span> ${esc(r.notas || 'registro manual')} · ${fechaDMY(r.created_at)}</div>
        ${v ? `<div style="margin-top:3px;font-size:11.5px;color:#334155"><span style="color:#dc2626;font-weight:700"><i class="ti ti-logout-2"></i> Salió:</span> Factura ${esc(v.numero_factura || v.numero || '')}${v.cliente_nombre ? ' · ' + esc(v.cliente_nombre) : ''} · ${fechaDMY(v.fecha)} · ${fmt(v.total)}</div>` : (vendido ? '<div style="margin-top:3px;font-size:11px;color:#475569">Vendido (sin factura enlazada)</div>' : '<div style="margin-top:3px;font-size:11px;color:#16a34a;font-weight:700">En inventario</div>')}
      </div>`;
    }).join('');
    res.innerHTML = `<div style="font-size:11px;color:#475569;margin-bottom:6px">${rows.length} equipo(s) encontrado(s)</div>${cards}`;
  };
  window.nxRep607 = function () {
    const list = ventasRepRango().filter(v => v.ncf);
    const e = empInfo();
    let mSin = 0, mItb = 0, mTot = 0;
    const filas = list.map(v => {
      const total = Number(v.total || 0), itbis = Number(v.itbis || 0), sin = total - itbis;
      mSin += sin; mItb += itbis; mTot += total;
      return `<tr><td>${esc(v.ncf)}</td><td>${fechaDMY(v.fecha || v.created_at)}</td><td>${esc(v.cliente_nombre || 'Consumidor final')}</td><td class="r">${fmt(sin)}</td><td class="r">${fmt(itbis)}</td><td class="r">${fmt(total)}</td></tr>`;
    }).join('') || '<tr><td colspan="6" style="text-align:center;color:#777;padding:14px">No hay ventas con NCF en el período.</td></tr>';
    const html = `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reporte 607 (NCF)</title>
      <style>body{font-family:Segoe UI,system-ui,-apple-system,sans-serif;color:#111;max-width:760px;margin:0 auto;padding:20px;font-size:12px}h1{font-size:16px;text-align:center;margin:0}.c{text-align:center}.muted{color:#555;font-size:11px}table{width:100%;border-collapse:collapse;margin:10px 0}th{text-align:left;font-size:9.5px;text-transform:uppercase;color:#555;border-bottom:1.5px solid #999;padding:5px}td{padding:4px 5px;border-bottom:1px solid #eee}.r{text-align:right}.tot td{font-weight:800;border-top:1.5px solid #999}.line{border-top:1px solid #ccc;margin:8px 0}@media print{.noprint{display:none}body{padding:0}}</style></head>
      <body>
        <div class="noprint" style="position:sticky;top:0;display:flex;gap:8px;background:#1e3a6e;margin:-20px -20px 14px;padding:9px 14px"><button onclick="window.close()" style="background:rgba(255,255,255,.16);color:#fff;border:none;border-radius:8px;padding:8px 14px;font-weight:700;cursor:pointer">✕ Cerrar</button><button onclick="window.print()" style="background:#fff;color:#1e3a6e;border:none;border-radius:8px;padding:8px 14px;font-weight:700;cursor:pointer">🖨️ Imprimir</button></div>
        <h1>${esc(e.nom)}</h1>
        <div class="c muted">${e.rnc ? 'RNC: ' + esc(e.rnc) : ''}</div>
        <div class="line"></div>
        <div class="c"><b>REPORTE 607 — VENTAS CON COMPROBANTE FISCAL (NCF)</b></div>
        <div class="c muted">Del ${fechaDMY(_repDesde)} al ${fechaDMY(_repHasta)} · ${list.length} comprobante(s)</div>
        <table><thead><tr><th>NCF</th><th>Fecha</th><th>Cliente</th><th class="r">Monto sin ITBIS</th><th class="r">ITBIS</th><th class="r">Total</th></tr></thead><tbody>${filas}<tr class="tot"><td colspan="3" class="r">TOTALES</td><td class="r">${fmt(mSin)}</td><td class="r">${fmt(mItb)}</td><td class="r">${fmt(mTot)}</td></tr></tbody></table>
        <div class="muted" style="margin-top:14px">Base para el formato 607 de la DGII. Verifica los datos del cliente (RNC/Cédula) antes de declarar.</div>
      </body></html>`;
    try { const w = window.open('', '_blank'); if (!w) { toast('warn', 'Permite las ventanas emergentes'); return; } w.document.write(html); w.document.close(); } catch (er) {}
  };

  // ════════════════════════════════════════════════════════════════════
  // ── MÓDULO RECURSOS HUMANOS / NÓMINA (POS / multiempresa, RD) ──
  // Empleados + generación de nómina con deducciones de ley (SFS/AFP/ISR),
  // recibo de pago imprimible y asiento contable automático.
  // ════════════════════════════════════════════════════════════════════
  const SFS_PCT = 0.0304, AFP_PCT = 0.0287; // aportes del empleado (TSS RD)
  // Escala ISR anual DGII (RD$)
  function isrAnual(base) {
    if (base <= 416220) return 0;
    if (base <= 624329) return (base - 416220) * 0.15;
    if (base <= 867123) return 31216 + (base - 624329) * 0.20;
    return 79776 + (base - 867123) * 0.25;
  }
  // Deducciones mensuales de un salario bruto mensual (RD)
  function calcDeducciones(salario) {
    const s = Number(salario || 0);
    const sfs = s * SFS_PCT, afp = s * AFP_PCT;
    const baseAnual = (s - sfs - afp) * 12;
    const isr = isrAnual(baseAnual) / 12;
    return { sfs: Math.round(sfs), afp: Math.round(afp), isr: Math.round(isr) };
  }
  async function cargarRRHH() {
    _empleados = await getAPI().get('rrhh_empleados', 'select=*&order=nombre.asc') || [];
    _nominas = await getAPI().get('rrhh_nominas', 'select=*&order=fecha.desc,created_at.desc&limit=200') || [];
  }
  function empById(id) { return _empleados.find(x => String(x.id) === String(id)); }

  function renderRRHH() {
    try { window.nxPfEnsureCSS(); } catch (e) {}
    const sub = (k, lbl, ic) => `<button type="button" class="nxFacSubTab${_rhTab === k ? ' on' : ''}" onclick="window.nxRhTab('${k}')"><i class="ti ${ic}"></i> ${lbl}</button>`;
    const tabs = `<div class="nxFacSubTabs">${sub('empleados', 'Empleados', 'ti-id-badge-2')}${sub('nominas', 'Nóminas', 'ti-receipt-2')}</div>`;
    return `<div class="nxPf nxRhWrap">` + tabs + (_rhTab === 'nominas' ? rhNominas() : rhEmpleados()) + `</div>`;
  }

  function rhEmpleados() {
    const activos = _empleados.filter(e => e.activo !== false);
    const nomMensual = activos.reduce((s, e) => s + Number(e.salario || 0), 0);
    const filas = _empleados.length ? _empleados.map(e => `<tr${e.activo === false ? ' style="opacity:.5"' : ''}>
        <td><div style="font-weight:700;font-size:12.5px">${esc(e.nombre || '')}</div><div style="font-size:10px;color:#475569">${esc(e.puesto || '')}${e.departamento ? ' · ' + esc(e.departamento) : ''}${e.cedula ? ' · ' + esc(e.cedula) : ''}</div></td>
        <td style="text-align:right;font-weight:700">${fmt(e.salario)}</td>
        <td style="text-align:center;font-size:10.5px;color:#475569">${esc(({ mensual: 'Mensual', quincenal: 'Quincenal', semanal: 'Semanal', por_hora: 'Por hora' })[e.tipo_pago] || e.tipo_pago || '')}</td>
        <td style="text-align:right;white-space:nowrap"><button aria-label="Editar este empleado" class="btn bsm bc1" onclick="window.nxRhEditEmp('${e.id}')"><i class="ti ti-edit"></i></button></td>
      </tr>`).join('') : '<tr><td colspan="4" style="text-align:center;padding:24px;color:#475569;font-size:12px">Sin empleados. Toca "Nuevo empleado".</td></tr>';
    return `<div class="kpirow" style="margin-bottom:12px">
        ${kpiPf('Empleados activos', activos.length, 'var(--pf-purple)')}
        ${kpiPf('Nómina mensual (bruto)', fmt(nomMensual), 'var(--pf-blue)')}
      </div>
      <div style="margin-bottom:10px"><button class="btn bsm bc1" type="button" onclick="window.nxRhNuevoEmp()"><i class="ti ti-plus"></i> Nuevo empleado</button></div>
      <div class="tw" style="font-size:12px"><table style="width:100%"><thead><tr><th>Empleado</th><th style="text-align:right">Salario</th><th style="text-align:center">Pago</th><th></th></tr></thead><tbody>${filas}</tbody></table></div>`;
  }

  function rhNominas() {
    if (_nominaSel) return rhNominaDetalle(_nominaSel);
    const filas = _nominas.length ? _nominas.map(n => {
      const est = n.estado === 'pagada' ? '<span style="font-size:9px;font-weight:800;color:#16a34a;background:#f0fdf4;padding:2px 7px;border-radius:6px">PAGADA</span>' : n.estado === 'anulada' ? '<span style="font-size:9px;font-weight:800;color:#dc2626;background:#fef2f2;padding:2px 7px;border-radius:6px">ANULADA</span>' : '<span style="font-size:9px;font-weight:800;color:#ea580c;background:#fff7ed;padding:2px 7px;border-radius:6px">BORRADOR</span>';
      return `<tr style="cursor:pointer" onclick="window.nxRhVerNomina('${n.id}')" tabindex="0" onkeydown="if(event.keyCode==13||event.keyCode==32){event.preventDefault();this.click()}">
        <td><div style="font-weight:700;font-size:12.5px">${esc(n.periodo || n.descripcion || 'Nómina')}</div><div style="font-size:10px;color:#475569">${fechaDMY(n.fecha)} · ${esc(({ mensual: 'Mensual', quincenal: 'Quincenal', semanal: 'Semanal' })[n.tipo] || n.tipo || '')}</div></td>
        <td style="text-align:center">${est}</td>
        <td style="text-align:right;font-weight:700">${fmt(n.total_neto)}</td>
        <td style="text-align:right"><i class="ti ti-chevron-right" style="color:#cbd5e1"></i></td>
      </tr>`;
    }).join('') : '<tr><td colspan="4" style="text-align:center;padding:24px;color:#475569;font-size:12px">Aún no has generado nóminas.</td></tr>';
    return `<div style="margin-bottom:10px"><button class="btn bsm bc1" type="button" onclick="window.nxRhGenerar()"><i class="ti ti-calculator"></i> Generar nómina</button></div>
      <div class="tw" style="font-size:12px"><table style="width:100%"><thead><tr><th>Período</th><th style="text-align:center">Estado</th><th style="text-align:right">Neto</th><th></th></tr></thead><tbody>${filas}</tbody></table></div>`;
  }

  function rhNominaDetalle(n) {
    const ls = n._lineas || [];
    const filas = ls.map(l => `<tr>
        <td style="font-weight:600">${esc(l.empleado_nombre || '')}</td>
        <td style="text-align:right">${fmt(l.salario_bruto)}</td>
        <td style="text-align:right">${Number(l.bonos) ? fmt(l.bonos) : '—'}</td>
        <td style="text-align:right;color:#dc2626">${fmt(Number(l.sfs) + Number(l.afp) + Number(l.isr) + Number(l.otras_deducciones))}</td>
        <td style="text-align:right;font-weight:800">${fmt(l.neto)}</td>
        <td style="text-align:right"><button aria-label="Imprimir el recibo de pago" class="btn bsm bghost" onclick="window.nxRhRecibo('${n.id}','${l.empleado_id || ''}')"><i class="ti ti-printer"></i></button></td>
      </tr>`).join('');
    return `<div style="display:flex;align-items:center;gap:8px;margin-bottom:12px;flex-wrap:wrap">
        <button class="btn bsm bghost" type="button" onclick="window.nxRhVolver()"><i class="ti ti-arrow-left"></i> Volver</button>
        <div style="font-weight:800;font-size:14px;color:#1e293b">${n.numero ? esc(n.numero) + ' · ' : ''}${esc(n.periodo || 'Nómina')}</div>
        <span style="font-size:11px;color:#475569">${fechaDMY(n.fecha)}</span>
        ${n.estado !== 'anulada' ? `<button class="btn bsm bc3" style="margin-left:auto" type="button" onclick="window.nxRhAnularNomina('${n.id}')"><i class="ti ti-ban"></i> Anular</button>` : '<span style="margin-left:auto;font-size:11px;font-weight:800;color:#dc2626">ANULADA</span>'}
      </div>
      <div class="kpirow" style="margin-bottom:12px">
        ${kpiPf('Total bruto', fmt(n.total_bruto), 'var(--pf-purple)')}
        ${kpiPf('Deducciones', fmt(n.total_deducciones), 'var(--pf-red)')}
        ${kpiPf('Neto a pagar', fmt(n.total_neto), 'var(--pf-green)')}
      </div>
      <div class="tw" style="font-size:12px"><table style="width:100%"><thead><tr><th>Empleado</th><th style="text-align:right">Bruto</th><th style="text-align:right">Bonos</th><th style="text-align:right">Deducc.</th><th style="text-align:right">Neto</th><th></th></tr></thead><tbody>${filas}</tbody></table></div>`;
  }

  // ── Acciones RRHH ──
  window.nxRhTab = function (t) { _rhTab = t; _nominaSel = null; const v = document.getElementById('v-pos'); if (v) renderPOS(v); };
  window.nxRhVolver = function () { _nominaSel = null; const v = document.getElementById('v-pos'); if (v) renderPOS(v); };
  window.nxRhNuevoEmp = function () { abrirEmpleado(null); };
  window.nxRhEditEmp = function (id) { const e = empById(id); if (e) abrirEmpleado(e); };
  function abrirEmpleado(e) {
    cerrarModal('nxEmpForm');
    const d = e || {};
    const tp = t => `<option value="${t[0]}"${d.tipo_pago === t[0] ? ' selected' : ''}>${t[1]}</option>`;
    const tipos = [['mensual', 'Mensual'], ['quincenal', 'Quincenal'], ['semanal', 'Semanal'], ['por_hora', 'Por hora']].map(tp).join('');
    const entEmp = (_clientes || []).filter(c => c.es_empleado);
    const entOpts = '<option value="">— Ninguna (crear nuevo) —</option>' + entEmp.map(c => `<option value="${c.id}"${String(d.entidad_id) === String(c.id) ? ' selected' : ''}>${esc(c.nombre)}${c.cedula ? ' · ' + esc(c.cedula) : ''}</option>`).join('');
    const ov = document.createElement('div'); ov.id = 'nxEmpForm'; ov.className = 'overlay open';
    ov.addEventListener('click', ev => { if (ev.target === ov) ov.remove(); });
    ov.innerHTML = `<div class="modal" style="max-width:440px;max-height:92vh;display:flex;flex-direction:column">
        <div class="mt"><span><i class="ti ti-id-badge-2"></i> ${e ? 'Editar empleado' : 'Nuevo empleado'}</span><button class="nxBack" type="button" onclick="document.getElementById('nxEmpForm').remove()"><i class="ti ti-arrow-left"></i> Volver</button></div>
        <div style="overflow-y:auto;flex:1">
          ${entEmp.length ? `<div class="fr"><label>Vincular con Entidad (empleado)</label><select id="emEnt" onchange="window.nxRhVincEnt()">${entOpts}</select></div>` : ''}
          <div class="fr"><label>Nombre completo *</label><input id="emN" class="no-upper" value="${esc(d.nombre || '')}" placeholder="Nombre y apellido"></div>
          <div class="fr-row">
            <div class="fr"><label>Cédula</label><input id="emC" class="no-upper" value="${esc(d.cedula || '')}" placeholder="000-0000000-0"></div>
            <div class="fr"><label>Teléfono</label><input id="emT" class="no-upper" value="${esc(d.telefono || '')}" placeholder="809-..."></div>
          </div>
          <div class="fr-row">
            <div class="fr"><label>Puesto</label><input id="emP" class="no-upper" value="${esc(d.puesto || '')}" placeholder="Ej: Cajero"></div>
            <div class="fr"><label>Departamento</label><input id="emD" class="no-upper" value="${esc(d.departamento || '')}" placeholder="Ej: Ventas"></div>
          </div>
          <div class="fr-row">
            <div class="fr"><label>Salario bruto *</label><input id="emS" data-nx-money inputmode="numeric" value="${d.salario ? Math.round(d.salario) : ''}" placeholder="0"></div>
            <div class="fr"><label>Tipo de pago</label><select id="emTp">${tipos}</select></div>
          </div>
          <div class="fr-row">
            <div class="fr"><label>Fecha de ingreso</label><input type="date" id="emF" value="${esc((d.fecha_ingreso || '').slice(0, 10))}"></div>
            <div class="fr"><label>No. TSS (NSS)</label><input id="emNss" class="no-upper" value="${esc(d.tss || '')}" placeholder="Opcional"></div>
          </div>
          <div class="fr-row">
            <div class="fr"><label>Banco</label><input id="emB" class="no-upper" value="${esc(d.banco || '')}" placeholder="Opcional"></div>
            <div class="fr"><label>Cuenta banco</label><input id="emCb" class="no-upper" value="${esc(d.cuenta_banco || '')}" placeholder="Opcional"></div>
          </div>
          <div class="fr"><label>Activo</label><select id="emA"><option value="1"${d.activo !== false ? ' selected' : ''}>Sí (activo)</option><option value="0"${d.activo === false ? ' selected' : ''}>No (inactivo)</option></select></div>
        </div>
        <div class="fe" style="margin-top:8px;gap:8px">
          ${e ? `<button aria-label="Eliminar este empleado" class="btn bc3 bsm" type="button" onclick="window.nxRhDelEmp('${e.id}')" style="margin-right:auto"><i class="ti ti-minus"></i></button>` : ''}
          <button class="btn bghost" type="button" onclick="document.getElementById('nxEmpForm').remove()">Cancelar</button>
          <button class="btn bc1" type="button" onclick="window.nxRhGuardarEmp('${e ? e.id : ''}')"><i class="ti ti-device-floppy"></i> Guardar</button>
        </div>
      </div>`;
    document.body.appendChild(ov);
    scanMoney(ov);
  }
  window.nxRhVincEnt = function () {
    const id = val('emEnt'); if (!id) return;
    const c = _clientes.find(x => String(x.id) === String(id)); if (!c) return;
    const set = (eln, v) => { const el = document.getElementById(eln); if (el) el.value = v || ''; };
    set('emN', c.nombre); set('emC', c.cedula); set('emT', c.telefono);
  };
  window.nxRhGuardarEmp = async function (id) {
    const body = {
      nombre: (val('emN') || '').trim(), cedula: (val('emC') || '').trim() || null, telefono: (val('emT') || '').trim() || null,
      puesto: (val('emP') || '').trim() || null, departamento: (val('emD') || '').trim() || null,
      salario: parseMoney(val('emS')), tipo_pago: val('emTp'), fecha_ingreso: val('emF') || null,
      tss: (val('emNss') || '').trim() || null, banco: (val('emB') || '').trim() || null, cuenta_banco: (val('emCb') || '').trim() || null,
      entidad_id: val('emEnt') || null,
      activo: val('emA') === '1'
    };
    if (!body.nombre) { toast('err', 'Falta el nombre'); return; }
    try {
      if (id) await getAPI().patch('rrhh_empleados', 'id=eq.' + id, body); else await getAPI().post('rrhh_empleados', body);
      cerrarModal('nxEmpForm'); toast('ok', 'Empleado guardado');
      await cargarRRHH(); const v = document.getElementById('v-pos'); if (v) renderPOS(v);
    } catch (e) { toast('err', 'No se pudo guardar', String(e && e.message || e)); }
  };
  window.nxRhDelEmp = async function (id) {
    if (!confirm('¿Eliminar este empleado? (mejor márcalo como inactivo si ya tuvo nómina)')) return;
    try { await getAPI().del('rrhh_empleados', 'id=eq.' + id); cerrarModal('nxEmpForm'); toast('ok', 'Empleado eliminado'); await cargarRRHH(); const v = document.getElementById('v-pos'); if (v) renderPOS(v); }
    catch (e) { toast('err', 'No se pudo eliminar', 'Si ya tiene nómina, márcalo inactivo'); }
  };

  // ── Generar nómina ──
  window.nxRhGenerar = function () {
    const activos = _empleados.filter(e => e.activo !== false);
    if (!activos.length) { toast('err', 'No hay empleados activos', 'Agrega empleados primero'); return; }
    const d = new Date();
    _nomEdit = {
      periodo: d.toLocaleDateString('es-DO', { month: 'long', year: 'numeric' }),
      fecha: isoHoy(), tipo: 'mensual',
      lineas: activos.map(e => { const ded = calcDeducciones(e.salario); return { empleado_id: e.id, empleado_nombre: e.nombre, salario_bruto: Number(e.salario || 0), bonos: 0, otras_deducciones: 0, sfs: ded.sfs, afp: ded.afp, isr: ded.isr }; })
    };
    abrirNomina();
  }
  function nomLineaNeto(l) { return Number(l.salario_bruto || 0) + Number(l.bonos || 0) - Number(l.sfs || 0) - Number(l.afp || 0) - Number(l.isr || 0) - Number(l.otras_deducciones || 0); }
  function abrirNomina() {
    cerrarModal('nxNomForm');
    const ov = document.createElement('div'); ov.id = 'nxNomForm'; ov.className = 'overlay open';
    ov.addEventListener('click', ev => { if (ev.target === ov) ov.remove(); });
    ov.innerHTML = `<div class="modal" style="max-width:680px;max-height:94vh;display:flex;flex-direction:column">
        <div class="mt"><span><i class="ti ti-calculator"></i> Generar nómina</span><button class="nxBack" type="button" onclick="document.getElementById('nxNomForm').remove()"><i class="ti ti-arrow-left"></i> Volver</button></div>
        <div class="fr-row">
          <div class="fr" style="flex:2"><label>Período</label><input id="nmP" class="no-upper" value="${esc(_nomEdit.periodo)}" placeholder="Ej: Junio 2026"></div>
          <div class="fr"><label>Fecha</label><input type="date" id="nmF" value="${_nomEdit.fecha}"></div>
          <div class="fr"><label>Tipo</label><select id="nmT"><option value="mensual"${_nomEdit.tipo === 'mensual' ? ' selected' : ''}>Mensual</option><option value="quincenal"${_nomEdit.tipo === 'quincenal' ? ' selected' : ''}>Quincenal</option><option value="semanal"${_nomEdit.tipo === 'semanal' ? ' selected' : ''}>Semanal</option></select></div>
        </div>
        <div style="font-size:10.5px;color:#475569;margin:2px 2px 8px">Deducciones automáticas RD: SFS 3.04% · AFP 2.87% · ISR escala DGII. Puedes editar bonos y otras deducciones.</div>
        <div id="nmLineas" style="overflow-y:auto;flex:1"></div>
        <div id="nmTot" class="nxAsTot"></div>
        <div class="fe" style="margin-top:8px;gap:8px"><button class="btn bghost" type="button" onclick="document.getElementById('nxNomForm').remove()">Cancelar</button><button class="btn bc1" type="button" onclick="window.nxRhGuardarNomina()"><i class="ti ti-device-floppy"></i> Guardar nómina</button></div>
      </div>`;
    document.body.appendChild(ov);
    pintarNomLineas();
  }
  function leerNomLineas() {
    if (!_nomEdit) return;
    const wrap = document.getElementById('nmLineas'); if (!wrap) return;
    _nomEdit.lineas.forEach((l, i) => {
      const b = wrap.querySelector(`[data-nmb="${i}"]`), o = wrap.querySelector(`[data-nmo="${i}"]`);
      if (b) l.bonos = Number(parseMoney(b.value) || 0); if (o) l.otras_deducciones = Number(parseMoney(o.value) || 0);
    });
    const p = document.getElementById('nmP'), f = document.getElementById('nmF'), t = document.getElementById('nmT');
    if (p) _nomEdit.periodo = p.value; if (f) _nomEdit.fecha = f.value; if (t) _nomEdit.tipo = t.value;
  }
  function pintarNomLineas() {
    const wrap = document.getElementById('nmLineas'); if (!wrap || !_nomEdit) return;
    wrap.innerHTML = _nomEdit.lineas.map((l, i) => `<div class="nxNomRow">
        <div class="nxNomEmp"><div style="font-weight:700;font-size:12px">${esc(l.empleado_nombre)}</div><div style="font-size:10px;color:#475569">Bruto ${fmt(l.salario_bruto)} · Ded. ${fmt(Number(l.sfs) + Number(l.afp) + Number(l.isr))}</div></div>
        <label class="nxNomF"><span>Bonos</span><input data-nmb="${i}" data-nx-money inputmode="numeric" value="${l.bonos || ''}" placeholder="0" oninput="window.nxNomTotals()"></label>
        <label class="nxNomF"><span>Otras ded.</span><input data-nmo="${i}" data-nx-money inputmode="numeric" value="${l.otras_deducciones || ''}" placeholder="0" oninput="window.nxNomTotals()"></label>
        <div class="nxNomNeto"><span>Neto</span><b data-nmn="${i}">${fmt(nomLineaNeto(l))}</b></div>
      </div>`).join('');
    try { scanMoney(wrap); } catch (e) {}
    pintarNomTot();
  }
  function pintarNomTot() {
    const el = document.getElementById('nmTot'); if (!el || !_nomEdit) return;
    let bruto = 0, ded = 0, neto = 0;
    _nomEdit.lineas.forEach((l, i) => { bruto += Number(l.salario_bruto || 0) + Number(l.bonos || 0); ded += Number(l.sfs || 0) + Number(l.afp || 0) + Number(l.isr || 0) + Number(l.otras_deducciones || 0); neto += nomLineaNeto(l); const nb = document.querySelector(`[data-nmn="${i}"]`); if (nb) nb.textContent = fmt(nomLineaNeto(l)); });
    el.innerHTML = `<div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px"><span>Bruto: <b>${fmt(bruto)}</b></span><span style="color:#dc2626">Deducciones: <b>${fmt(ded)}</b></span><span style="color:#16a34a">Neto a pagar: <b>${fmt(neto)}</b></span></div>`;
  }
  window.nxNomTotals = function () { leerNomLineas(); pintarNomTot(); };
  window.nxRhGuardarNomina = async function () {
    leerNomLineas();
    if (!_nomEdit.lineas.length) { toast('err', 'Sin empleados en la nómina'); return; }
    let bruto = 0, ded = 0, neto = 0;
    _nomEdit.lineas.forEach(l => { bruto += Number(l.salario_bruto || 0) + Number(l.bonos || 0); ded += Number(l.sfs || 0) + Number(l.afp || 0) + Number(l.isr || 0) + Number(l.otras_deducciones || 0); neto += nomLineaNeto(l); });
    try {
      const nm = await getAPI().post('rrhh_nominas', { numero: await nextSeq('nomina'), periodo: (_nomEdit.periodo || '').trim() || 'Nómina', fecha: _nomEdit.fecha || isoHoy(), tipo: _nomEdit.tipo, total_bruto: Math.round(bruto), total_deducciones: Math.round(ded), total_neto: Math.round(neto), estado: 'pagada' });
      const nid = (nm && nm[0] && nm[0].id); if (!nid) throw new Error('No se creó la nómina');
      const rows = _nomEdit.lineas.map(l => ({ nomina_id: nid, empleado_id: l.empleado_id, empleado_nombre: l.empleado_nombre, salario_bruto: Math.round(l.salario_bruto || 0), bonos: Math.round(l.bonos || 0), sfs: Math.round(l.sfs || 0), afp: Math.round(l.afp || 0), isr: Math.round(l.isr || 0), otras_deducciones: Math.round(l.otras_deducciones || 0), neto: Math.round(nomLineaNeto(l)) }));
      await getAPI().post('rrhh_nomina_lineas', rows);
      try { postAsientoNomina(nm[0], Math.round(bruto), Math.round(ded), Math.round(neto)); } catch (e) {}
      cerrarModal('nxNomForm'); _nomEdit = null; toast('ok', 'Nómina generada', fmt(neto) + ' neto');
      await cargarRRHH(); const v = document.getElementById('v-pos'); if (v) renderPOS(v);
    } catch (e) { toast('err', 'No se pudo generar', String(e && e.message || e)); }
  };
  window.nxRhVerNomina = async function (id) {
    const n = _nominas.find(x => String(x.id) === String(id)); if (!n) return;
    try { n._lineas = await getAPI().get('rrhh_nomina_lineas', 'select=*&nomina_id=eq.' + id) || []; } catch (e) { n._lineas = []; }
    _nominaSel = n; const v = document.getElementById('v-pos'); if (v) renderPOS(v);
  };
  window.nxRhAnularNomina = async function (id) {
    if (!confirm('¿Anular esta nómina?')) return;
    try { await getAPI().patch('rrhh_nominas', 'id=eq.' + id, { estado: 'anulada' }); await delAsientoOrigen('nomina', id); toast('ok', 'Nómina anulada', 'Contabilidad revertida'); _nominaSel = null; await cargarRRHH(); const v = document.getElementById('v-pos'); if (v) renderPOS(v); }
    catch (e) { toast('err', 'No se pudo anular', String(e && e.message || e)); }
  };

  // Asiento contable de la nómina (si existe plan de cuentas)
  async function postAsientoNomina(nomina, bruto, ded, neto) {
    try {
      let cu = _cuentas;
      if (!cu || !cu.length) { try { cu = await getAPI().get('pos_cuentas', 'select=id,codigo,nombre') || []; } catch (e) { cu = []; } }
      if (!cu.length) return;
      const byc = {}; cu.forEach(x => byc[x.codigo] = x);
      const ln = (cod, d, h) => { const x = byc[cod]; if (!x || (Math.round(d) === 0 && Math.round(h) === 0)) return null; return { cuenta_id: x.id, cuenta_codigo: cod, cuenta_nombre: x.nombre, debito: Math.round(d), credito: Math.round(h) }; };
      const lineas = [ln('6101', bruto, 0), ln('2104', 0, ded), ln('2103', 0, neto)].filter(Boolean);
      await guardarAsientoBalanceado({ numero: await nextSeq('asiento'), fecha: (String(nomina.fecha || '').slice(0, 10)) || isoHoy(), concepto: 'Nómina ' + (nomina.periodo || ''), referencia: nomina.periodo || '', tipo: 'nomina', origen_id: nomina.id }, lineas);
    } catch (e) {}
  }

  // ── Recibo de pago imprimible ──
  window.nxRhRecibo = function (nominaId, empId) {
    const n = (_nominaSel && String(_nominaSel.id) === String(nominaId)) ? _nominaSel : _nominas.find(x => String(x.id) === String(nominaId));
    if (!n || !n._lineas) { toast('err', 'Abre la nómina primero'); return; }
    const l = n._lineas.find(x => String(x.empleado_id) === String(empId)); if (!l) return;
    const e = empInfo();
    const totDed = Number(l.sfs) + Number(l.afp) + Number(l.isr) + Number(l.otras_deducciones);
    const fila = (lbl, v, neg) => `<tr><td>${lbl}</td><td style="text-align:right">${neg ? '- ' : ''}${fmt(v)}</td></tr>`;
    const html = `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Recibo de pago — ${esc(l.empleado_nombre)}</title>
      <style>body{font-family:Segoe UI,system-ui,-apple-system,sans-serif;color:#111;max-width:460px;margin:0 auto;padding:18px;font-size:13px}h1{font-size:17px;text-align:center;margin:0}.c{text-align:center}.muted{color:#555;font-size:11px}table{width:100%;border-collapse:collapse;margin:6px 0}td{padding:4px 0}.line{border-top:1px solid #ccc;margin:8px 0}.tot{font-weight:800;font-size:15px}.sec{font-weight:800;font-size:11px;color:#555;text-transform:uppercase;letter-spacing:.4px;margin-top:8px}.box{border:1px solid #e2e8f0;border-radius:10px;padding:12px;margin-top:10px}@media print{.noprint{display:none}body{padding:0}}</style></head>
      <body>
        <div class="noprint" style="position:sticky;top:0;display:flex;gap:8px;background:#1e3a6e;margin:-18px -18px 12px;padding:9px 14px"><button onclick="window.close()" style="background:rgba(255,255,255,.16);color:#fff;border:none;border-radius:8px;padding:8px 14px;font-weight:700;cursor:pointer">✕ Cerrar</button></div>
        <h1>${esc(e.nom)}</h1>
        <div class="c muted">${e.rnc ? 'RNC: ' + esc(e.rnc) : ''}${e.tel ? ' · ' + esc(e.tel) : ''}</div>
        <div class="line"></div>
        <div class="c"><b>RECIBO DE PAGO DE NÓMINA</b></div>
        <div class="c muted">${esc(n.periodo || '')} · ${fechaDMY(n.fecha)}</div>
        <div class="box">
          <table><tr><td><b>Empleado</b></td><td style="text-align:right">${esc(l.empleado_nombre)}</td></tr></table>
          <div class="sec">Ingresos</div>
          <table>${fila('Salario', l.salario_bruto)}${Number(l.bonos) ? fila('Bonos', l.bonos) : ''}</table>
          <div class="sec">Deducciones</div>
          <table>${fila('SFS (Seguro Familiar Salud)', l.sfs, true)}${fila('AFP (Pensión)', l.afp, true)}${Number(l.isr) ? fila('ISR', l.isr, true) : ''}${Number(l.otras_deducciones) ? fila('Otras deducciones', l.otras_deducciones, true) : ''}</table>
          <div class="line"></div>
          <table><tr><td>Total deducciones</td><td style="text-align:right">- ${fmt(totDed)}</td></tr><tr class="tot"><td>NETO A PAGAR</td><td style="text-align:right">${fmt(l.neto)}</td></tr></table>
        </div>
        <div style="display:flex;justify-content:space-between;margin-top:34px;font-size:12px">
          <div style="text-align:center;width:45%;border-top:1px solid #999;padding-top:4px">Recibí conforme</div>
          <div style="text-align:center;width:45%;border-top:1px solid #999;padding-top:4px">Pagado por</div>
        </div>
        <button class="noprint" onclick="window.print()" style="width:100%;padding:12px;margin-top:18px;background:#1e3a6e;color:#fff;border:none;border-radius:10px;font-weight:700;cursor:pointer">🖨️ Imprimir</button>
      </body></html>`;
    try { const w = window.open('', '_blank'); if (!w) { toast('warn', 'Permite las ventanas emergentes para ver el recibo'); return; } w.document.write(html); w.document.close(); } catch (er) {}
  };


  // ══════════════ SERVICIO TÉCNICO / REPARACIONES (kanban) ══════════════
  // ── Clave / patrón del equipo (patrón visual 3x3, PIN o texto libre) ──
  // Se guarda TODO en la misma columna de texto pos_reparaciones.clave, con un prefijo
  // tipo:valor ("patron:1-2-3", "pin:4521", "otro:contraseña123") — así no hizo falta
  // ninguna columna nueva. Texto viejo sin prefijo (capturado antes de esta versión) se
  // interpreta como tipo "otro" — nunca se pierde ni se rompe un dato ya guardado.
  let _claveCap = {};
  function claveParse(raw) {
    const s = String(raw || '').trim();
    if (!s) return { tipo: 'patron', patron: [], pin: '', otro: '' };
    const m = s.match(/^(patron|pin|otro):([\s\S]*)$/);
    if (!m) return { tipo: 'otro', patron: [], pin: '', otro: s };
    if (m[1] === 'patron') return { tipo: 'patron', patron: m[2] ? m[2].split('-').filter(Boolean).map(Number) : [], pin: '', otro: '' };
    if (m[1] === 'pin') return { tipo: 'pin', patron: [], pin: m[2] || '', otro: '' };
    return { tipo: 'otro', patron: [], pin: '', otro: m[2] || '' };
  }
  function claveEncode(st) {
    if (!st) return '';
    if (st.tipo === 'patron') return st.patron.length ? ('patron:' + st.patron.join('-')) : '';
    if (st.tipo === 'pin') return st.pin ? ('pin:' + st.pin) : '';
    return st.otro ? ('otro:' + st.otro) : '';
  }
  function nxClaveBodyHTML(key) {
    const st = _claveCap[key] || { tipo: 'patron', patron: [], pin: '', otro: '' };
    if (st.tipo === 'pin') {
      const disp = st.pin ? st.pin.split('').map(() => '●').join(' ') : 'Sin PIN';
      const nums = [1, 2, 3, 4, 5, 6, 7, 8, 9].map(n => `<button type="button" class="nxClaveKey" onclick="window.nxClavePin('${key}',${n})">${n}</button>`).join('');
      return `<div class="nxClavePinDisp">${disp}</div><div class="nxClaveKeypad">${nums}<button aria-label="Borrar el último dígito" type="button" class="nxClaveKey" onclick="window.nxClavePinDel('${key}')"><i class="ti ti-backspace"></i></button><button type="button" class="nxClaveKey" onclick="window.nxClavePin('${key}',0)">0</button><button aria-label="Limpiar el patrón" type="button" class="nxClaveKey" onclick="window.nxClaveLimpiar('${key}')"><i class="ti ti-x"></i></button></div>`;
    }
    if (st.tipo === 'otro') {
      return `<input type="text" class="no-upper" value="${esc(st.otro)}" placeholder="Ej: contraseña, sin clave, solo huella..." oninput="window.nxClaveOtroInput('${key}', this.value)" style="width:100%">`;
    }
    const dots = [1, 2, 3, 4, 5, 6, 7, 8, 9].map(n => { const i = st.patron.indexOf(n); return `<button type="button" class="nxClaveDot${i >= 0 ? ' on' : ''}" onclick="window.nxClaveDot('${key}',${n})">${i >= 0 ? (i + 1) : ''}</button>`; }).join('');
    const resumen = st.patron.length ? ('Orden: ' + st.patron.join(' → ')) : 'Toca los puntos en el orden del patrón';
    return `<div class="nxClaveGrid">${dots}</div><div class="nxClaveResumen">${resumen}</div><button type="button" class="nxClaveBorrar" onclick="window.nxClaveLimpiar('${key}')"><i class="ti ti-eraser"></i> Borrar</button>`;
  }
  function claveCapturaHTML(key, raw) {
    _claveCap[key] = claveParse(raw);
    const tipo = _claveCap[key].tipo;
    const tab = (t, lbl) => `<button type="button" class="nxClaveTab${tipo === t ? ' on' : ''}" onclick="window.nxClaveTab('${key}','${t}')">${lbl}</button>`;
    return `<div class="nxClaveWrap">
      <div class="nxClaveTabs">${tab('patron', 'Patrón')}${tab('pin', 'PIN')}${tab('otro', 'Otro')}</div>
      <div id="claveBody_${key}">${nxClaveBodyHTML(key)}</div>
    </div>`;
  }
  window.nxClaveTab = function (key, tipo) {
    if (!_claveCap[key]) _claveCap[key] = { tipo: 'patron', patron: [], pin: '', otro: '' };
    _claveCap[key].tipo = tipo;
    const wrap = document.getElementById('claveBody_' + key); if (!wrap) return;
    const tabs = wrap.parentElement.querySelectorAll('.nxClaveTab');
    const ord = ['patron', 'pin', 'otro'];
    tabs.forEach((b, i) => b.classList.toggle('on', ord[i] === tipo));
    wrap.innerHTML = nxClaveBodyHTML(key);
  };
  window.nxClaveDot = function (key, n) {
    const st = _claveCap[key]; if (!st) return;
    if (st.patron.indexOf(n) < 0 && st.patron.length < 9) st.patron.push(n);
    const wrap = document.getElementById('claveBody_' + key); if (wrap) wrap.innerHTML = nxClaveBodyHTML(key);
  };
  window.nxClaveLimpiar = function (key) {
    const st = _claveCap[key]; if (!st) return;
    st.patron = []; st.pin = ''; st.otro = '';
    const wrap = document.getElementById('claveBody_' + key); if (wrap) wrap.innerHTML = nxClaveBodyHTML(key);
  };
  window.nxClavePin = function (key, d) {
    const st = _claveCap[key]; if (!st) return;
    if (st.pin.length >= 8) return;
    st.pin += String(d);
    const wrap = document.getElementById('claveBody_' + key); if (wrap) wrap.innerHTML = nxClaveBodyHTML(key);
  };
  window.nxClavePinDel = function (key) {
    const st = _claveCap[key]; if (!st) return;
    st.pin = st.pin.slice(0, -1);
    const wrap = document.getElementById('claveBody_' + key); if (wrap) wrap.innerHTML = nxClaveBodyHTML(key);
  };
  window.nxClaveOtroInput = function (key, v) {
    const st = _claveCap[key]; if (st) st.otro = v;
  };
  function nxClaveValor(key) { return claveEncode(_claveCap[key]); }
  // Muestra la clave ya guardada (solo lectura) — reusa el mismo parseo, tanto en la app
  // como en la orden impresa (esta última con estilos en línea, ver claveImprimirHTML).
  function claveDisplayHTML(raw) {
    const st = claveParse(raw);
    if (st.tipo === 'patron' && st.patron.length) {
      const dots = [1, 2, 3, 4, 5, 6, 7, 8, 9].map(n => { const i = st.patron.indexOf(n); return `<span class="nxClaveDotRO${i >= 0 ? ' on' : ''}">${i >= 0 ? (i + 1) : ''}</span>`; }).join('');
      return `<div class="nxClaveGridRO">${dots}</div>`;
    }
    if (st.tipo === 'pin' && st.pin) return `<div class="nxClavePinRO">${esc(st.pin)}</div>`;
    if (st.tipo === 'otro' && st.otro) return `<div style="font-size:12px">${esc(st.otro)}</div>`;
    return null;
  }
  function claveImprimirHTML(raw) {
    const st = claveParse(raw);
    if (st.tipo === 'patron' && st.patron.length) {
      const dots = [1, 2, 3, 4, 5, 6, 7, 8, 9].map(n => { const i = st.patron.indexOf(n); return `<span style="display:inline-flex;align-items:center;justify-content:center;width:20px;height:20px;border-radius:50%;border:1.5px solid ${i >= 0 ? '#1e3a8a' : '#cbd5e1'};background:${i >= 0 ? '#1e3a8a' : '#fff'};color:${i >= 0 ? '#fff' : '#94a3b8'};font-size:9px;font-weight:700;margin:1px">${i >= 0 ? (i + 1) : ''}</span>`; }).join('');
      return `<div style="display:grid;grid-template-columns:repeat(3,22px);gap:2px;margin-top:3px">${dots}</div>`;
    }
    if (st.tipo === 'pin' && st.pin) return `<div style="font-family:monospace;font-size:13px;font-weight:700;letter-spacing:3px;margin-top:3px">${esc(st.pin)}</div>`;
    if (st.tipo === 'otro' && st.otro) return `<div style="font-size:11px;margin-top:2px">${esc(st.otro)}</div>`;
    return null;
  }
  const REP_ESTADOS = [['recibido', 'Recibido', '#64748b'], ['diagnostico', 'Diagnóstico', '#d97706'], ['reparando', 'Reparando', '#2563eb'], ['esperando_pieza', 'Esperando pieza', '#a21caf'], ['listo', 'Listo', '#16a34a'], ['entregado', 'Entregado', '#0f172a']];
  function repEst(k) { return REP_ESTADOS.find(e => e[0] === k) || REP_ESTADOS[0]; }
  function repDias(r) { try { return Math.max(0, Math.floor((Date.now() - new Date(r.created_at).getTime()) / 86400000)); } catch (e) { return 0; } }
  // Garantía de la reparación (no del equipo): vive en r.garantia_hasta (fecha), se calcula UNA vez
  // al entregar según los días configurados en Ajustes — nunca se recalcula sola después.
  function garantiaInfo(r) {
    if (!r.garantia_hasta) return null;
    const hoyK = hoyISOPos();
    const vigente = String(r.garantia_hasta).slice(0, 10) >= hoyK;
    const fFmt = String(r.garantia_hasta).slice(0, 10).split('-').reverse().join('/');
    return { vigente: vigente, fecha: fFmt };
  }
  // NPGS §5: lupa colapsada. Las tarjetas son <button>, no <tr> — nbfContar sí sabe
  // excluir por offsetParent en ese caso, así que cont: funcionaría bien para UNA sola
  // columna; pero el kanban reparte las tarjetas en varias columnas por estado sin un
  // contenedor único que las agrupe todas — se deja sin cont: (mismo "Buscando…" honesto
  // que Inventario/Productos) en vez de contar solo la primera columna.
  function pintarLupaRep() {
    const box = document.getElementById('repQLupa');
    if (!box || typeof nxBuscaInlineHTML !== 'function') return;
    if (document.getElementById('nbiIn_repQ')) return; // no reconstruir a mitad de escritura
    box.innerHTML = nxBuscaInlineHTML({
      id: 'repQ',
      placeholder: 'Cliente, equipo, IMEI o número…',
      onterm: function (v) { window.nxRepBuscar(v); }
    });
  }
  function renderReparaciones() {
    nxPfEnsureCSS();
    const activas = _reps.filter(r => r.estado !== 'entregado' && r.estado !== 'cancelado');
    const vistaLista = _repVista === 'entregadas' ? _reps.filter(r => r.estado === 'entregado') : activas;
    const cols = REP_ESTADOS.filter(e => e[0] !== 'entregado').map(e => {
      const cards = activas.filter(r => r.estado === e[0]).map(r => {
        const d = repDias(r);
        return `<button type="button" class="nxRepCard" data-busca="${esc(((r.cliente_nombre || '') + ' ' + (r.equipo || '') + ' ' + (r.imei || '') + ' ' + (r.numero || '')).toLowerCase())}" onclick="window.nxRepVer('${r.id}')">
          <div class="nxRepNum">${esc(r.numero || '')}<span>${d} día${d === 1 ? '' : 's'}</span></div>
          <div class="nxRepEq">${esc(r.equipo || '')}${claveDisplayHTML(r.clave) ? ' <i class="ti ti-lock" style="color:#94a3b8;font-size:11px" title="Tiene clave/patrón guardado"></i>' : ''}</div>
          <div class="nxRepCli">${esc(r.cliente_nombre || '')}</div>
          <div class="nxRepFalla">${esc((r.falla || '').slice(0, 60))}</div>
          ${Number(r.presupuesto || 0) > 0 ? `<div class="nxRepPre">${fmt(r.presupuesto)}</div>` : ''}
        </button>`;
      }).join('');
      return `<div class="nxRepCol"><div class="nxRepColH" style="--rc:${e[2]}"><span>${e[1]}</span><b>${activas.filter(r => r.estado === e[0]).length}</b></div>${cards || '<div class="nxRepEmpty">—</div>'}</div>`;
    }).join('');
    const entregadasHTML = _repVista === 'entregadas'
      ? (vistaLista.length ? vistaLista.slice(0, 40).map(r => { const g = garantiaInfo(r); return `<div class="nxMdRow" style="cursor:pointer" onclick="window.nxRepVer('${r.id}')" tabindex="0" onkeydown="if(event.keyCode==13||event.keyCode==32){event.preventDefault();this.click()}" role="button"><div style="flex:1;min-width:0"><div class="nxMdNom">${esc(r.equipo)} · ${esc(r.numero || '')}</div><div class="nxMdSub">${esc(r.cliente_nombre || '')} · entregado ${String(r.entregado_at || '').slice(0, 10)}${g ? ` · <span style="color:${g.vigente ? '#16a34a' : '#dc2626'};font-weight:700">garantía ${g.vigente ? 'hasta ' + g.fecha : 'vencida'}</span>` : ''}</div></div><b>${fmt(r.cobrado_monto || 0)}</b></div>`; }).join('') : '<div class="nxRepEmpty" style="padding:20px">Sin entregadas</div>')
      : '';
    return `<div class="nxPf nxRepWrapK"><div style="margin-bottom:8px"><span id="repQLupa"></span></div>
      <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px;align-items:center">
        <button class="btn bc1" type="button" onclick="window.nxRepNueva()"><i class="ti ti-plus"></i> Recibir equipo</button>
        <div class="nxInvPills" style="margin:0">
          <button type="button" class="nxInvPill${_repVista !== 'entregadas' ? ' on' : ''}" onclick="window.nxRepVista('activas')">En taller <span>${activas.length}</span></button>
          <button type="button" class="nxInvPill${_repVista === 'entregadas' ? ' on' : ''}" onclick="window.nxRepVista('entregadas')">Entregadas</button>
        </div>
      </div>
      ${_repVista === 'entregadas' ? entregadasHTML : `<div class="nxRepKb">${cols}</div>`}</div>`;
  }
  window.nxRepBuscar = function (q) {
    const ql = String(q || '').trim().toLowerCase();
    document.querySelectorAll('.nxRepCard[data-busca]').forEach(c => { c.style.display = (!ql || (c.getAttribute('data-busca') || '').includes(ql)) ? '' : 'none'; });
  };
  window.nxRepVista = function (v) { _repVista = v; const el = document.getElementById('v-pos'); if (el) renderPOS(el); };
  // Resumen estimado en vivo del formulario de recepción (Presupuesto − Avance = Falta)
  window.nxRepEstim = function (preId, aboId, boxId) {
    preId = preId || 'repPre'; aboId = aboId || 'repAbo'; boxId = boxId || 'nxRepEstimBox';
    const box = document.getElementById(boxId); if (!box) return;
    const pre = moneyVal(preId), abo = moneyVal(aboId); const falta = Math.max(0, pre - abo);
    box.innerHTML = `<div class="nxRepEstR"><span>Presupuesto</span><b>${fmt(pre)}</b></div>
      <div class="nxRepEstR"><span>Avance recibido</span><b style="color:var(--pf-green)">${fmt(abo)}</b></div>
      <div class="nxRepEstR nxRepEstT"><span>Falta por cobrar</span><b style="color:${falta > 0 ? 'var(--pf-orange)' : 'var(--pf-green)'}">${fmt(falta)}</b></div>`;
  };
  window.nxRepNueva = function () {
    nxPfEnsureCSS();
    cerrarModal('nxRepM');
    const ov = document.createElement('div'); ov.id = 'nxRepM'; ov.className = 'overlay open';
    ov.addEventListener('click', e => { if (e.target === ov) ov.remove(); });
    const flow = REP_ESTADOS.map((e, i) => `<div class="nxRepFlowStep${i === 0 ? ' on' : ''}"><span class="dot">${i + 1}</span><span class="lb">${e[1]}</span></div>`).join('');
    ov.innerHTML = `<div class="modal nxPf" style="max-width:480px;max-height:92vh;display:flex;flex-direction:column;padding:0;border-radius:18px;overflow:hidden">
      <div class="head">
        <button class="nxBack" type="button" onclick="document.getElementById('nxRepM').remove()" title="Volver" aria-label="Volver"><i class="ti ti-arrow-left"></i></button>
        <h3><i class="ti ti-tool"></i> Recibir equipo</h3>
      </div>
      <div style="overflow-y:auto;flex:1;padding:14px;display:flex;flex-direction:column;gap:12px">
        <div class="nxRepFlow">${flow}</div>
        <div class="card">
          <h4><span class="bdg blue"><i class="ti ti-user"></i></span> Cliente</h4>
          <div class="g2">
            <div class="fld"><label>Nombre *</label><div class="inw"><i class="ti ti-user"></i><input id="repCli" class="no-upper" placeholder="Nombre del cliente"></div></div>
            <div class="fld"><label>Teléfono</label><div class="inw"><i class="ti ti-phone"></i><input id="repTel" class="no-upper" inputmode="tel" placeholder="809-000-0000"></div></div>
          </div>
        </div>
        <div class="card">
          <h4><span class="bdg purple"><i class="ti ti-device-mobile"></i></span> Equipo</h4>
          <div class="g2">
            <div class="fld"><label>Equipo *</label><div class="inw"><i class="ti ti-device-mobile"></i><input id="repEq" class="no-upper" placeholder="iPhone 12, Samsung A54..."></div></div>
            <div class="fld"><label>IMEI / Serie (opcional)</label><div class="inw"><i class="ti ti-scan-eye"></i><input id="repImei" class="no-upper" placeholder="Opcional"></div></div>
          </div>
          <div class="fld" style="margin-top:10px"><label>Falla que reporta *</label><div class="inw"><i class="ti ti-alert-triangle"></i><input id="repFalla" class="no-upper" placeholder="No enciende, pantalla rota..."></div></div>
          <div class="g2" style="margin-top:10px">
            <div class="fld"><label>Estado físico</label><div class="inw"><i class="ti ti-clipboard-text"></i><input id="repFis" class="no-upper" placeholder="Rayado, tapa rota..."></div></div>
            <div class="fld"><label>Accesorios que deja</label><div class="inw"><i class="ti ti-plug"></i><input id="repAcc" class="no-upper" placeholder="Cargador, forro..."></div></div>
          </div>
          <div class="fld" style="margin-top:10px"><label>Clave / patrón del equipo</label>${claveCapturaHTML('repNueva', '')}</div>
        </div>
        <div class="card">
          <h4><span class="bdg green"><i class="ti ti-cash"></i></span> Presupuesto</h4>
          <div class="g2">
            <div class="fld"><label>Presupuesto RD$</label><div class="inw"><span class="cur">$</span><input id="repPre" data-nx-money inputmode="numeric" placeholder="0" style="padding-left:24px" oninput="window.nxRepEstim()"></div></div>
            <div class="fld"><label>Avance RD$</label><div class="inw"><span class="cur">$</span><input id="repAbo" data-nx-money inputmode="numeric" placeholder="0" style="padding-left:24px" oninput="window.nxRepEstim()"></div></div>
          </div>
          <div class="fld" style="margin-top:10px"><label>Técnico</label><div class="inw"><i class="ti ti-user-cog"></i><input id="repTec" class="no-upper" placeholder="Quién repara"></div></div>
          <div class="nxRepEstim" id="nxRepEstimBox" style="margin-top:10px"></div>
        </div>
      </div>
      <div class="actions" style="margin-top:0;grid-template-columns:1fr 1fr 1fr">
        <button class="ab g3" type="button" onclick="document.getElementById('nxRepM').remove()">Cancelar</button>
        <button class="ab g2" type="button" onclick="window.nxRepGuardar(true)"><i class="ti ti-printer"></i> Guardar e imprimir</button>
        <button class="ab g1" type="button" onclick="window.nxRepGuardar()"><i class="ti ti-check"></i> Guardar</button>
      </div>
    </div>`;
    document.body.appendChild(ov); scanMoney(ov); window.nxRepEstim();
  };
  window.nxRepGuardar = async function (imprimir) {
    const cli = val('repCli').trim(), eq = val('repEq').trim(), falla = val('repFalla').trim();
    if (!cli || !eq || !falla) { toast('err', 'Faltan datos', 'Cliente, equipo y falla son obligatorios'); return; }
    const abono = moneyVal('repAbo');
    // REGLAMENTO DEL TALLER: el avance al recibir un equipo es efectivo (entra al arqueo), así que
    // exige caja abierta — mismo candado del §2/§3. Sin avance no estorba.
    if (abono > 0 && !(_caja && _caja.id)) {
      try { const _cj = await getAPI().get('pos_cajas', 'select=*&estado=eq.abierta&order=apertura.desc&limit=1'); _caja = (_cj && _cj[0]) || null; } catch (e) {}
      if (!(_caja && _caja.id)) { toast('err', 'La caja está cerrada', 'Ábrela en Caja antes de recibir el avance de ' + fmt(abono) + ', o recibe el equipo sin avance.'); return; }
    }
    let numero = null; try { numero = await nextSeq('reparacion'); } catch (e) {}
    if (!numero) numero = 'REP-' + String((_reps.length + 1)).padStart(5, '0');
    const d = { numero: numero, cliente_nombre: cli.toUpperCase(), cliente_telefono: val('repTel').trim() || null, equipo: eq, imei: val('repImei').trim() || null, falla: falla, estado_fisico: val('repFis').trim() || null, clave: nxClaveValor('repNueva') || null, accesorios: val('repAcc').trim() || null, presupuesto: moneyVal('repPre'), abono: abono, tecnico: val('repTec').trim() || null, estado: 'recibido' };
    try {
      const r = await getAPI().post('pos_reparaciones', d);
      const rep = (r && r[0]) || d;
      _reps.unshift(rep);
      if (abono > 0 && _caja) { try { await getAPI().post('pos_caja_movimientos', { caja_id: _caja.id, tipo: 'entrada', monto: abono, concepto: 'Avance reparación ' + numero + ' · ' + d.cliente_nombre, fecha: new Date().toISOString() }); } catch (e) {} }
      if (abono > 0) { try { await postAsientoServicio('Avance reparación ' + numero + ' · ' + d.cliente_nombre, abono, 'Efectivo', rep.id || null); } catch (e) {} }
      try { window.logAudit && window.logAudit('REP_RECIBIDA', numero + ' · ' + eq + ' · ' + d.cliente_nombre, 'Reparaciones'); } catch (e) {}
      cerrarModal('nxRepM'); toast('ok', 'Equipo recibido', numero);
      if (imprimir) window.nxRepImprimir(rep.id || null, rep);
      const el = document.getElementById('v-pos'); if (el) renderPOS(el);
    } catch (e) { toast('err', 'No se pudo guardar', String(e && e.message || e)); }
  };
  window.nxRepVer = function (id) {
    nxPfEnsureCSS();
    const r = _reps.find(x => String(x.id) === String(id)); if (!r) return;
    cerrarModal('nxRepM');
    const est = repEst(r.estado);
    const idx = REP_ESTADOS.findIndex(e => e[0] === r.estado);
    const flow = REP_ESTADOS.map((e, i) => `<div class="nxRepFlowStep${idx >= 0 && i <= idx ? ' on' : ''}"><span class="dot">${i + 1}</span><span class="lb">${e[1]}</span></div>`).join('');
    const chips = REP_ESTADOS.map(e => `<button type="button" class="nxRepChip${r.estado === e[0] ? ' on' : ''}" style="--rc:${e[2]}" onclick="window.nxRepEstado('${r.id}','${e[0]}')">${e[1]}</button>`).join('');
    const telW = String(r.cliente_telefono || '').replace(/\D/g, '');
    const msg = 'Hola ' + (r.cliente_nombre || '') + ', su equipo ' + (r.equipo || '') + ' (' + (r.numero || '') + ') está: ' + est[1].toUpperCase() + (r.estado === 'listo' ? '. ¡Ya puede pasar a recogerlo!' : '.') + (Number(r.presupuesto || 0) > 0 ? ' Presupuesto: ' + fmt(r.presupuesto) + (Number(r.abono || 0) > 0 ? ' (avance ' + fmt(r.abono) + ')' : '') : '');
    const gi = garantiaInfo(r);
    const ov = document.createElement('div'); ov.id = 'nxRepM'; ov.className = 'overlay open';
    ov.addEventListener('click', e => { if (e.target === ov) ov.remove(); });
    ov.innerHTML = `<div class="modal nxPf" style="max-width:480px;max-height:92vh;display:flex;flex-direction:column;padding:0;border-radius:18px;overflow:hidden">
      <div class="head">
        <button class="nxBack" type="button" onclick="document.getElementById('nxRepM').remove()" title="Volver" aria-label="Volver"><i class="ti ti-arrow-left"></i></button>
        <h3><i class="ti ti-tool"></i> ${esc(r.numero || 'Reparación')}</h3>
        <span class="bdg2" style="background:${est[2]}22;color:${est[2]}">${est[1]}</span>
      </div>
      <div style="overflow-y:auto;flex:1;padding:14px;display:flex;flex-direction:column;gap:12px">
        <div class="nxRepFlow">${flow}</div>
        <div class="card">
          <h4><span class="bdg blue"><i class="ti ti-device-mobile"></i></span> ${esc(r.equipo)}</h4>
          <div style="font-size:11.5px;color:var(--pf-txt2)">${esc(r.cliente_nombre || '')}${r.cliente_telefono ? ' · ' + esc(r.cliente_telefono) : ''}${r.imei ? ' · IMEI ' + esc(r.imei) : ''}</div>
          <div style="font-size:11.5px;color:var(--pf-txt3);margin-top:2px">Recibido hace ${repDias(r)} día(s)${r.tecnico ? ' · Téc: ' + esc(r.tecnico) : ''}</div>
          <div style="background:var(--pf-orange-l);border:1px solid var(--pf-orange);border-radius:10px;padding:8px 10px;margin-top:8px;font-size:12px;color:var(--pf-txt2)"><b style="color:var(--pf-orange)">Falla:</b> ${esc(r.falla || '')}${r.estado_fisico ? '<br><b style="color:var(--pf-orange)">Físico:</b> ' + esc(r.estado_fisico) : ''}${r.accesorios ? '<br><b style="color:var(--pf-orange)">Dejó:</b> ' + esc(r.accesorios) : ''}</div>
        </div>
        <div class="card">
          <h4><span class="bdg purple"><i class="ti ti-progress"></i></span> Estado <span style="font-weight:600;color:var(--pf-txt3);font-size:11px">(toca para mover)</span></h4>
          <div class="nxRepChips">${chips}</div>
        </div>
        <div class="card">
          <h4><span class="bdg blue"><i class="ti ti-clipboard-text"></i></span> Diagnóstico</h4>
          <div class="fld"><label>Diagnóstico / trabajo hecho</label><textarea id="repDiag" rows="2" class="no-upper" placeholder="Qué se encontró, qué se hizo...">${esc(r.diagnostico || '')}</textarea></div>
          <div class="fld" style="margin-top:10px"><label>Clave / patrón del equipo</label>${claveCapturaHTML('repEdit_' + r.id, r.clave || '')}</div>
        </div>
        <div class="card">
          <h4><span class="bdg green"><i class="ti ti-cash"></i></span> Presupuesto</h4>
          <div class="g2">
            <div class="fld"><label>Presupuesto RD$</label><div class="inw"><span class="cur">$</span><input id="repPre2" data-nx-money inputmode="numeric" style="padding-left:24px" oninput="window.nxRepEstim('repPre2','repAbo2','nxRepEstimBox2')" value="${Number(r.presupuesto || 0) ? Math.round(r.presupuesto).toLocaleString('en-US') : ''}"></div></div>
            <div class="fld"><label>Avance RD$</label><div class="inw"><span class="cur">$</span><input id="repAbo2" data-nx-money inputmode="numeric" style="padding-left:24px" oninput="window.nxRepEstim('repPre2','repAbo2','nxRepEstimBox2')" value="${Number(r.abono || 0) ? Math.round(r.abono).toLocaleString('en-US') : ''}"></div></div>
          </div>
          ${r.estado !== 'entregado' ? `<div class="nxRepEstim" id="nxRepEstimBox2" style="margin-top:10px"></div>${_posCfg.garantia_rep_dias > 0 ? `<div style="margin-top:8px;font-size:11.5px;color:var(--pf-txt3)">Al entregar se le darán ${_posCfg.garantia_rep_dias} día(s) de garantía.</div>` : ''}` : `<div style="margin-top:10px;font-size:12px;color:var(--pf-green);font-weight:800">✓ Entregado ${String(r.entregado_at || '').slice(0, 10)} · Cobrado ${fmt(r.cobrado_monto || 0)}</div>${gi ? `<div style="margin-top:6px;font-size:12px;font-weight:700;color:${gi.vigente ? 'var(--pf-green)' : 'var(--pf-red)'}"><i class="ti ti-shield-check"></i> Garantía ${gi.vigente ? 'vigente hasta' : 'vencida el'} ${gi.fecha}</div>` : ''}`}
        </div>
      </div>
      <div style="padding:12px 14px;border-top:1px solid var(--pf-line);display:flex;gap:6px;flex-wrap:wrap">
        ${telW ? `<a class="ab sm g3" style="color:var(--pf-green);flex:1 1 auto" href="https://wa.me/1${telW}?text=${encodeURIComponent(msg)}" target="_blank"><i class="ti ti-brand-whatsapp"></i> Avisar</a>` : ''}
        <button class="ab sm g3" style="flex:1 1 auto" type="button" onclick="window.nxRepImprimir('${r.id}')"><i class="ti ti-printer"></i> Orden</button>
        <button class="ab sm g2" style="flex:1 1 auto" type="button" onclick="window.nxRepDet('${r.id}')"><i class="ti ti-device-floppy"></i> Guardar</button>
        ${r.estado !== 'entregado' ? `<button class="ab sm g1" style="flex:1 1 auto" type="button" onclick="window.nxRepEntregar('${r.id}')"><i class="ti ti-check"></i> Entregar y cobrar</button>` : ''}
      </div>
    </div>`;
    document.body.appendChild(ov); scanMoney(ov); window.nxRepEstim('repPre2', 'repAbo2', 'nxRepEstimBox2');
  };
  window.nxRepEstado = async function (id, est) {
    const r = _reps.find(x => String(x.id) === String(id)); if (!r) return;
    if (est === 'entregado') { window.nxRepEntregar(id); return; }
    try { await getAPI().patch('pos_reparaciones', 'id=eq.' + id, { estado: est }); r.estado = est; const el = document.getElementById('v-pos'); if (el && _posTab === 'reparaciones') renderPOS(el); window.nxRepVer(id); try { window.logAudit && window.logAudit('REP_ESTADO', (r.numero || '') + ' → ' + est, 'Reparaciones'); } catch (e2) {} } catch (e) { toast('err', 'Error', String(e && e.message || e)); }
  };
  window.nxRepDet = async function (id) {
    const r = _reps.find(x => String(x.id) === String(id)); if (!r) return;
    const d = { diagnostico: val('repDiag').trim() || null, presupuesto: moneyVal('repPre2'), abono: moneyVal('repAbo2'), clave: nxClaveValor('repEdit_' + id) || null };
    try { await getAPI().patch('pos_reparaciones', 'id=eq.' + id, d); Object.assign(r, d); toast('ok', 'Guardado'); } catch (e) { toast('err', 'Error', String(e && e.message || e)); }
  };
  window.nxRepEntregar = function (id) {
    const r = _reps.find(x => String(x.id) === String(id)); if (!r) return;
    const resto = Math.max(0, Number(r.presupuesto || 0) - Number(r.abono || 0));
    cerrarModal('nxRepM'); cerrarModal('nxRepEnt');
    const ov = document.createElement('div'); ov.id = 'nxRepEnt'; ov.className = 'overlay open';
    ov.addEventListener('click', e => { if (e.target === ov) ov.remove(); });
    ov.innerHTML = `<div class="modal nxPrForm" style="max-width:400px">
      <div class="mt"><span><i class="ti ti-check"></i> Entregar y cobrar</span><button class="nxBack" type="button" onclick="document.getElementById('nxRepEnt').remove()"><i class="ti ti-arrow-left"></i> Volver</button></div>
      <div style="font-size:11.5px;color:#475569;margin-bottom:8px">${esc(r.equipo || '')} · ${esc(r.cliente_nombre || '')} · resta <b style="color:#dc2626">${fmt(resto)}</b></div>
      <div class="fr-row"><div class="fr"><label>Monto a cobrar</label><input id="reMonto" data-nx-money inputmode="numeric" value="${Math.round(resto).toLocaleString('en-US')}"></div>
      <div class="fr"><label>Método</label><select id="reMet"><option>Efectivo</option><option>Transferencia</option><option>Tarjeta</option></select></div></div>
      <div class="fr" style="margin-top:2px"><label style="display:flex;align-items:center;gap:8px;cursor:pointer;font-weight:600"><input type="checkbox" id="reItbis" style="width:17px;height:17px"> ¿Esta reparación lleva ITBIS (18%)?</label></div>
      <div class="fe" style="margin-top:10px"><button class="btn bc1" type="button" onclick="window.nxRepEntregarGo('${id}')"><i class="ti ti-check"></i> Entregar equipo</button></div>
    </div>`;
    document.body.appendChild(ov); scanMoney(ov);
  };
  window.nxRepEntregarGo = async function (id) {
    const r = _reps.find(x => String(x.id) === String(id)); if (!r) return;
    const monto = moneyVal('reMonto'); const metodo = val('reMet') || 'Efectivo';
    if (monto > 0) {
      // Antes de aquí, "Entregar y cobrar" cerraba el ciclo solo (asiento contable +
      // movimiento de caja) SIN pasar por Factura — el dinero quedaba en caja/contabilidad
      // pero sin NCF, invisible para la DGII y ausente de la lista de Facturas (confirmado
      // en vivo, 20-ago-2026). Ahora, si hay algo real que cobrar, se carga como una línea
      // de servicio en el carrito y se manda a Factura — el mismo camino ya probado que usan
      // Cotizaciones y Prefacturas para convertirse en venta real (nxCotConvertir/
      // nxPrefFacturar): el cajero elige el tipo de comprobante y completa el cobro ahí, con
      // caja/NCF/contabilidad/inventario resueltos por el código de venta de siempre. Cuando
      // esa venta se complete, el gancho de abajo (checkout, _facOrigenReparacion) termina de
      // marcar la reparación como entregada. Si el cajero cancela en Factura, la reparación
      // se queda tal cual — no se pierde nada, solo no se completó el cobro.
      if (_cart.length && !confirm('El cuadro de Factura ya tiene artículos. ¿Reemplazarlos para cobrar esta reparación?')) return;
      let servId; try { servId = await repServicioProductoId(); } catch (e) { toast('err', 'No se pudo preparar el cobro', String(e && e.message || e)); return; }
      const conItbis = !!(document.getElementById('reItbis') || {}).checked;
      _cart = [{ producto_id: servId, nombre: 'Reparación ' + (r.numero || '') + ' — ' + (r.equipo || ''), precio: Math.round(monto), cantidad: 1, itbis: conItbis, desc: 0, descT: 'pct' }];
      _factCli = '';
      _facOrigenReparacion = { id: id, abono: Number(r.abono || 0) };
      cerrarModal('nxRepEnt'); cerrarModal('nxRepM');
      window.nxPosTab('factura');
      toast('ok', 'Reparación cargada', 'Completa el cobro en Factura');
      return;
    }
    // Nada nuevo que cobrar (ya estaba saldada por el avance) — se entrega sin pasar por
    // Factura, como siempre; no tiene sentido generar una factura de RD$0.
    try {
      const d = { estado: 'entregado', cobrado: true, cobrado_monto: Number(r.abono || 0), cobrado_metodo: metodo, entregado_at: new Date().toISOString() };
      if (_posCfg.garantia_rep_dias > 0) { const gh = new Date(); gh.setDate(gh.getDate() + Number(_posCfg.garantia_rep_dias)); d.garantia_hasta = gh.getFullYear() + '-' + String(gh.getMonth() + 1).padStart(2, '0') + '-' + String(gh.getDate()).padStart(2, '0'); }
      await getAPI().patch('pos_reparaciones', 'id=eq.' + id, d); Object.assign(r, d);
      try { window.logAudit && window.logAudit('REP_ENTREGADA', (r.numero || '') + ' · ' + (r.equipo || '') + ' · sin cobro pendiente', 'Reparaciones'); } catch (e) {}
      cerrarModal('nxRepEnt'); toast('ok', 'Entregado', r.numero || '');
      const el = document.getElementById('v-pos'); if (el) renderPOS(el);
    } catch (e) { toast('err', 'Error', String(e && e.message || e)); }
  };
  window.nxRepImprimir = function (id, repObj) {
    const r = repObj || _reps.find(x => String(x.id) === String(id)); if (!r) return;
    const _s = curSesPOS(); const biz = (_s && _s.org && _s.org.nombre) || empNom() || 'Mi negocio';
    const w = window.open('', '_blank'); if (!w) { toast('warn', 'Permite las ventanas emergentes'); return; }
    const f = (l, v) => v ? `<tr><td style="color:#64748b;white-space:nowrap;padding:4px 8px 4px 0">${l}</td><td style="font-weight:700">${esc(v)}</td></tr>` : '';
    const g = garantiaInfo(r);
    const garantiaLinea = g ? `<div style="margin-top:6px;font-size:12px;font-weight:700;color:${g.vigente ? '#166534' : '#991b1b'}">Garantía de esta reparación ${g.vigente ? 'hasta' : 'vencida el'} ${g.fecha}</div>` : (r.estado !== 'entregado' && _posCfg.garantia_rep_dias > 0 ? `<div style="margin-top:6px;font-size:11px;color:#64748b">Esta reparación incluye ${_posCfg.garantia_rep_dias} día(s) de garantía a partir de la entrega.</div>` : '');
    const claveHTML = claveImprimirHTML(r.clave);
    const claveLinea = claveHTML ? `<div style="margin-top:8px"><div style="color:#64748b;font-size:11px;font-weight:600">Clave / patrón del equipo</div>${claveHTML}</div>` : '';
    w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(r.numero || 'Orden')}</title><style>body{font-family:Segoe UI,system-ui,-apple-system,sans-serif;padding:24px;color:#1e293b;max-width:520px;margin:0 auto;font-size:13px}h1{font-size:16px;margin:0;color:#1e3a8a}h2{font-size:13px;margin:2px 0 12px;color:#64748b;font-weight:600}table{width:100%;border-collapse:collapse;font-size:12.5px}.tot{margin-top:10px;border-top:2px solid #1e3a8a;padding-top:8px;font-size:13px}.leg{margin-top:14px;font-size:10px;color:#64748b;border-top:1px dashed #cbd5e1;padding-top:8px}.fir{margin-top:44px;display:flex;justify-content:space-between;gap:20px;text-align:center;font-size:11px}.fir div{flex:1;border-top:1px solid #1e293b;padding-top:4px}</style></head><body>
      <h1>${esc(biz)}</h1><h2>ORDEN DE SERVICIO · ${esc(r.numero || '')} · ${new Date().toLocaleDateString('es-DO')}</h2>
      <table>${f('Cliente', r.cliente_nombre)}${f('Teléfono', r.cliente_telefono)}${f('Equipo', r.equipo)}${f('IMEI / Serie', r.imei)}${f('Falla reportada', r.falla)}${f('Estado físico', r.estado_fisico)}${f('Accesorios', r.accesorios)}${f('Técnico', r.tecnico)}</table>
      ${claveLinea}
      <div class="tot">Presupuesto: <b>${fmt(r.presupuesto || 0)}</b> · Avance: <b>${fmt(r.abono || 0)}</b> · Resta: <b>${fmt(Math.max(0, Number(r.presupuesto || 0) - Number(r.abono || 0)))}</b></div>
      ${garantiaLinea}
      <div class="leg">El presupuesto puede variar según el diagnóstico final (se le avisará antes de proceder). Equipos no retirados en 30 días luego de estar listos generan cargo de almacenaje y a los 90 días se consideran abandonados. No respondemos por datos: respalde su información.</div>
      <div class="fir"><div>Recibido por</div><div>Firma del cliente</div></div>
      <script>window.print();</` + `script></body></html>`);
    w.document.close();
  };

  // ══════════════ CUOTAS / FINANCIAMIENTOS ══════════════
  function cuotasDe(finId) { return _finCuotas.filter(c => String(c.financiamiento_id) === String(finId)).sort((a, b) => a.numero - b.numero); }
  // Recargo por mora: % configurable por el dueño (Ajustes), UNA sola vez por cuota vencida (no
  // se acumula por día), después de los días de gracia que él defina. 0% = mora desactivada.
  // Se calcula EN VIVO (nunca se guarda), igual que el resto de estados calculados de este módulo.
  function moraDeCuota(c) {
    if (!_posCfg.mora_pct || c.pagado) return 0;
    const hoyK = hoyISOPos();
    const venc = String(c.fecha_venc || '').slice(0, 10);
    if (!venc || venc >= hoyK) return 0;
    const diasAtraso = Math.floor((new Date(hoyK + 'T12:00:00') - new Date(venc + 'T12:00:00')) / 86400000);
    if (diasAtraso <= Number(_posCfg.mora_dias_gracia || 0)) return 0;
    return Math.round(Number(c.monto || 0) * Number(_posCfg.mora_pct || 0) / 100);
  }
  // Recalcula monto_pagado/pagado de CADA cuota sumando pos_fin_pagos (la fuente de verdad es el
  // ledger, nunca el booleano solo) — se corre después de cargar y después de cada pago nuevo.
  function resyncCuotasPagos() {
    const porCuota = {};
    (_finPagos || []).forEach(p => { const k = String(p.cuota_id); porCuota[k] = (porCuota[k] || 0) + Number(p.monto || 0); });
    (_finCuotas || []).forEach(c => { c.monto_pagado = porCuota[String(c.id)] || 0; c.pagado = c.monto_pagado >= Number(c.monto || 0) - 0.01; });
  }
  function hoyISOPos() { const d = new Date(); return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0'); }
  function curSesPOS() { try { return (typeof sesion !== 'undefined') ? sesion : window.sesion; } catch (e) { return null; } }

  // ════════════════════════════════════════════════════════════════════
  // ── CUOTAS PREMIUM (rediseño v48.16, a pedido del dueño — mismo motor,
  //    solo interfaz nueva) — helpers de cálculo/clasificación ──
  // ════════════════════════════════════════════════════════════════════
  function pendPlan(f) { return cuotasDe(f.id).filter(c => !c.pagado).reduce((s, c) => s + Math.max(0, Number(c.monto || 0) - Number(c.monto_pagado || 0)), 0); }
  function moraPlan(f) { return cuotasDe(f.id).filter(c => !c.pagado).reduce((s, c) => s + moraDeCuota(c), 0); }
  function diasAtraso(c) {
    const hoyK = hoyISOPos(); const venc = String(c.fecha_venc || '').slice(0, 10);
    if (!venc || venc >= hoyK) return 0;
    return Math.floor((new Date(hoyK + 'T12:00:00') - new Date(venc + 'T12:00:00')) / 86400000);
  }
  // REGLAMENTO DE CRÉDITO Y COBRANZA: ¿este cliente ya está atrasado en alguna cuota de un plan
  // activo? Devuelve {n, monto} (cuotas vencidas + su pendiente con mora) o null si está al día.
  // Sirve para decidir si se le puede fiar más (ver nxPosConfirmar).
  function clienteConCuotaVencida(cliId) {
    if (!cliId) return null;
    let n = 0, monto = 0;
    (_fins || []).filter(f => f.estado === 'activo' && String(f.cliente_id) === String(cliId)).forEach(f => {
      cuotasDe(f.id).filter(c => !c.pagado && diasAtraso(c) > 0).forEach(c => {
        n++; monto += Math.max(0, Number(c.monto || 0) - Number(c.monto_pagado || 0)) + moraDeCuota(c);
      });
    });
    return n ? { n: n, monto: monto } : null;
  }
  function finClienteInfo(f) { const c = f.cliente_id ? _clientes.find(x => String(x.id) === String(f.cliente_id)) : null; return { cedula: (c && c.cedula) || '', telefono: (c && c.telefono) || '' }; }
  // Referencia corta derivada del id del plan (NO es un consecutivo — pos_financiamientos no tiene
  // numeración propia; se deriva del id ya existente para no tocar Supabase/esquema/lógica).
  function finRefCorta(f) { return 'PR-' + String(f.id || '').replace(/-/g, '').slice(0, 6).toUpperCase(); }
  const FIN_AVATAR_COLORES = ['#4f46e5', '#7c3aed', '#0891b2', '#059669', '#d97706', '#dc2626', '#db2777', '#0284c7'];
  function finIniciales(nombre) {
    const partes = String(nombre || '').trim().split(/\s+/).filter(Boolean);
    const ini = partes.length ? (partes[0][0] + (partes[1] ? partes[1][0] : '')).toUpperCase() : '—';
    let hash = 0; const s = String(nombre || ''); for (let i = 0; i < s.length; i++) hash = (hash * 31 + s.charCodeAt(i)) >>> 0;
    return { ini: ini, color: FIN_AVATAR_COLORES[hash % FIN_AVATAR_COLORES.length] };
  }
  // Clasificación real (5 estados, todos calculados en vivo de datos reales — nada inventado):
  // activo = al día · vencido = atrasado pero AÚN dentro del período de gracia (sin recargo) ·
  // en_mora = atrasado más allá de la gracia (ya generando recargo real) · pagado · cancelado.
  function finEstado(f) {
    if (f.estado === 'cancelado') return { key: 'cancelado', label: 'CANCELADO' };
    if (f.estado === 'saldado') return { key: 'pagado', label: 'PAGADO' };
    const vencidasPlan = cuotasDe(f.id).filter(c => !c.pagado && diasAtraso(c) > 0);
    if (!vencidasPlan.length) return { key: 'activo', label: 'ACTIVO' };
    return vencidasPlan.some(c => moraDeCuota(c) > 0) ? { key: 'en_mora', label: 'EN MORA' } : { key: 'vencido', label: 'VENCIDO' };
  }
  function finHeroStats() {
    const activos = _fins.filter(f => f.estado === 'activo');
    const prestado = _fins.filter(f => f.estado !== 'cancelado').reduce((s, f) => s + Number(f.monto_financiado || 0), 0);
    const cobrado = (_finPagos || []).reduce((s, p) => s + Number(p.monto || 0), 0);
    const porCobrar = activos.reduce((s, f) => s + pendPlan(f) + moraPlan(f), 0);
    const vencido = activos.reduce((s, f) => s + cuotasDe(f.id).filter(c => !c.pagado && diasAtraso(c) > 0).reduce((x, c) => x + Math.max(0, Number(c.monto || 0) - Number(c.monto_pagado || 0)) + moraDeCuota(c), 0), 0);
    const clientesActivos = new Set(activos.map(f => String(f.cliente_id || f.cliente_nombre))).size;
    return { prestado, cobrado, porCobrar, vencido, clientesActivos };
  }
  function finStatsMes() {
    const ym = hoyISOPos().slice(0, 7);
    const esperado = _finCuotas.filter(c => String(c.fecha_venc || '').slice(0, 7) === ym).reduce((s, c) => s + Number(c.monto || 0), 0);
    const cobradoMes = (_finPagos || []).filter(p => String(p.fecha || '').slice(0, 7) === ym).reduce((s, p) => s + Number(p.monto || 0), 0);
    const cobradoMesAnt = (_finPagos || []).filter(p => { const d = new Date(ym + '-01T12:00:00'); d.setMonth(d.getMonth() - 1); return String(p.fecha || '').slice(0, 7) === (d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0')); }).reduce((s, p) => s + Number(p.monto || 0), 0);
    const enMoraPlanes = _fins.filter(f => f.estado === 'activo' && cuotasDe(f.id).some(c => !c.pagado && diasAtraso(c) >= 31));
    const clientesNuevos = new Set(_fins.filter(f => String(f.created_at || '').slice(0, 7) === ym).map(f => String(f.cliente_id || f.cliente_nombre))).size;
    return { esperado: esperado, cobradoMes: cobradoMes, pctMes: esperado > 0 ? Math.round(cobradoMes / esperado * 100) : 0, tendencia: cobradoMesAnt > 0 ? Math.round((cobradoMes - cobradoMesAnt) / cobradoMesAnt * 100) : null, enMoraCount: enMoraPlanes.length, montoMora31: enMoraPlanes.reduce((s, f) => s + pendPlan(f), 0), clientesNuevos: clientesNuevos };
  }
  function finFiltrados() {
    const q = (_finQ || '').toLowerCase().trim();
    return _fins.filter(f => {
      const est = finEstado(f).key;
      if (_finFiltro === 'activos' && est !== 'activo') return false;
      if (_finFiltro === 'vencidos' && est !== 'vencido' && est !== 'en_mora') return false;
      if (_finFiltro === 'pagados' && est !== 'pagado') return false;
      if (_finFiltro === 'cancelados' && est !== 'cancelado') return false;
      if (!q) return true;
      const info = finClienteInfo(f);
      return [f.cliente_nombre, f.descripcion, info.cedula, info.telefono, finRefCorta(f)].join(' ').toLowerCase().includes(q);
    });
  }
  function finTabsHTML() {
    const conteo = key => _fins.filter(f => { const e = finEstado(f).key; return key === 'todos' ? true : key === 'vencidos' ? (e === 'vencido' || e === 'en_mora') : key === 'activos' ? e === 'activo' : key === 'pagados' ? e === 'pagado' : e === 'cancelado'; }).length;
    const tabs = [['todos', 'Todos', 'ti-layout-grid'], ['activos', 'Activos', 'ti-circle-check'], ['vencidos', 'Vencidos', 'ti-alert-triangle'], ['pagados', 'Pagados', 'ti-checks'], ['cancelados', 'Cancelados', 'ti-ban']];
    return tabs.map(t => `<button type="button" class="nxFP-tab ${_finFiltro === t[0] ? 'on' : ''}" onclick="window.nxFinFiltro('${t[0]}')"><i class="ti ${t[2]}"></i> ${t[1]} <span class="nxFP-tabN">${conteo(t[0])}</span></button>`).join('');
  }
  function finCardHTML(f) {
    const cs = cuotasDe(f.id); const pag = cs.filter(c => c.pagado).length;
    const prox = cs.find(c => !c.pagado);
    const est = finEstado(f); const av = finIniciales(f.cliente_nombre); const info = finClienteInfo(f);
    const balance = pendPlan(f); const atraso = prox ? diasAtraso(prox) : 0;
    const metaBits = [info.cedula, info.telefono].filter(Boolean).map(esc);
    return `<div class="nxFP-card">
      <div class="nxFP-avatar" style="background:${av.color}">${av.ini}</div>
      <div class="nxFP-cardBody">
        <div class="nxFP-cardTop"><div class="nxFP-cardNom">${esc(f.cliente_nombre || '')}</div><span class="nxFP-badge ${est.key}">${est.label}</span></div>
        <div class="nxFP-cardMeta">${metaBits.length ? metaBits.join(' · ') : 'Sin cédula/teléfono registrado'}</div>
        <div class="nxFP-refRow"><span class="nxFP-ref">REF: ${finRefCorta(f)}</span></div>
        <div class="nxFP-cardGrid">
          <div><div class="nxFP-gLbl">Monto prestado</div><div class="nxFP-gVal">${fmt(f.monto_financiado)}</div></div>
          <div><div class="nxFP-gLbl">Por cobrar</div><div class="nxFP-gVal ${balance > 0 ? 'accent' : ''}">${fmt(balance)}</div></div>
          <div><div class="nxFP-gLbl">Cuota mensual</div><div class="nxFP-gVal">${fmt(f.cuota_monto)}</div></div>
          <div>${est.key === 'pagado' ? `<div class="nxFP-gLbl">Estado</div><div class="nxFP-gVal">Completado</div>` : est.key === 'cancelado' ? `<div class="nxFP-gLbl">Estado</div><div class="nxFP-gVal">Anulado</div>` : prox ? `<div class="nxFP-gLbl">${atraso > 0 ? 'Días vencidos' : 'Próximo pago'}</div><div class="nxFP-gVal ${atraso > 0 ? 'danger' : ''}">${atraso > 0 ? atraso + ' días' : String(prox.fecha_venc).slice(0, 10)}</div></div>` : ''}</div>
        </div>
      </div>
      <div class="nxFP-cardMenuWrap" data-nbf-ignorar>
        <button type="button" class="nxFP-menuBtn" aria-label="Más opciones de ${esc(f.cliente_nombre || '')}" onclick="window.nxFinMenu(event,'${f.id}')"><i class="ti ti-dots-vertical"></i></button>
        <div class="nxFP-menuPop" id="finMenu_${f.id}">
          ${est.key !== 'pagado' && est.key !== 'cancelado' && prox ? `<button type="button" onclick="window.nxFinMenuGo(event,'${f.id}','pagar')"><i class="ti ti-cash"></i> Cobrar cuota</button>` : ''}
          <button type="button" onclick="window.nxFinMenuGo(event,'${f.id}','plan')"><i class="ti ti-list-numbers"></i> Ver plan</button>
          <button type="button" onclick="window.nxFinMenuGo(event,'${f.id}','imprimir')"><i class="ti ti-printer"></i> Imprimir acuerdo</button>
        </div>
      </div>
    </div>`;
  }
  function finListaHTML() {
    const lista = finFiltrados();
    if (!lista.length) {
      if (!_fins.length) return `<div class="nxFP-empty" data-nbf-ignorar><div class="nxFP-emptyIco"><i class="ti ti-file-off"></i></div><h3>Aún no hay préstamos</h3><p>Se crean al cobrar una venta marcando "Financiar el resto en CUOTAS".</p><button type="button" class="nxFP-qbtn" style="max-width:220px;margin:14px auto 0" onclick="window.nxFinNuevo()"><div class="nxFP-qico primary"><i class="ti ti-plus"></i></div><span>Nuevo préstamo</span></button></div>`;
      return `<div class="nxFP-empty" data-nbf-ignorar><div class="nxFP-emptyIco"><i class="ti ti-search-off"></i></div><h3>Nada por aquí</h3><p>Ningún préstamo coincide con este filtro o búsqueda.</p></div>`;
    }
    return lista.map(finCardHTML).join('');
  }
  function finRepintarLista() {
    const el = document.getElementById('finList'); if (el) el.innerHTML = finListaHTML();
    const lbl = document.getElementById('finTotalLbl'); if (lbl) lbl.textContent = 'Total: ' + finFiltrados().length + (finFiltrados().length === 1 ? ' préstamo' : ' préstamos');
  }
